function getSubjectMeta(subj) {
  const canon = canonicalSubjectName(subj);
  if (SUBJECT_METADATA[canon]) return SUBJECT_METADATA[canon];

  // Smart heuristic inference for custom/user-created subjects
  const lower = String(canon).toLowerCase();
  let icon = 'book-open';
  let color = '#6366f1';

  if (lower.includes('math') || lower.includes('গণিত') || lower.includes('অঙ্ক') || lower.includes('calcu')) {
    icon = 'calculator'; color = '#10b981';
  } else if (lower.includes('eng') || lower.includes('ইংরেজি') || lower.includes('vocab') || lower.includes('gram') || lower.includes('lang')) {
    icon = 'languages'; color = '#06b6d4';
  } else if (lower.includes('bang') || lower.includes('বাংলা') || lower.includes('সাহিত্য')) {
    icon = 'book-open'; color = '#ec4899';
  } else if (lower.includes('phys') || lower.includes('পদার্থ')) {
    icon = 'atom'; color = '#8b5cf6';
  } else if (lower.includes('chem') || lower.includes('রসায়ন')) {
    icon = 'flask-conical'; color = '#14b8a6';
  } else if (lower.includes('bio') || lower.includes('জীব')) {
    icon = 'dna'; color = '#22c55e';
  } else if (lower.includes('sci') || lower.includes('বিজ্ঞান')) {
    icon = 'microscope'; color = '#3b82f6';
  } else if (lower.includes('gk') || lower.includes('জ্ঞান') || lower.includes('affair') || lower.includes('বিশ্ব') || lower.includes('world')) {
    icon = 'globe'; color = '#f59e0b';
  } else if (lower.includes('ict') || lower.includes('comp') || lower.includes('তথ্য') || lower.includes('আইসিটি') || lower.includes('code') || lower.includes('prog') || lower.includes('tech')) {
    icon = 'monitor'; color = '#0ea5e9';
  } else if (lower.includes('law') || lower.includes('আইন') || lower.includes('moral') || lower.includes('ethic') || lower.includes('সুশাসন') || lower.includes('বিচার')) {
    icon = 'scale'; color = '#475569';
  } else if (lower.includes('bank') || lower.includes('finan') || lower.includes('অর্থ') || lower.includes('হিসাব') || lower.includes('account') || lower.includes('tax')) {
    icon = 'coins'; color = '#0284c7';
  } else if (lower.includes('med') || lower.includes('health') || lower.includes('চিকিৎসা') || lower.includes('ডাক্তার') || lower.includes('নাব')) {
    icon = 'activity'; color = '#ef4444';
  } else if (lower.includes('art') || lower.includes('ড্রয়িং') || lower.includes('চিত্র') || lower.includes('সঙ্গীত') || lower.includes('music')) {
    icon = 'palette'; color = '#d946ef';
  } else if (lower.includes('geo') || lower.includes('ভূগোল') || lower.includes('পরিবেশ') || lower.includes('earth') || lower.includes('climate')) {
    icon = 'trees'; color = '#10b981';
  } else if (lower.includes('hist') || lower.includes('ইতিহাস') || lower.includes('মুক্তিযুদ্ধ') || lower.includes('war')) {
    icon = 'landmark'; color = '#e11d48';
  } else if (lower.includes('biz') || lower.includes('business') || lower.includes('উদ্যোগ') || lower.includes('manage')) {
    icon = 'rocket'; color = '#d97706';
  }

  return { bn: canon, color, icon };
}

function addSubject(name) {
  if (!name || typeof name !== 'string') return null;
  const trimmed = name.trim();
  if (!trimmed || trimmed === '__custom__' || trimmed.toLowerCase() === 'all') return null;
  const canonical = canonicalSubjectName(trimmed);
  if (Array.isArray(state.deletedSubjects)) {
    state.deletedSubjects = state.deletedSubjects.filter(s => canonicalSubjectName(s).toLowerCase() !== canonical.toLowerCase());
  }
  if (Array.isArray(state.permanentlyDeletedSubjects)) {
    state.permanentlyDeletedSubjects = state.permanentlyDeletedSubjects.filter(s => canonicalSubjectName(s).toLowerCase() !== canonical.toLowerCase());
  }
  if (!Array.isArray(state.customSubjects)) state.customSubjects = [];
  if (!state.customSubjects.some(c => canonicalSubjectName(c).toLowerCase() === canonical.toLowerCase())) {
    state.customSubjects.push(canonical);
  }
  saveData();
  syncAllSubjectSelects();
  return canonical;
}

function masterSubjectList(includeDeleted = false) {
  const fromRoutine = (state.routine || []).map(r => r.subject).filter(Boolean);
  const fromSessions = (state.sessions || []).map(s => s.subject).filter(Boolean);
  const fromCustom = Array.isArray(state.customSubjects) ? state.customSubjects : [];
  const fromSyllabus = (state.syllabus || []).map(c => c.name).filter(Boolean);
  const fromFlashcards = (state.flashcards || []).map(f => f.category).filter(Boolean);
  const fromDeleted = Array.isArray(state.deletedSubjects) ? state.deletedSubjects : [];

  const all = uniqueSubjectNames([
    ...DEFAULT_SUBJECTS,
    ...fromCustom,
    ...fromSyllabus,
    ...fromRoutine,
    ...fromSessions,
    ...fromFlashcards,
    ...(includeDeleted ? fromDeleted : [])
  ]);

  const permDeletedSet = new Set((state.permanentlyDeletedSubjects || []).map(s => canonicalSubjectName(s).toLowerCase()));
  const eligibleAll = all.filter(s => !permDeletedSet.has(canonicalSubjectName(s).toLowerCase()));

  if (includeDeleted) return eligibleAll;
  const deletedSet = new Set((state.deletedSubjects || []).map(s => canonicalSubjectName(s).toLowerCase()));
  return eligibleAll.filter(s => !deletedSet.has(canonicalSubjectName(s).toLowerCase()));
}

function getSubjectDisplayName(subject, lang = null) {
  if (!subject) return '';
  const canon = canonicalSubjectName(subject);
  const currentLang = lang || (typeof getUserTrack === 'function' ? (getUserTrack().subjectLanguage || 'en') : 'en');
  if (currentLang === 'bn') {
    const meta = typeof getSubjectMeta === 'function' ? getSubjectMeta(canon) : null;
    return (meta && meta.bn) ? meta.bn : canon;
  }
  return canon;
}
window.getSubjectDisplayName = getSubjectDisplayName;

function setSubjectLanguage(lang) {
  const cleanLang = (lang === 'bn' || lang === 'bangla') ? 'bn' : 'en';
  const track = getUserTrack();
  track.subjectLanguage = cleanLang;
  saveUserTrack(track);
  syncAllSubjectSelects();
  if (typeof renderProfileAspirantHub === 'function') renderProfileAspirantHub();
  if (typeof renderRoutine === 'function') renderRoutine();
  if (typeof renderCategories === 'function') renderCategories();
  if (typeof renderTrackerRoutinePreview === 'function') renderTrackerRoutinePreview();
  if (typeof renderMCQFilterBar === 'function') renderMCQFilterBar();
  if (typeof showToast === 'function') {
    showToast(`Subject language set to ${cleanLang === 'bn' ? 'বাংলা (Bangla)' : 'English'}`);
  }
}
window.setSubjectLanguage = setSubjectLanguage;

function subjectList() {
  return masterSubjectList(false);
}

function renderSubjectSelect() {
  const sel = document.getElementById('sessionSubject');
  const datalist = document.getElementById('appSubjectDatalist');
  const subs = subjectList();
  const currentLang = typeof getUserTrack === 'function' ? (getUserTrack().subjectLanguage || 'en') : 'en';

  // 1. Sync global datalist for Routine and Syllabus
  if (datalist) {
    const optionsMap = new Map();
    subs.forEach(s => {
      const canon = canonicalSubjectName(s);
      const display = getSubjectDisplayName(s, currentLang);
      optionsMap.set(display.toLowerCase(), display);
      if (display !== canon) {
        optionsMap.set(canon.toLowerCase(), canon);
      }
    });
    datalist.innerHTML = Array.from(optionsMap.values()).map(v => `<option value="${escapeAttr(v)}"></option>`).join('');
  }

  // 2. Populate Tracker dropdown
  if (sel) {
    const previousValue = sel.value || (state.activeSession ? state.activeSession.subject : '') || '';
    const previousCustomValue = sessionCustomInput ? sessionCustomInput.value : '';

    sel.innerHTML = subs.map(s => {
      const canon = canonicalSubjectName(s);
      const display = getSubjectDisplayName(s, currentLang);
      const label = display;
      return `<option value="${escapeAttr(canon)}">${escapeHtml(label)}</option>`;
    }).join('')
      + '<option value="__custom__">+ Add New Subject</option>';

    let nextValue = '';
    if (previousValue === '__custom__' || (previousCustomValue && previousValue === '')) {
      nextValue = '__custom__';
    } else if (previousValue && subs.map(canonicalSubjectName).includes(canonicalSubjectName(previousValue))) {
      nextValue = canonicalSubjectName(previousValue);
    } else if (subs.length) {
      nextValue = canonicalSubjectName(subs[0]);
    }

    if (nextValue) {
      sel.value = nextValue;
    }

    if (sessionCustomInput) {
      sessionCustomInput.style.display = sel.value === '__custom__' ? 'block' : 'none';
      if (sel.value === '__custom__') {
        sessionCustomInput.value = previousCustomValue || '';
      } else {
        sessionCustomInput.value = '';
      }
    }
  }
}


// Cascading Subject Mutation (Rename, Delete, Restore, Sync)
function renameSubject(oldName, newName) {
  if (!oldName || !newName || oldName === newName) return;
  const oldCanonical = canonicalSubjectName(oldName).toLowerCase();

  // 1. Routine
  if (Array.isArray(state.routine)) {
    state.routine.forEach(r => {
      if (canonicalSubjectName(r.subject).toLowerCase() === oldCanonical) {
        r.subject = newName;
      }
    });
  }

  // 2. Sessions
  if (Array.isArray(state.sessions)) {
    state.sessions.forEach(s => {
      if (canonicalSubjectName(s.subject).toLowerCase() === oldCanonical) {
        s.subject = newName;
      }
    });
  }

  // 3. Active session
  if (state.activeSession && canonicalSubjectName(state.activeSession.subject).toLowerCase() === oldCanonical) {
    state.activeSession.subject = newName;
  }

  // 4. Custom subjects
  if (Array.isArray(state.customSubjects)) {
    const idx = state.customSubjects.findIndex(c => canonicalSubjectName(c).toLowerCase() === oldCanonical);
    if (idx !== -1) {
      state.customSubjects[idx] = newName;
    } else {
      state.customSubjects.push(newName);
    }
  } else {
    state.customSubjects = [newName];
  }

  // 5. Syllabus categories
  if (Array.isArray(state.syllabus)) {
    state.syllabus.forEach(cat => {
      if (canonicalSubjectName(cat.name).toLowerCase() === oldCanonical) {
        cat.name = newName;
      }
    });
  }

  // 6. Flashcards
  if (Array.isArray(state.flashcards)) {
    state.flashcards.forEach(fc => {
      if (canonicalSubjectName(fc.category).toLowerCase() === oldCanonical) {
        fc.category = newName;
      }
    });
  }

  // 7. Deleted subjects
  if (Array.isArray(state.deletedSubjects)) {
    state.deletedSubjects = state.deletedSubjects.filter(s => canonicalSubjectName(s).toLowerCase() !== oldCanonical);
  }

  saveData();
  syncAllSubjectSelects();
  renderRoutine();
  renderCategories();
  if (typeof renderFlashcards === 'function') renderFlashcards();
  renderTrackerRoutinePreview();
  showToast(`Renamed "${oldName}" to "${newName}" across all data.`);
}

function deleteSubject(subj) {
  if (!subj) return;
  const canonical = canonicalSubjectName(subj);
  const confirmed = confirm(`Archive and hide subject "${subj}"?\n\nThis will hide it from all active subject pickers and routine lists. Your past study sessions and routine entries will remain safely preserved in history, and you can restore it anytime from Inactive / Archived Subjects.`);
  if (!confirmed) return;

  if (!Array.isArray(state.deletedSubjects)) state.deletedSubjects = [];
  if (!state.deletedSubjects.some(s => canonicalSubjectName(s).toLowerCase() === canonical.toLowerCase())) {
    state.deletedSubjects.push(canonical);
  }

  // Remove from custom subjects if present
  if (Array.isArray(state.customSubjects)) {
    state.customSubjects = state.customSubjects.filter(c => canonicalSubjectName(c).toLowerCase() !== canonical.toLowerCase());
  }

  saveData();
  syncAllSubjectSelects();
  if (typeof renderProfileAspirantHub === 'function') renderProfileAspirantHub();
  showToast(`"${subj}" archived to Inactive Subjects.`);
}

function restoreSubject(subj) {
  if (!subj) return;
  const canonical = canonicalSubjectName(subj);
  const canonLower = canonical.toLowerCase();
  if (Array.isArray(state.deletedSubjects)) {
    state.deletedSubjects = state.deletedSubjects.filter(s => canonicalSubjectName(s).toLowerCase() !== canonLower);
  }
  if (Array.isArray(state.permanentlyDeletedSubjects)) {
    state.permanentlyDeletedSubjects = state.permanentlyDeletedSubjects.filter(s => canonicalSubjectName(s).toLowerCase() !== canonLower);
  }
  // Ensure non-default subject is restored to customSubjects so it doesn't vanish
  const isDefault = (typeof DEFAULT_SUBJECTS !== 'undefined' ? DEFAULT_SUBJECTS : []).some(
    d => canonicalSubjectName(d).toLowerCase() === canonLower
  );
  if (!isDefault) {
    if (!Array.isArray(state.customSubjects)) state.customSubjects = [];
    if (!state.customSubjects.some(c => canonicalSubjectName(c).toLowerCase() === canonLower)) {
      state.customSubjects.push(canonical);
    }
  }
  saveData();
  syncAllSubjectSelects();
  if (typeof renderProfileAspirantHub === 'function') renderProfileAspirantHub();
  if (typeof renderSubjectManager === 'function') renderSubjectManager();
  showToast(`"${canonical}" restored to active subjects.`);
}

function permanentlyDeleteSubject(subj) {
  if (!subj) return;
  const canonical = canonicalSubjectName(subj);
  const canonLower = canonical.toLowerCase();

  const confirmed = confirm(
    `PERMANENTLY delete subject "${subj}"?\n\n` +
    `⚠️ WARNING: Deleted data CANNOT be restored!\n\n` +
    `• All logged study sessions for "${subj}" will be permanently wiped.\n` +
    `• All routine schedule blocks for "${subj}" will be removed.\n` +
    `• All syllabus categories and topics for "${subj}" will be deleted.\n` +
    `• All flashcards for "${subj}" will be deleted.\n\n` +
    `Do you want to permanently delete this subject?`
  );
  if (!confirmed) return;

  // 1. Remove from deletedSubjects
  if (Array.isArray(state.deletedSubjects)) {
    state.deletedSubjects = state.deletedSubjects.filter(s => canonicalSubjectName(s).toLowerCase() !== canonLower);
  }

  // 2. Remove from customSubjects
  if (Array.isArray(state.customSubjects)) {
    state.customSubjects = state.customSubjects.filter(s => canonicalSubjectName(s).toLowerCase() !== canonLower);
  }

  // 3. Mark in permanentlyDeletedSubjects so default lists won't re-add it
  if (!Array.isArray(state.permanentlyDeletedSubjects)) {
    state.permanentlyDeletedSubjects = [];
  }
  if (!state.permanentlyDeletedSubjects.some(s => canonicalSubjectName(s).toLowerCase() === canonLower)) {
    state.permanentlyDeletedSubjects.push(canonical);
  }

  // 4. Purge routine
  if (Array.isArray(state.routine)) {
    state.routine = state.routine.filter(r => canonicalSubjectName(r.subject).toLowerCase() !== canonLower);
  }

  // 5. Purge sessions
  if (Array.isArray(state.sessions)) {
    state.sessions = state.sessions.filter(sess => canonicalSubjectName(sess.subject).toLowerCase() !== canonLower);
  }

  // 6. Reset activeSession if matching
  if (state.activeSession && canonicalSubjectName(state.activeSession.subject).toLowerCase() === canonLower) {
    state.activeSession = null;
  }

  // 7. Purge syllabus categories
  if (Array.isArray(state.syllabus)) {
    state.syllabus = state.syllabus.filter(c => canonicalSubjectName(c.name).toLowerCase() !== canonLower);
  }

  // 8. Purge flashcards
  if (Array.isArray(state.flashcards)) {
    state.flashcards = state.flashcards.filter(f => canonicalSubjectName(f.category).toLowerCase() !== canonLower);
  }

  saveData();
  syncAllSubjectSelects();
  renderRoutine();
  renderCategories();
  if (typeof renderFlashcards === 'function') renderFlashcards();
  if (typeof renderTrackerRoutinePreview === 'function') renderTrackerRoutinePreview();
  if (typeof renderProfileAspirantHub === 'function') renderProfileAspirantHub();
  if (typeof renderSubjectManager === 'function') renderSubjectManager();
  showToast(`"${subj}" permanently deleted. Data cannot be restored.`);
}

function permanentlyDeleteAllInactiveSubjects() {
  if (!Array.isArray(state.deletedSubjects) || state.deletedSubjects.length === 0) return;
  const count = state.deletedSubjects.length;

  const confirmed = confirm(
    `PERMANENTLY delete all ${count} inactive subjects?\n\n` +
    `⚠️ WARNING: Deleted data CANNOT be restored!\n\n` +
    `All study sessions, routine blocks, syllabus checklists, and flashcards for these subjects will be permanently wiped.\n\n` +
    `Are you sure you want to proceed?`
  );
  if (!confirmed) return;

  const targets = [...state.deletedSubjects];
  targets.forEach(s => {
    const canonLower = canonicalSubjectName(s).toLowerCase();
    if (!Array.isArray(state.permanentlyDeletedSubjects)) state.permanentlyDeletedSubjects = [];
    if (!state.permanentlyDeletedSubjects.some(p => canonicalSubjectName(p).toLowerCase() === canonLower)) {
      state.permanentlyDeletedSubjects.push(canonicalSubjectName(s));
    }
    if (Array.isArray(state.customSubjects)) {
      state.customSubjects = state.customSubjects.filter(cs => canonicalSubjectName(cs).toLowerCase() !== canonLower);
    }
    if (Array.isArray(state.routine)) {
      state.routine = state.routine.filter(r => canonicalSubjectName(r.subject).toLowerCase() !== canonLower);
    }
    if (Array.isArray(state.sessions)) {
      state.sessions = state.sessions.filter(sess => canonicalSubjectName(sess.subject).toLowerCase() !== canonLower);
    }
    if (state.activeSession && canonicalSubjectName(state.activeSession.subject).toLowerCase() === canonLower) {
      state.activeSession = null;
    }
    if (Array.isArray(state.syllabus)) {
      state.syllabus = state.syllabus.filter(c => canonicalSubjectName(c.name).toLowerCase() !== canonLower);
    }
    if (Array.isArray(state.flashcards)) {
      state.flashcards = state.flashcards.filter(f => canonicalSubjectName(f.category).toLowerCase() !== canonLower);
    }
  });

  state.deletedSubjects = [];
  saveData();
  syncAllSubjectSelects();
  renderRoutine();
  renderCategories();
  if (typeof renderFlashcards === 'function') renderFlashcards();
  if (typeof renderTrackerRoutinePreview === 'function') renderTrackerRoutinePreview();
  if (typeof renderProfileAspirantHub === 'function') renderProfileAspirantHub();
  if (typeof renderSubjectManager === 'function') renderSubjectManager();
  showToast(`All ${count} inactive subjects permanently deleted.`);
}

/* Liquid switch indicator shared by the timer switches and the nav tabs: when a
   control turns on, a bubble of its fill slides over from the control that was
   on, bulges mid-flight and wobbles as it lands. */
function slideSwitchBubble(previousButton, nextButton, bubbleClass) {
  if (!previousButton || !nextButton || previousButton === nextButton) return;
  const group = nextButton.parentElement;
  if (!group) return;
  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

  const groupRect = group.getBoundingClientRect();
  const fromRect = previousButton.getBoundingClientRect();
  const toRect = nextButton.getBoundingClientRect();
  if (!fromRect.width || !toRect.width) return; // group is hidden

  if (getComputedStyle(group).position === 'static') group.style.position = 'relative';

  const className = bubbleClass || 'switch-bubble';
  group.querySelectorAll(':scope > .' + className).forEach(stale => stale.remove());

  /* Read the settled "on" look with transitions muted, so the bubble never picks
     up a mid-transition value. The control itself is already showing it. */
  const priorTransition = nextButton.style.getPropertyValue('transition');
  const priorTransitionPriority = nextButton.style.getPropertyPriority('transition');
  nextButton.style.setProperty('transition', 'none', 'important');
  const activeStyle = getComputedStyle(nextButton);
  const activeLook = {
    borderRadius: activeStyle.borderRadius,
    backgroundColor: activeStyle.backgroundColor,
    backgroundImage: activeStyle.backgroundImage,
    boxShadow: activeStyle.boxShadow,
    borderStyle: activeStyle.borderStyle,
    borderWidth: activeStyle.borderWidth,
    borderColor: activeStyle.borderColor
  };
  if (priorTransition) nextButton.style.setProperty('transition', priorTransition, priorTransitionPriority);
  else nextButton.style.removeProperty('transition');

  const tint = activeLook.backgroundColor;
  const filled = activeLook.backgroundImage !== 'none'
    || (tint && tint !== 'transparent' && tint !== 'rgba(0, 0, 0, 0)');
  const bubble = document.createElement('span');
  bubble.className = 'switch-bubble ' + className;
  bubble.setAttribute('aria-hidden', 'true');
  bubble.style.width = fromRect.width + 'px';
  bubble.style.height = fromRect.height + 'px';
  bubble.style.borderRadius = activeLook.borderRadius;
  bubble.style.backgroundImage = filled ? activeLook.backgroundImage : 'linear-gradient(135deg, #6366f1, #06b6d4)';
  bubble.style.backgroundColor = filled ? tint : 'transparent';
  bubble.style.boxShadow = activeLook.boxShadow === 'none' ? '' : activeLook.boxShadow;
  if (activeLook.borderStyle !== 'none' && parseFloat(activeLook.borderWidth) > 0) {
    bubble.style.border = `${activeLook.borderWidth} ${activeLook.borderStyle} ${activeLook.borderColor}`;
  }
  group.appendChild(bubble);

  const startX = fromRect.left - groupRect.left;
  const startY = fromRect.top - groupRect.top;
  const dx = toRect.left - fromRect.left;
  const dy = toRect.top - fromRect.top;
  const scaleX = toRect.width / fromRect.width;
  const scaleY = toRect.height / fromRect.height;
  const place = (x, y, sx, sy) => `translate(${x}px, ${y}px) scale(${sx}, ${sy})`;

  bubble.style.transform = place(startX, startY, 1, 1);

  /* Straight slide: the fill travels and resizes in one smooth move, no mid-flight
     bulge and no landing squash. */
  const animation = bubble.animate([
    { transform: place(startX, startY, 1, 1) },
    { transform: place(startX + dx, startY + dy, scaleX, scaleY) }
  ], { duration: 160, easing: 'cubic-bezier(.4, 0, .2, 1)', fill: 'forwards' });

  /* The bubble is disposable: it comes off as soon as it lands, and the control
     underneath is already showing its own active fill. */
  const cleanup = () => bubble.remove();
  animation.addEventListener('cancel', cleanup);
  animation.finished.then(cleanup, cleanup);
}

/* Timer switches (Study/Break, Stopwatch/30m/...) on the dashboard and tracker. */
function slideTimerSwitchBubble(previousButton, nextButton) {
  if (!nextButton || !nextButton.parentElement || !nextButton.parentElement.classList.contains('db-timer-modes')) return;
  slideSwitchBubble(previousButton, nextButton, 'db-timer-bubble');
}

/* Primary navigation tabs (sidebar, mobile dock and the More menu). */
function slideNavTabBubble(previousButton, nextButton) {
  slideSwitchBubble(previousButton, nextButton, 'nav-tab-bubble');
}

function syncAllSubjectSelects() {
  renderSubjectSelect();
  if (typeof renderFlashCategoryOptions === 'function') renderFlashCategoryOptions();
  renderSubjectManager();
  if (typeof renderMCQFilterBar === 'function') {
    renderMCQFilterBar();
  }
  const newSubjSel = document.getElementById('new-subject');
  if (newSubjSel) {
    const subs = subjectList();
    const curVal = newSubjSel.value;
    newSubjSel.innerHTML = subs.map(s => `<option value="${escapeAttr(s)}">${escapeHtml(s)}</option>`).join('');
    if (curVal && subs.includes(curVal)) newSubjSel.value = curVal;
  }
}

/* Source: assets/js/features/routine.js */
/* ==========================================================================
   CareerDesk — Routine Module: Day-by-Day & Monthly Schedules
   ========================================================================== */

// ===== Routine =====
const routineCardWrap = document.getElementById('routineCardWrap');
let routineDateFilter = dateKey(Date.now());

function updateMonthYearPlaceholder() {
  const textEl = document.getElementById('routineMonthYearText');
  if (!textEl) return;
  const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  textEl.textContent = `${months[currentViewMonth]} ${currentViewYear}`;
}

function updateRoutineTodayButtonState() {
  const btn = document.getElementById('routineGoTodayBtn');
  if (!btn) return;
  const isToday = routineDateFilter === dateKey(Date.now());
  btn.classList.toggle('is-today', isToday);
  btn.title = isToday ? "Currently viewing today's routine" : "Jump to today's routine";
}

function goToTodayRoutine() {
  const now = new Date();
  currentViewYear = now.getFullYear();
  currentViewMonth = now.getMonth();
  routineDateFilter = dateKey(now.getTime());
  const mSel = document.getElementById('monthDropdown');
  if (mSel) mSel.value = `${currentViewYear}-${String(currentViewMonth + 1).padStart(2, '0')}`;
  updateMonthYearPlaceholder();
  toggleMonthlyRoutineView(false);
  renderDateSlider();
  renderRoutine();
  updateRoutineTodayButtonState();
  if (typeof showToast === 'function') {
    showToast("Viewing today's routine");
  }
}

const routineGoTodayBtn = document.getElementById('routineGoTodayBtn');
if (routineGoTodayBtn) {
  routineGoTodayBtn.addEventListener('click', goToTodayRoutine);
}

function shiftRoutineMonth(delta) {
  currentViewMonth += delta;
  if (currentViewMonth < 0) {
    currentViewMonth = 11;
    currentViewYear -= 1;
  } else if (currentViewMonth > 11) {
    currentViewMonth = 0;
    currentViewYear += 1;
  }
  const sel = document.getElementById('monthDropdown');
  if (sel) {
    sel.value = `${currentViewYear}-${String(currentViewMonth + 1).padStart(2, '0')}`;
  }
  updateMonthYearPlaceholder();

  const now = new Date();
  if (now.getFullYear() === currentViewYear && now.getMonth() === currentViewMonth) {
    routineDateFilter = dateKey(now.getTime());
  } else {
    routineDateFilter = dateKey(new Date(currentViewYear, currentViewMonth, 1).getTime());
  }
  const mBox = document.getElementById('monthlyRoutineView');
  if (mBox && !mBox.hidden) {
    showMonthlyRoutines();
  } else {
    renderDateSlider();
    renderRoutine();
  }
}

const routinePrevMonthBtn = document.getElementById('routinePrevMonthBtn');
if (routinePrevMonthBtn) {
  routinePrevMonthBtn.addEventListener('click', () => shiftRoutineMonth(-1));
}

const routineNextMonthBtn = document.getElementById('routineNextMonthBtn');
if (routineNextMonthBtn) {
  routineNextMonthBtn.addEventListener('click', () => shiftRoutineMonth(1));
}

function initMonthDropdown() {
  const sel = document.getElementById('monthDropdown');
  if (!sel) return;
  const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  let html = '';
  const baseYear = new Date().getFullYear();
  for (let y = baseYear - 1; y <= baseYear + 2; y++) {
    for (let m = 0; m < 12; m++) {
      const val = `${y}-${String(m + 1).padStart(2, '0')}`;
      const label = `${months[m]} ${y}`;
      const selected = (y === currentViewYear && m === currentViewMonth) ? 'selected' : '';
      html += `<option value="${val}" ${selected}>${label}</option>`;
    }
  }
  sel.innerHTML = html;
  updateMonthYearPlaceholder();
}

const monthDropdownSel = document.getElementById('monthDropdown');
if (monthDropdownSel) {
  monthDropdownSel.addEventListener('change', (e) => {
    const [y, m] = e.target.value.split('-');
    currentViewYear = parseInt(y);
    currentViewMonth = parseInt(m) - 1;
    updateMonthYearPlaceholder();

    const now = new Date();
    if (now.getFullYear() === currentViewYear && now.getMonth() === currentViewMonth) {
      routineDateFilter = dateKey(now.getTime());
    } else {
      routineDateFilter = dateKey(new Date(currentViewYear, currentViewMonth, 1).getTime());
    }
    const mBox = document.getElementById('monthlyRoutineView');
    if (mBox && !mBox.hidden) {
      showMonthlyRoutines();
    } else {
      renderDateSlider();
      renderRoutine();
    }
  });
}

function buildDateSliderList() {
  const dates = new Set();
  // 1. Generate all days of current viewed month
  const daysInMonth = new Date(currentViewYear, currentViewMonth + 1, 0).getDate();
  for (let day = 1; day <= daysInMonth; day++) {
    const d = new Date(currentViewYear, currentViewMonth, day);
    dates.add(dateKey(d.getTime()));
  }
  // 2. Ensure today is present
  dates.add(dateKey(Date.now()));
  // 3. Ensure routineDateFilter is present
  if (routineDateFilter) dates.add(routineDateFilter);
  // 4. Add any other routine dates with existing entries
  if (Array.isArray(state.routine)) {
    state.routine.forEach(r => { if (r.date) dates.add(r.date); });
  }
  return Array.from(dates).sort();
}

function renderDateSlider() {
  const box = document.getElementById('dateSlider');
  if (!box) return;
  const dayLabels = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const routineDates = new Set((state.routine || []).filter(r => r.subject).map(r => r.date));
  let html = '';
  buildDateSliderList().forEach(ds => {
    const d = new Date(ds + 'T00:00:00');
    const hasDot = routineDates.has(ds) ? 'has-routine' : '';
    const isAct = routineDateFilter === ds ? 'active' : '';
    html += `<div class="date-chip ${isAct} ${hasDot}" data-date="${ds}">
      <span class="dc-day">${dayLabels[d.getDay()]}</span><span class="dc-num">${d.getDate()}</span>
    </div>`;
  });
  box.innerHTML = html;
  updateRoutineTodayButtonState();

  const activeChip = box.querySelector('.date-chip.active');
  if (activeChip) {
    setTimeout(() => {
      activeChip.scrollIntoView({ behavior: 'smooth', inline: 'center', block: 'nearest' });
    }, 50);
  }
}

const dateSliderBox = document.getElementById('dateSlider');
if (dateSliderBox) {
  dateSliderBox.addEventListener('click', (e) => {
    const chip = e.target.closest('.date-chip');
    if (!chip) return;
    routineDateFilter = chip.dataset.date || null;
    renderDateSlider();
    renderRoutine();
  });
}

function shiftRoutineDate(delta) {
  const base = routineDateFilter || dateKey(Date.now());
  const d = new Date(base + 'T00:00:00');
  d.setDate(d.getDate() + delta);
  routineDateFilter = dateKey(d.getTime());

  if (d.getMonth() !== currentViewMonth || d.getFullYear() !== currentViewYear) {
    currentViewMonth = d.getMonth();
    currentViewYear = d.getFullYear();
    const sel = document.getElementById('monthDropdown');
    if (sel) sel.value = `${currentViewYear}-${String(currentViewMonth + 1).padStart(2, '0')}`;
    updateMonthYearPlaceholder();
  }

  renderDateSlider();
  renderRoutine();
}

const prevDateBtn = document.getElementById('datePrevBtn');
if (prevDateBtn) prevDateBtn.addEventListener('click', () => shiftRoutineDate(-1));

const nextDateBtn = document.getElementById('dateNextBtn');
if (nextDateBtn) nextDateBtn.addEventListener('click', () => shiftRoutineDate(1));

function formatTime12(t) {
  if (!t || !t.includes(':')) return t || '--:--';
  const [hStr, mStr] = t.split(':');
  let h = parseInt(hStr, 10);
  if (isNaN(h)) return t;
  const ampm = h >= 12 ? 'PM' : 'AM';
  h = h % 12;
  if (h === 0) h = 12;
  return `${h}:${mStr} ${ampm}`;
}
window.formatTime12 = formatTime12;

const ROUTINE_HEAD = '<thead><tr><th style="width:16%">Start</th><th style="width:16%">End</th><th style="width:24%" class="routine-subject-head" title="Subject">Subject</th><th>Topic / Task</th><th style="width:78px; text-align:right;"><button type="button" class="routine-table-reset-btn" id="resetRoutineBtn" title="Reset to recommended daily routine"><i data-lucide="rotate-ccw" style="width:12px; height:12px; vertical-align:middle; margin-right:3px;"></i><span>Reset</span></button></th></tr></thead>';

/* The Subject column header names the subject of the row being edited, so the
   table always says what you picked. An empty row falls back to "Subject", and
   the full name stays available in the tooltip when the cell has to shorten. */
const ROUTINE_SUBJECT_HEAD_MAX = 22;

function updateRoutineSubjectHead(input) {
  if (!input || input.dataset.field !== 'subject') return;
  const table = input.closest('table.routine');
  const head = table ? table.querySelector('th.routine-subject-head') : null;
  if (!head) return;

  const name = typeof getSubjectDisplayName === 'function'
    ? String(getSubjectDisplayName(input.value) || '').trim()
    : String(input.value || '').trim();
  const shown = name.length > ROUTINE_SUBJECT_HEAD_MAX
    ? name.slice(0, ROUTINE_SUBJECT_HEAD_MAX - 1).trimEnd() + '…'
    : name;

  head.textContent = shown || 'Subject';
  head.title = name || 'Subject';
  head.classList.toggle('is-named', !!name);
}
window.updateRoutineSubjectHead = updateRoutineSubjectHead;

function routineTopicIsInSyllabus(row) {
  const subject = typeof canonicalSubjectName === 'function'
    ? canonicalSubjectName(row.subject).trim().toLowerCase()
    : String(row.subject || '').trim().toLowerCase();
  const task = String(row.task || '').trim().toLowerCase();
  if (!subject || !task) return false;
  const category = (state.syllabus || []).find(item => {
    const name = typeof canonicalSubjectName === 'function'
      ? canonicalSubjectName(item.name).trim().toLowerCase()
      : String(item.name || '').trim().toLowerCase();
    return name === subject;
  });
  return !!category && (category.topics || []).some(topic => String(topic.name || '').trim().toLowerCase() === task);
}

function updateRoutineSyllabusAction(row, button) {
  if (!row || !button) return;
  const complete = !!String(row.subject || '').trim() && !!String(row.task || '').trim();
  const added = complete && routineTopicIsInSyllabus(row);
  button.disabled = !complete || added;
  button.title = added ? 'Already in Syllabus' : complete ? 'Add task to Syllabus' : 'Enter a subject and task first';
  button.setAttribute('aria-label', button.title);
  button.innerHTML = added ? ICON.check : ICON.layers;
}

function routineRowHtml(row) {
  const meta = typeof getSubjectMeta === 'function' ? getSubjectMeta(row.subject) : { color: '#6366f1', icon: 'book-open' };
  const topicAdded = routineTopicIsInSyllabus(row);
  const taskReady = !!String(row.subject || '').trim() && !!String(row.task || '').trim();
  return `
    <tr>
      <td><input type="time" value="${row.startTime || ''}" data-field="startTime" data-id="${row.id}"></td>
      <td><input type="time" value="${row.endTime || ''}" data-field="endTime" data-id="${row.id}"></td>
      <td>
        <div style="display:flex; align-items:center; gap:6px;">
          <span style="color:${meta.color}; display:inline-flex; align-items:center;"><i data-lucide="${meta.icon || 'book-open'}" style="width:14px; height:14px;"></i></span>
          <input type="text" value="${escapeAttr(row.subject || '')}" placeholder="Subject" data-field="subject" data-id="${row.id}" list="appSubjectDatalist" style="flex:1;">
        </div>
      </td>
      <td><input type="text" value="${escapeAttr(row.task || '')}" placeholder="Task description" data-field="task" data-id="${row.id}"></td>
      <td><div class="routine-row-actions">
        <button class="routine-syllabus-btn" type="button" data-id="${escapeAttr(row.id)}" ${!taskReady || topicAdded ? 'disabled' : ''} title="${topicAdded ? 'Already in Syllabus' : taskReady ? 'Add task to Syllabus' : 'Enter a subject and task first'}" aria-label="${topicAdded ? 'Already in Syllabus' : 'Add task to Syllabus'}">${topicAdded ? ICON.check : ICON.layers}</button>
        <button class="del-row" title="Delete row" data-id="${row.id}">${ICON.x}</button>
      </div></td>
    </tr>
  `;
}

function renderTrackerRoutinePreview() {
  const box = document.getElementById('trackerRoutinePreview');
  if (!box) return;

  const today = state.sessions.filter(s => dateKey(s.start) === todayKey());
  const byTotal = {};
  today.forEach(s => { byTotal[s.subject] = (byTotal[s.subject] || 0) + s.duration; });
  const entries = Object.entries(byTotal).sort((a, b) => b[1] - a[1]).slice(0, 4);

  if (!entries.length) {
    box.innerHTML = '<div class="tracker-routine-title">Today\'s Subject Breakdown</div><div class="empty-state">No study sessions recorded today.</div>';
    return;
  }

  const max = Math.max(...entries.map(([, min]) => min));
  const rowsHtml = entries.map(([subj, min]) => {
    const meta = typeof getSubjectMeta === 'function' ? getSubjectMeta(subj) : { color: '#6366f1', icon: 'book-open' };
    return `
      <div class="tracker-routine-item">
        <div class="tracker-routine-details">
          <div class="tracker-routine-subject-row">
            <span class="tracker-routine-subject" style="display:inline-flex; align-items:center; gap:6px;">
              <span style="color:${meta.color}; display:inline-flex; align-items:center;"><i data-lucide="${meta.icon || 'book-open'}" style="width:13px; height:13px;"></i></span>
              <span>${escapeHtml(typeof getSubjectDisplayName === 'function' ? getSubjectDisplayName(subj) : subj)}</span>
            </span>
            <span class="tracker-routine-time">${fmtHM(min)}</span>
          </div>
          <div class="tracker-routine-progress">
            <div class="tracker-routine-track">
              <div class="tracker-routine-fill" style="width:${Math.round((min / max) * 100)}%; background:${meta.color};"></div>
            </div>
          </div>
        </div>
      </div>
    `;
  }).join('');

  box.innerHTML = `<div class="tracker-routine-title">Today's Subject Breakdown</div>${rowsHtml}`;

  if (window.lucide && typeof window.lucide.createIcons === 'function') {
    window.lucide.createIcons();
  }
}

function renderRoutine() {
  const wrap = document.getElementById('routineCardWrap');
  if (!wrap) return;
  if (!Array.isArray(state.routine)) state.routine = [];

  if (routineDateFilter === null) {
    const byDate = {};
    state.routine.forEach(r => { (byDate[r.date] = byDate[r.date] || []).push(r); });
    const dates = Object.keys(byDate).sort().reverse();
    if (!dates.length) {
      wrap.innerHTML = '<div class="empty-state" style="border:none; margin:16px;">No routine entries for this date.</div>';
      return;
    }
    wrap.innerHTML = dates.map(ds => {
      const rows = byDate[ds].slice().sort((a, b) => (a.startTime || '').localeCompare(b.startTime || ''));
      return `
        <div class="routine-date-group">
          <div class="routine-date-heading">${bnDateLabel(ds)}</div>
          <table class="routine">
            ${ROUTINE_HEAD}
            <tbody>${rows.map(routineRowHtml).join('')}</tbody>
          </table>
        </div>
      `;
    }).join('');
    return;
  }

  const todayTarget = routineDateFilter || dateKey(Date.now());
  let rows = state.routine.filter(r => r.date === todayTarget);

  if (!rows.length) {
    wrap.innerHTML = `
      <div class="routine-empty-card">
        <div class="routine-empty-icon"><i data-lucide="calendar-plus"></i></div>
        <h4>No study routine planned for this day</h4>
        <p>You can add your own custom study blocks or load the recommended BCS preliminary study routine.</p>
        <div class="routine-empty-actions">
          <button class="pill solid" id="emptyLoadDefaultsBtn" type="button"><i data-lucide="sparkles"></i> Load Recommended Routine</button>
          <button class="pill" id="emptyAddBlockBtn" type="button"><i data-lucide="plus"></i> Add Study Block</button>
        </div>
      </div>
    `;
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }
    renderTrackerRoutinePreview();
    return;
  }

  rows.sort((a, b) => {
    const timeA = a.startTime || '99:99';
    const timeB = b.startTime || '99:99';
    return timeA.localeCompare(timeB) || a.id - b.id;
  });

      wrap.innerHTML = `
      <div class="routine-table-container">
        <table class="routine">
          ${ROUTINE_HEAD}
          <tbody>${rows.map(routineRowHtml).join('')}</tbody>
        </table>
        <div class="routine-floating-add-dock" id="routineFloatingAddDock">
          <button type="button" class="routine-floating-add-circle" id="inlineAddRowBtn" title="Add another study block" aria-label="Add study block">
            <i data-lucide="plus" style="width:18px; height:18px;"></i>
          </button>
        </div>
      </div>
    `;

    // Connect hover for the floating add block button on the last item
    const lastTr = wrap.querySelector('tbody tr:last-child');
    const addBtn = wrap.querySelector('#inlineAddRowBtn');
    const dock = wrap.querySelector('#routineFloatingAddDock');
    if (lastTr && addBtn && dock) {
      const showBtn = () => addBtn.classList.add('hover-active');
      const hideBtn = (e) => {
        if (e && e.relatedTarget && (lastTr.contains(e.relatedTarget) || dock.contains(e.relatedTarget))) {
          return;
        }
        addBtn.classList.remove('hover-active');
      };
      lastTr.addEventListener('mouseenter', showBtn);
      lastTr.addEventListener('mouseleave', hideBtn);
      dock.addEventListener('mouseenter', showBtn);
      dock.addEventListener('mouseleave', hideBtn);
    }
  if (window.lucide && typeof window.lucide.createIcons === 'function') {
    window.lucide.createIcons();
  }
  renderTrackerRoutinePreview();
}

function bnDateLabel(dateStr) {
  if (!dateStr) return '';
  const d = new Date(dateStr + 'T00:00:00');
  const dayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const monthNames = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  return `${dayNames[d.getDay()]}, ${monthNames[d.getMonth()]} ${d.getDate()}, ${d.getFullYear()}`;
}

document.addEventListener('input', (e) => {
  const t = e.target;
  if (t.closest('#routineCardWrap') && t.dataset.field) {
    if (!Array.isArray(state.routine)) state.routine = [];
    const row = state.routine.find(r => String(r.id) === t.dataset.id);
    if (row) {
      row[t.dataset.field] = t.value;
      updateRoutineSyllabusAction(row, t.closest('tr')?.querySelector('.routine-syllabus-btn'));
      saveData();
    }
    if (t.dataset.field === 'subject') updateRoutineSubjectHead(t);
  }
});

/* Opening a subject field shows that row's subject name in the column header
   straight away — before a single key is typed. */
document.addEventListener('focusin', (e) => {
  const t = e.target;
  if (t && t.closest && t.closest('#routineCardWrap') && t.dataset && t.dataset.field === 'subject') {
    updateRoutineSubjectHead(t);
  }
});

document.addEventListener('change', (e) => {
  const t = e.target;
  if (t.closest('#routineCardWrap') && t.dataset.field === 'subject') {
    const val = t.value.trim();
    if (val && typeof addSubject === 'function') {
      addSubject(val);
    } else {
      syncAllSubjectSelects();
    }
  }
});

document.addEventListener('click', (e) => {
  const syllabusBtn = e.target.closest('.routine-syllabus-btn');
  if (syllabusBtn && syllabusBtn.closest('#routineCardWrap')) {
    const row = state.routine.find(item => String(item.id) === syllabusBtn.dataset.id);
    const subject = String(row?.subject || '').trim();
    const task = String(row?.task || '').trim();
    if (!row || !subject || !task) {
      showToast('Enter a subject and task first.', true);
      return;
    }

    const subjectName = typeof canonicalSubjectName === 'function' ? canonicalSubjectName(subject) : subject;
    const subjectKey = subjectName.trim().toLowerCase();
    let category = (state.syllabus || []).find(item => {
      const name = typeof canonicalSubjectName === 'function'
        ? canonicalSubjectName(item.name).trim().toLowerCase()
        : String(item.name || '').trim().toLowerCase();
      return name === subjectKey;
    });
    if (!category) {
      category = { id: Date.now(), name: subjectName, topics: [] };
      state.syllabus.push(category);
    }
    if (!Array.isArray(category.topics)) category.topics = [];
    const taskKey = task.toLowerCase();
    if (category.topics.some(topic => String(topic.name || '').trim().toLowerCase() === taskKey)) {
      updateRoutineSyllabusAction(row, syllabusBtn);
      showToast('This task is already in the Syllabus.');
      return;
    }
    category.topics.push({ id: Date.now(), name: task, done: false });
    saveData();
    if (typeof renderCategories === 'function') renderCategories();
    if (typeof syncAllSubjectSelects === 'function') syncAllSubjectSelects();
    renderRoutine();
    showToast(`Added "${task}" to ${category.name} Syllabus.`);
    return;
  }

  const delBtn = e.target.closest('.del-row');
  if (delBtn && delBtn.closest('#routineCardWrap')) {
    if (!window.confirm('Are you sure you want to delete this routine slot?')) return;
    if (!Array.isArray(state.routine)) state.routine = [];
    state.routine = state.routine.filter(r => String(r.id) !== delBtn.dataset.id);
    saveData();
    renderRoutine();
    renderDateSlider();
    syncAllSubjectSelects();
    return;
  }

  if (e.target && (e.target.id === 'inlineAddRowBtn' || e.target.closest('#inlineAddRowBtn'))) {
    const date = routineDateFilter || dateKey(Date.now());
    if (!Array.isArray(state.routine)) state.routine = [];
    state.routine.push({
      id: Date.now(),
      date: date,
      startTime: '',
      endTime: '',
      subject: '',
      task: ''
    });
    saveData();
    renderRoutine();
    syncAllSubjectSelects();
    showToast('New time slot added to routine');
    return;
  }

  if (e.target && (e.target.id === 'resetRoutineBtn' || e.target.closest('#resetRoutineBtn'))) {
    const date = routineDateFilter || dateKey(Date.now());
    if (!Array.isArray(state.routine)) state.routine = [];
    state.routine = state.routine.filter(r => r.date !== date);
    state.routine.push(...buildDefaultRoutine(date));
    saveData();
    renderDateSlider();
    renderRoutine();
    syncAllSubjectSelects();
    showToast('Default routine loaded for today');
    return;
  }
});

function toggleMonthlyRoutineView(forceOpen) {
  const mBox = document.getElementById('monthlyRoutineView');
  const dateNav = document.querySelector('.date-slider-row');
  const cardWrap = document.getElementById('routineCardWrap');
  const routineActions = document.querySelector('.routine-actions');
  const routineSaveNote = document.getElementById('routineSaveNote');
  const titleEl = document.querySelector('.routine-hero-copy .section-title');
  const leadEl = document.querySelector('.routine-hero-copy .routine-lead');
  const mBtn = document.getElementById('monthlyRoutineBtn');
  const dBtn = document.getElementById('dbdRoutineBtn') || document.getElementById('todayRoutineBtn');
  const todayBtn = document.getElementById('routineGoTodayBtn');
  const monthPlaceholder = document.getElementById('routineMonthPlaceholder');
  const monthSelectWrap = document.getElementById('routineMonthSelectWrap');

  const shouldOpen = typeof forceOpen === 'boolean' ? forceOpen : (mBox && mBox.hidden);

  if (shouldOpen) {
    if (mBox) mBox.hidden = false;
    if (dateNav) dateNav.hidden = true;
    if (cardWrap) cardWrap.hidden = true;
    if (routineActions) routineActions.hidden = true;
    if (routineSaveNote) routineSaveNote.hidden = true;
    if (mBtn) mBtn.classList.add('active');
    if (dBtn) dBtn.classList.remove('active');
    if (todayBtn) todayBtn.style.display = 'none';
    if (monthPlaceholder) monthPlaceholder.style.display = 'none';
    if (monthSelectWrap) monthSelectWrap.style.display = 'inline-flex';
    if (titleEl) titleEl.textContent = 'Monthly Study Overview';
    if (leadEl) leadEl.textContent = 'Review all scheduled study sessions across the selected month.';
    try { localStorage.setItem('careerdesk_subnav_routine', 'monthly'); } catch (e) { }
    showMonthlyRoutines();
  } else {
    if (mBox) mBox.hidden = true;
    if (dateNav) dateNav.hidden = false;
    if (cardWrap) cardWrap.hidden = false;
    if (routineActions) routineActions.hidden = false;
    if (routineSaveNote) routineSaveNote.hidden = false;
    if (mBtn) mBtn.classList.remove('active');
    if (dBtn) dBtn.classList.add('active');
    if (todayBtn) todayBtn.style.display = 'none';
    if (monthPlaceholder) monthPlaceholder.style.display = 'none';
    if (monthSelectWrap) monthSelectWrap.style.display = 'none';
    if (titleEl) titleEl.textContent = 'Daily Study Routine';
    if (leadEl) leadEl.textContent = 'Plan your next study block and keep your momentum moving.';
    try { localStorage.setItem('careerdesk_subnav_routine', 'daily'); } catch (e) { }
    updateMonthYearPlaceholder();
    renderDateSlider();
    renderRoutine();
  }
  if (window.lucide && typeof window.lucide.createIcons === 'function') {
    window.lucide.createIcons();
  }
}

function showMonthlyRoutines() {
  const box = document.getElementById('monthlyRoutineView');
  if (!box) return;
  const prefix = `${currentViewYear}-${String(currentViewMonth + 1).padStart(2, '0')}-`;
  const byDate = (state.routine || []).filter(r => r.date && r.date.startsWith(prefix) && r.subject).reduce((map, row) => {
    (map[row.date] ||= []).push(row); return map;
  }, {});
  const dates = Object.keys(byDate).sort();
  box.hidden = false;
  box.innerHTML = dates.length ? dates.map((date, idx) => {
    const rows = byDate[date].sort((a, b) => (a.startTime || '').localeCompare(b.startTime || ''));
    return `<article class="monthly-routine-card" data-month-date="${escapeAttr(date)}" style="animation-delay: ${idx * 35}ms;">
      <div class="monthly-routine-head">
        <div style="display:flex; align-items:center; gap:8px;">
          <i data-lucide="calendar" style="width:16px; height:16px; color:var(--accent1);"></i>
          <strong>${escapeHtml(bnDateLabel(date))}</strong>
          <span class="badge" style="font-size:11px; padding:2px 8px; border-radius:12px; background:var(--surface-strong); border:1px solid var(--border); color:var(--text-soft); font-weight:600;">${rows.length} ${rows.length === 1 ? 'block' : 'blocks'}</span>
        </div>
        <div class="monthly-routine-actions btn-group">
          <button class="pill action-btn-edit" data-month-edit="${escapeAttr(date)}" title="Open this date in daily routine editor" aria-label="Edit Date Routine">${ICON.edit} <span>Open &amp; Edit</span></button>
          <button class="pill danger action-btn-del" data-month-delete="${escapeAttr(date)}" title="Delete Routine for this date" aria-label="Delete Date Routine">${ICON.trash} <span>Delete</span></button>
        </div>
      </div>
      <table class="mini-routine">
        <thead>
          <tr style="color:var(--text-muted); font-size:11.5px; text-transform:uppercase; letter-spacing:0.04em;">
            <th style="text-align:left; padding:6px 4px; font-weight:600; width:25%;">Time</th>
            <th style="text-align:left; padding:6px 4px; font-weight:600; width:30%;">Subject</th>
            <th style="text-align:left; padding:6px 4px; font-weight:600;">Topic / Tasks</th>
          </tr>
        </thead>
        <tbody>
          ${rows.map(r => `<tr>
            <td style="font-family:var(--font-mono); font-size:12px; color:var(--accent2);">${escapeHtml(formatTime12(r.startTime))} – ${escapeHtml(formatTime12(r.endTime))}</td>
            <td style="font-weight:600; color:var(--text);">${escapeHtml(typeof getSubjectDisplayName === 'function' ? getSubjectDisplayName(r.subject) : (r.subject || 'No Subject'))}</td>
            <td style="color:var(--text-soft);">${escapeHtml(r.task || '—')}</td>
          </tr>`).join('')}
        </tbody>
      </table>
    </article>`;
  }).join('') : `
    <div class="empty-state glass" style="text-align:center; padding:36px 20px; border:1px dashed var(--border); border-radius:16px; margin: 10px 0;">
      <div style="width:48px; height:48px; border-radius:50%; background:rgba(99,102,241,0.12); color:var(--accent1); display:flex; align-items:center; justify-content:center; margin:0 auto 12px;">
        <i data-lucide="calendar-x" style="width:24px; height:24px;"></i>
      </div>
      <h4 style="margin:0 0 6px; font-size:16px; color:var(--text);">No routines scheduled for this month</h4>
      <p style="margin:0 0 16px; color:var(--text-soft); font-size:13px;">You have no study blocks planned for ${document.getElementById('monthDropdown')?.selectedOptions[0]?.text || 'this month'}.</p>
      <button class="pill solid" id="monthlyBackToDailyBtn" type="button" style="display:inline-flex; align-items:center; gap:8px;">
        <i data-lucide="arrow-left"></i> Back to Day by Day Routine
      </button>
    </div>
  `;
  if (window.lucide && typeof window.lucide.createIcons === 'function') {
    window.lucide.createIcons();
  }
}

const dbdRoutineBtn = document.getElementById('dbdRoutineBtn');
if (dbdRoutineBtn) {
  dbdRoutineBtn.addEventListener('click', () => {
    // If user changed today to another, default if user clicks Daily (Day by Day) open today routine
    const now = new Date();
    currentViewYear = now.getFullYear();
    currentViewMonth = now.getMonth();
    routineDateFilter = dateKey(now.getTime());
    const mSel = document.getElementById('monthDropdown');
    if (mSel) mSel.value = `${currentViewYear}-${String(currentViewMonth + 1).padStart(2, '0')}`;
    toggleMonthlyRoutineView(false);
    renderDateSlider();
    renderRoutine();
  });
}

function restoreRoutineSubNav() {
  try {
    const saved = localStorage.getItem('careerdesk_subnav_routine');
    if (saved === 'monthly') {
      toggleMonthlyRoutineView(true);
    }
  } catch (e) { }
}
window.restoreRoutineSubNav = restoreRoutineSubNav;

const todayRoutineBtn = document.getElementById('todayRoutineBtn');
if (todayRoutineBtn) {
  todayRoutineBtn.addEventListener('click', () => {
    goToTodayRoutine();
  });
}

const monthlyRoutineBtn = document.getElementById('monthlyRoutineBtn');
if (monthlyRoutineBtn) {
  monthlyRoutineBtn.addEventListener('click', () => {
    const mBox = document.getElementById('monthlyRoutineView');
    const isOpen = mBox && !mBox.hidden;
    toggleMonthlyRoutineView(!isOpen);
  });
}

// Handle empty routine buttons
document.addEventListener('click', (e) => {
  if (e.target.closest('#emptyLoadDefaultsBtn')) {
    const todayTarget = routineDateFilter || dateKey(Date.now());
    const defaults = buildDefaultRoutine(todayTarget);
    if (!Array.isArray(state.routine)) state.routine = [];
    state.routine.push(...defaults);
    saveData();
    renderRoutine();
    if (typeof showToast === 'function') showToast('Recommended BCS routine loaded for today!');
  } else if (e.target.closest('#emptyAddBlockBtn')) {
    const inlineAdd = document.getElementById('inlineAddRowBtn');
    if (inlineAdd) inlineAdd.click();
  }
});

const monthlyRoutineView = document.getElementById('monthlyRoutineView');
if (monthlyRoutineView) {
  monthlyRoutineView.addEventListener('click', (e) => {
    const edit = e.target.closest('[data-month-edit]');
    const del = e.target.closest('[data-month-delete]');
    const back = e.target.closest('#monthlyBackToDailyBtn');
    if (back) {
      toggleMonthlyRoutineView(false);
      return;
    }
    if (edit) {
      const d = new Date(edit.dataset.monthEdit + 'T00:00:00');
      routineDateFilter = edit.dataset.monthEdit;
      currentViewYear = d.getFullYear();
      currentViewMonth = d.getMonth();
      const mSel = document.getElementById('monthDropdown');
      if (mSel) mSel.value = `${currentViewYear}-${String(currentViewMonth + 1).padStart(2, '0')}`;
      toggleMonthlyRoutineView(false);
    }
    if (del && window.confirm('Delete all routines for this date?')) {
      state.routine = state.routine.filter(r => r.date !== del.dataset.monthDelete);
      saveData();
      renderDateSlider();
      renderRoutine();
      showMonthlyRoutines();
    }
  });
}

