function updateQuoteAuthorAvatar(author) {
  const badge = document.getElementById('homeQuoteAuthorAvatar');
  if (!badge) return;

  const name = String(author || 'CareerDesk').trim() || 'CareerDesk';
  if (badge.dataset.author === name) return;
  badge.dataset.author = name;
  badge.title = name;

  const fallback = badge.querySelector('.quote-author-avatar-fallback');
  const existing = badge.querySelector('img');
  const src = Object.prototype.hasOwnProperty.call(AUTHOR_PHOTOS, name) ? AUTHOR_PHOTOS[name] : null;

  if (!src) {
    if (existing) existing.remove();
    if (fallback) fallback.style.display = '';
    return;
  }

  if (fallback) fallback.style.display = 'none';
  if (existing && existing.getAttribute('src') === src) return;
  const img = existing || document.createElement('img');
  img.alt = name;
  img.decoding = 'async';
  img.loading = 'lazy';
  img.addEventListener('error', () => {
    img.remove();
    if (fallback) fallback.style.display = '';
  }, { once: true });
  img.src = src;
  if (!existing) badge.prepend(img);
}

function stopQuoteTypewriter() {
  if (quoteTypewriterTimeout) {
    clearTimeout(quoteTypewriterTimeout);
    quoteTypewriterTimeout = null;
  }
  if (quoteHoldTimeout) {
    clearTimeout(quoteHoldTimeout);
    quoteHoldTimeout = null;
  }
}

function renderQuoteFrame() {
  stopQuoteTypewriter();

  if (quoteIsPaused) return;

  const textEl = document.getElementById('profileQuoteTypedText');
  const langTextEl = document.getElementById('profileQuoteLangText');
  const langBadgeEl = document.getElementById('profileQuoteLangBadge');
  const authorEl = document.getElementById('profileQuoteAuthorPill');
  const cursorEl = document.getElementById('profileQuoteCursor');
  const progressFill = document.getElementById('profileQuoteProgressFill');

  if (!textEl) return;

  const pool = getBilingualQuotesPool();
  const currentQuote = pool[((quoteActiveIndex % pool.length) + pool.length) % pool.length];
  if (!currentQuote) return;

  updateQuoteAuthorAvatar(currentQuote.author);

  // Determine current text
  const rawText = (quoteActiveLang === 'en' ? currentQuote.en : currentQuote.bn) || currentQuote.en || '';
  const cleanText = typeof cleanQuoteText === 'function' ? cleanQuoteText(rawText) : rawText.trim();
  // Update language badge & author
  if (langTextEl) langTextEl.textContent = quoteActiveLang === 'en' ? 'EN' : 'BN';
  if (langBadgeEl) {
    langBadgeEl.classList.toggle('bangla', quoteActiveLang === 'bn');
    langBadgeEl.title = quoteActiveLang === 'en' ? 'Language: English (Click for বাংলা)' : 'Language: বাংলা (Click for English)';
  }
  if (authorEl) {
    const authorName = typeof cleanQuoteAuthor === 'function' ? cleanQuoteAuthor(currentQuote.author) : (currentQuote.author || 'CareerDesk');
    authorEl.textContent = `— ${authorName}`;
  }

  textEl.textContent = cleanText;
  textEl.classList.remove('quote-text-fade-out');
  textEl.classList.remove('quote-text-reveal');
  void textEl.offsetWidth;
  textEl.classList.add('quote-text-reveal');
  quotePhase = 'holding';
  quoteCharIndex = 0;
  if (cursorEl) cursorEl.classList.add('quote-cursor-hidden');
  if (progressFill) {
    progressFill.style.transition = 'none';
    progressFill.style.width = '0%';
    progressFill.style.opacity = '1';
  }
  quoteHoldRemaining = quoteHoldDuration;
  startQuoteHoldTimer();
}

// Kept as a compatibility alias for existing pause/resume callers.
function stepQuoteTypewriter() {
  renderQuoteFrame();
}

function startQuoteHoldTimer() {
  const progressFill = document.getElementById('profileQuoteProgressFill');
  if (progressFill) {
    progressFill.style.transition = `width ${quoteHoldRemaining}ms linear`;
    progressFill.style.width = '100%';
  }
  quoteHoldStartTime = Date.now();

  quoteHoldTimeout = setTimeout(() => {
    // Graceful smooth fade transition to next language or next quote
    smoothTransitionNext(false);
  }, quoteHoldRemaining);
}

function pauseQuoteHoldTimer() {
  if (quoteHoldTimeout) {
    clearTimeout(quoteHoldTimeout);
    quoteHoldTimeout = null;
    const elapsed = Date.now() - quoteHoldStartTime;
    quoteHoldRemaining = Math.max(0, quoteHoldRemaining - elapsed);
    const progressFill = document.getElementById('profileQuoteProgressFill');
    if (progressFill) {
      const computedWidth = window.getComputedStyle(progressFill).width;
      progressFill.style.transition = 'none';
      progressFill.style.width = computedWidth;
    }
  }
}

function resumeQuoteHoldTimer() {
  if (quotePhase === 'holding' && !quoteIsPaused && !quoteIsHovered) {
    startQuoteHoldTimer();
  }
}

function smoothTransitionNext(forceNextQuote = false) {
  stopQuoteTypewriter();
  quotePhase = 'transitioning';

  const textEl = document.getElementById('profileQuoteTypedText');
  const authorEl = document.getElementById('profileQuoteAuthorPill');
  const cursorEl = document.getElementById('profileQuoteCursor');
  const progressFill = document.getElementById('profileQuoteProgressFill');

  if (progressFill) {
    progressFill.style.transition = 'opacity 0.25s ease';
    progressFill.style.opacity = '0';
  }

  if (textEl) textEl.classList.add('quote-text-fade-out');
  if (authorEl) authorEl.classList.add('quote-text-fade-out');
  if (cursorEl) cursorEl.classList.add('quote-cursor-hidden');

  setTimeout(() => {
    const pool = getBilingualQuotesPool();
    if (forceNextQuote) {
      quoteActiveLang = 'en';
      quoteActiveIndex = (quoteActiveIndex + 1) % pool.length;
    } else {
      if (quoteActiveLang === 'en') {
        quoteActiveLang = 'bn';
      } else {
        quoteActiveLang = 'en';
        quoteActiveIndex = (quoteActiveIndex + 1) % pool.length;
      }
    }

    quoteCharIndex = 0;
    quotePhase = 'holding';

    if (textEl) {
      textEl.textContent = '';
      textEl.classList.remove('quote-text-fade-out');
    }
    if (authorEl) {
      authorEl.classList.remove('quote-text-fade-out');
    }
    if (cursorEl) cursorEl.classList.add('quote-cursor-hidden');

    if (progressFill) {
      progressFill.style.transition = 'none';
      progressFill.style.width = '0%';
      progressFill.style.opacity = '1';
    }

    quoteTypewriterTimeout = setTimeout(renderQuoteFrame, 340);
  }, 320);
}

function toggleQuoteTypewriterPause() {
  quoteIsPaused = !quoteIsPaused;
  const pauseBtns = document.querySelectorAll('#btnToggleQuotePause');

  if (quoteIsPaused) {
    if (quotePhase === 'holding') pauseQuoteHoldTimer();
    stopQuoteTypewriter();
    pauseBtns.forEach(btn => {
      btn.innerHTML = '<i data-lucide="play" style="width:13px;height:13px;"></i>';
      btn.title = 'Resume quote typing animation';
    });
    if (window.lucide && typeof window.lucide.createIcons === 'function') window.lucide.createIcons();
  } else {
    pauseBtns.forEach(btn => {
      btn.innerHTML = '<i data-lucide="pause" style="width:13px;height:13px;"></i>';
      btn.title = 'Pause quote typing animation';
    });
    if (window.lucide && typeof window.lucide.createIcons === 'function') window.lucide.createIcons();
    if (quotePhase === 'holding') {
      resumeQuoteHoldTimer();
    } else {
      stepQuoteTypewriter();
    }
  }
}

function skipToNextQuoteTypewriter() {
  smoothTransitionNext(true);
}

function toggleQuoteLanguageManual() {
  stopQuoteTypewriter();
  quotePhase = 'transitioning';

  const textEl = document.getElementById('profileQuoteTypedText');
  const authorEl = document.getElementById('profileQuoteAuthorPill');
  const cursorEl = document.getElementById('profileQuoteCursor');

  if (textEl) textEl.classList.add('quote-text-fade-out');
  if (authorEl) authorEl.classList.add('quote-text-fade-out');
  if (cursorEl) cursorEl.classList.add('quote-cursor-hidden');

  setTimeout(() => {
    quoteActiveLang = quoteActiveLang === 'en' ? 'bn' : 'en';
    quoteCharIndex = 0;
    quotePhase = 'holding';

    if (textEl) {
      textEl.textContent = '';
      textEl.classList.remove('quote-text-fade-out');
    }
    if (authorEl) {
      authorEl.classList.remove('quote-text-fade-out');
    }
    if (cursorEl) cursorEl.classList.add('quote-cursor-hidden');

    const progressFill = document.getElementById('profileQuoteProgressFill');
    if (progressFill) {
      progressFill.style.transition = 'none';
      progressFill.style.width = '0%';
    }

    quoteTypewriterTimeout = setTimeout(renderQuoteFrame, 260);
  }, 300);
}

function initProfileQuoteTypewriter() {
  const container = document.getElementById('profileHeroQuoteTicker');
  const textEl = document.getElementById('profileQuoteTypedText');
  if (!container || !textEl) return;

  stopQuoteTypewriter();

  // Wire all Pause Buttons
  document.querySelectorAll('#btnToggleQuotePause').forEach(btn => {
    if (!btn._bound) {
      btn._bound = true;
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        toggleQuoteTypewriterPause();
      });
    }
  });

  // Wire all Next/Cycle Buttons (signed-in & guest)
  document.querySelectorAll('.btn-cycle-profile-hero-quote, #btnCycleProfileHeroQuote, #btnCycleProfileHeroQuoteGuest').forEach(btn => {
    if (!btn._bound) {
      btn._bound = true;
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        skipToNextQuoteTypewriter();
      });
    }
  });

  // Wire all Language Badges
  document.querySelectorAll('#profileQuoteLangBadge').forEach(badge => {
    if (!badge._bound) {
      badge._bound = true;
      badge.addEventListener('click', (e) => {
        e.stopPropagation();
        toggleQuoteLanguageManual();
      });
    }
  });

  // Hover Pause/Resume
  if (container && !container._boundHover) {
    container._boundHover = true;
    container.addEventListener('mouseenter', () => {
      quoteIsHovered = true;
      if (quotePhase === 'holding' && !quoteIsPaused) pauseQuoteHoldTimer();
    });
    container.addEventListener('mouseleave', () => {
      quoteIsHovered = false;
      if (quotePhase === 'holding' && !quoteIsPaused) resumeQuoteHoldTimer();
    });
  }

  // Start typing from beginning if fresh
  quoteCharIndex = 0;
  quotePhase = 'holding';
  textEl.textContent = '';
  renderQuoteFrame();
}

window.initProfileQuoteTypewriter = initProfileQuoteTypewriter;
window.skipToNextQuoteTypewriter = skipToNextQuoteTypewriter;
window.toggleQuoteTypewriterPause = toggleQuoteTypewriterPause;

/* Source: assets/js/features/tracker.js */
/* ==========================================================================
   CareerDesk — Study Tracker & Focus Engine: Timers, Heatmap & Analytics
   ========================================================================== */

// ===== Tracker =====
/* ── Shared timer clock: dashboard + tracker rings ─────────────────────────
   One renderer drives both clocks so the ring, the digits and the status
   line always agree. A chosen duration is a countdown: the ring starts full
   and depletes as the time is spent. Stopwatch mode has no target, so the
   ring sweeps toward empty once per minute. */
window.getCareerDeskTimerRingState = function () {
  const breakMode = window.trackerTimerMode === 'break';
  const selectedMinutes = Number(typeof selectedDuration === 'number' ? selectedDuration : 0) || 0;
  const countdownTotal = Math.max(0, selectedMinutes) * 60;
  const countdownActive = !!window.isCustomCountdownActive && countdownTotal > 0;

  if (countdownActive) {
    const remaining = Math.max(0, Math.min(countdownTotal, Number(customCountdownSecs) || 0));
    return { mode: 'countdown', breakMode, running: true, remaining, total: countdownTotal };
  }

  const active = (typeof state !== 'undefined' && state) ? state.activeSession : null;
  if (active && !breakMode) {
    const elapsed = Math.max(0, Math.floor((Date.now() - Number(active.start)) / 1000));
    return { mode: 'stopwatch', breakMode: false, running: true, remaining: 60 - (elapsed % 60), total: 60 };
  }

  if (countdownTotal > 0) {
    return { mode: 'countdown', breakMode, running: false, remaining: countdownTotal, total: countdownTotal };
  }

  return { mode: 'stopwatch', breakMode: false, running: false, remaining: 0, total: 60 };
};

window.updateCareerDeskTimerRings = function (snapshot) {
  const ringState = snapshot || window.getCareerDeskTimerRingState();
  const total = Math.max(1, Number(ringState.total) || 60);
  const remaining = Math.max(0, Math.min(total, Number(ringState.remaining) || 0));
  const remainingRatio = remaining / total;
  const complete = ringState.mode === 'countdown' && remaining <= 0;

  document.querySelectorAll('[data-careerdesk-timer-ring]').forEach((ring) => {
    const circumference = 2 * Math.PI * Number(ring.getAttribute('r') || 82);
    ring.style.strokeDasharray = String(circumference);
    ring.style.strokeDashoffset = String(circumference * (1 - remainingRatio));
  });

  document.querySelectorAll('[data-careerdesk-timer-ring-container]').forEach((el) => {
    el.classList.toggle('is-running', !!ringState.running);
    el.classList.toggle('is-countdown', ringState.mode === 'countdown');
    el.classList.toggle('is-stopwatch', ringState.mode === 'stopwatch');
    el.classList.toggle('is-complete', complete);
  });

  const label = complete
    ? 'Session complete'
    : ringState.running
      ? (ringState.breakMode ? 'On a break' : (ringState.mode === 'stopwatch' ? 'Tracking your time' : 'Stay focused'))
      : 'Ready to focus';
  const minutes = Math.round(total / 60);
  const unit = ringState.breakMode ? 'break' : (ringState.running ? 'focus' : 'session');
  const meta = ringState.mode === 'countdown' ? `${minutes} min ${unit}` : 'Stopwatch';

  document.querySelectorAll('[data-careerdesk-timer-label]').forEach((el) => { el.textContent = label; });
  document.querySelectorAll('[data-careerdesk-timer-meta]').forEach((el) => { el.textContent = meta; });
};

window.syncCareerDeskTimerRings = function () {
  window.updateCareerDeskTimerRings();
};

/* Re-render both clocks after any tracker state change. */
function syncTimerRingUI() {
  if (typeof window.syncCareerDeskTimerRings === 'function') window.syncCareerDeskTimerRings();
}

const sessionSubjectSel = document.getElementById('sessionSubject');
const sessionCustomInput = document.getElementById('sessionCustomSubject');
const timerDisplay = document.getElementById('timerDisplay');
const timerSub = document.getElementById('timerSub');
const startBtn = document.getElementById('startBtn');
const stopBtn = document.getElementById('stopBtn');
const targetHoursInput = document.getElementById('targetHours');

// ==========================================
// FIRST-TIME USER ONBOARDING SUBJECT WIZARD
// ==========================================

// Guard: Ensure state is initialized before accessing DOM elements
if (typeof state === 'undefined') {
   console.warn('⚠️ State not yet initialized. Core.js must load before tracker.js');
}

const CURRICULUM_SUBJECT_CHOICES = (typeof BANGLADESH_CURRICULUM_DATA !== 'undefined' && BANGLADESH_CURRICULUM_DATA.jobSeeker && BANGLADESH_CURRICULUM_DATA.jobSeeker.primarySubjects) || [
  { name: 'Bangla', bn: 'বাংলা ভাষা ও সাহিত্য', desc: 'প্রাচীন, মধ্য ও আধুনিক যুগ, ব্যাকরণ ও সাহিত্য' },
  { name: 'English', bn: 'English Language & Literature', desc: 'Grammar, Vocabulary, Comprehension & Literature' },
  { name: 'Mathematics', bn: 'গণিত ও গাণিতিক যুক্তি', desc: 'পাটিগণিত, বীজগণিত, জ্যামিতি ও বিশ্লেষণ' },
  { name: 'General Knowledge', bn: 'সাধারণ জ্ঞান (বাংলাদেশ ও আন্তর্জাতিক)', desc: 'ইতিহাস, মুক্তিযুদ্ধ, বিজ্ঞান, আইসিটি ও আন্তর্জাতিক' }
];

function openOnboardingModal(isReset = false) {
  const modal = document.getElementById('onboardingModal');
  const grid = document.getElementById('onboardingSubjectGrid');
  if (!modal || !grid) return;

  let activeSet;
  if (isReset) {
    activeSet = new Set(CURRICULUM_SUBJECT_CHOICES.map(c => canonicalSubjectName(c.name).toLowerCase()));
  } else {
    const currentActive = masterSubjectList(false);
    if (currentActive.length > 0 && Array.isArray(state.deletedSubjects) && state.deletedSubjects.length > 0) {
      activeSet = new Set(currentActive.map(s => canonicalSubjectName(s).toLowerCase()));
    } else {
      activeSet = new Set(CURRICULUM_SUBJECT_CHOICES.map(c => canonicalSubjectName(c.name).toLowerCase()));
    }
  }

  grid.innerHTML = CURRICULUM_SUBJECT_CHOICES.map(item => {
    const canonical = canonicalSubjectName(item.name).toLowerCase();
    const isChecked = activeSet.has(canonical);
    return `
      <label class="onboarding-subject-item ${isChecked ? 'selected' : ''}" data-subject-name="${escapeAttr(item.name)}">
        <input type="checkbox" class="onboarding-checkbox" value="${escapeAttr(item.name)}" ${isChecked ? 'checked' : ''}>
        <div class="onboarding-item-info">
          <span class="onboarding-item-title">${escapeHtml(item.name)}</span>
          <span class="onboarding-item-alias">${escapeHtml(item.bn)}</span>
          <span class="onboarding-item-desc">${escapeHtml(item.desc)}</span>
        </div>
      </label>
    `;
  }).join('');

  updateOnboardingSelectedCount();

  modal.style.display = 'flex';
  setTimeout(() => {
    modal.classList.add('open');
  }, 20);

  if (window.lucide && typeof window.lucide.createIcons === 'function') {
    window.lucide.createIcons();
  }
}

function closeOnboardingModal() {
  const modal = document.getElementById('onboardingModal');
  if (!modal) return;
  modal.classList.remove('open');
  setTimeout(() => {
    modal.style.display = 'none';
  }, 250);
}

function updateOnboardingSelectedCount() {
  const grid = document.getElementById('onboardingSubjectGrid');
  const badge = document.getElementById('onboardingSelectedCount');
  if (!grid || !badge) return;
  const checkedCount = grid.querySelectorAll('.onboarding-checkbox:checked').length;
  const totalCount = CURRICULUM_SUBJECT_CHOICES.length;
  badge.textContent = `${checkedCount} of ${totalCount}`;
}

// Click delegation on onboarding items
const onboardingGrid = document.getElementById('onboardingSubjectGrid');
if (onboardingGrid) {
  onboardingGrid.addEventListener('change', (e) => {
    if (e.target.classList.contains('onboarding-checkbox')) {
      const item = e.target.closest('.onboarding-subject-item');
      if (item) item.classList.toggle('selected', e.target.checked);
      updateOnboardingSelectedCount();
    }
  });
}

// Select All button
const onboardingSelectAllBtn = document.getElementById('onboardingSelectAllBtn');
if (onboardingSelectAllBtn) {
  onboardingSelectAllBtn.addEventListener('click', () => {
    const grid = document.getElementById('onboardingSubjectGrid');
    if (!grid) return;
    grid.querySelectorAll('.onboarding-checkbox').forEach(cb => {
      cb.checked = true;
      const item = cb.closest('.onboarding-subject-item');
      if (item) item.classList.add('selected');
    });
    updateOnboardingSelectedCount();
  });
}

// Deselect All button
const onboardingClearAllBtn = document.getElementById('onboardingClearAllBtn');
if (onboardingClearAllBtn) {
  onboardingClearAllBtn.addEventListener('click', () => {
    const grid = document.getElementById('onboardingSubjectGrid');
    if (!grid) return;
    grid.querySelectorAll('.onboarding-checkbox').forEach(cb => {
      cb.checked = false;
      const item = cb.closest('.onboarding-subject-item');
      if (item) item.classList.remove('selected');
    });
    updateOnboardingSelectedCount();
  });
}

// Confirm selection button
const confirmOnboardingBtn = document.getElementById('confirmOnboardingSubjectsBtn');
if (confirmOnboardingBtn) {
  confirmOnboardingBtn.addEventListener('click', () => {
    const grid = document.getElementById('onboardingSubjectGrid');
    if (!grid) return;
    const checkedInputs = Array.from(grid.querySelectorAll('.onboarding-checkbox:checked'));
    if (checkedInputs.length === 0) {
      showToast('Please select at least one subject to get started', true);
      return;
    }

    const selectedNames = checkedInputs.map(cb => cb.value.trim());
    const selectedCanonicals = new Set(selectedNames.map(s => canonicalSubjectName(s).toLowerCase()));

    if (!Array.isArray(state.deletedSubjects)) state.deletedSubjects = [];
    if (!Array.isArray(state.customSubjects)) state.customSubjects = [];

    // Collect all known subjects across system to ensure unselected items are removed
    const allKnown = masterSubjectList(true);
    CURRICULUM_SUBJECT_CHOICES.forEach(c => {
      if (!allKnown.some(s => canonicalSubjectName(s).toLowerCase() === canonicalSubjectName(c.name).toLowerCase())) {
        allKnown.push(c.name);
      }
    });

    allKnown.forEach(sub => {
      const subCanonical = canonicalSubjectName(sub).toLowerCase();
      const isSelected = selectedCanonicals.has(subCanonical);
      if (!isSelected) {
        if (!state.deletedSubjects.some(d => canonicalSubjectName(d).toLowerCase() === subCanonical)) {
          state.deletedSubjects.push(sub);
        }
        state.customSubjects = state.customSubjects.filter(c => canonicalSubjectName(c).toLowerCase() !== subCanonical);
      } else {
        state.deletedSubjects = state.deletedSubjects.filter(d => canonicalSubjectName(d).toLowerCase() !== subCanonical);
        const isDefault = DEFAULT_SUBJECTS.some(d => canonicalSubjectName(d).toLowerCase() === subCanonical);
        if (!isDefault && !state.customSubjects.some(c => canonicalSubjectName(c).toLowerCase() === subCanonical)) {
          state.customSubjects.push(sub);
        }
      }
    });

    try { localStorage.setItem(ONBOARDING_KEY, 'true'); } catch (e) { }

    saveData();
    syncAllSubjectSelects();
    renderSubjectManager();
    renderRoutine();
    renderTrackerAll();
    renderCategories();

    closeOnboardingModal();
    showToast(`${selectedNames.length} subjects configured for your dashboard!`);
  });
}



function checkFirstTimeUser() {
  try {
    // First-time popup disabled: mark onboarding as done so no interrupting popup appears
    localStorage.setItem(ONBOARDING_KEY, 'true');
  } catch (e) { }
}

function refreshTimerSub() {
  if (state.activeSession || window.isCustomCountdownActive) return;
  const sub = document.getElementById('timerSub');
  if (!sub) return;
  if (timerMode === 'break') {
    const reason = document.getElementById('breakReason')?.value || 'Refreshment';
    sub.innerHTML = `<strong>${selectedDuration}-minute ${escapeHtml(reason.toLowerCase())}</strong> break — recharge before your next focus block`;
    return;
  }
  const subject = currentSubjectValue() || 'General';
  if (selectedDuration === 0) {
    sub.innerHTML = `<strong>${escapeHtml(subject)}</strong> — Stopwatch mode — click Start to track time`;
  } else {
    sub.innerHTML = `<strong>${escapeHtml(subject)}</strong> — ${selectedDuration} minute focus session`;
  }
}

if (sessionSubjectSel) {
  sessionSubjectSel.addEventListener('change', () => {
    if (sessionCustomInput) {
      sessionCustomInput.style.display = sessionSubjectSel.value === '__custom__' ? 'block' : 'none';
      if (sessionSubjectSel.value !== '__custom__') {
        sessionCustomInput.value = '';
      }
    }
    refreshTimerSub();
  });
}
if (sessionCustomInput) {
  sessionCustomInput.addEventListener('input', refreshTimerSub);
}
const breakReasonSelect = document.getElementById('breakReason');
if (breakReasonSelect) breakReasonSelect.addEventListener('change', refreshTimerSub);

function currentSubjectValue() {
  if (!sessionSubjectSel) return '';
  if (sessionSubjectSel.value === '__custom__' && sessionCustomInput) return sessionCustomInput.value.trim();
  return sessionSubjectSel.value;
}

if (startBtn) {
  startBtn.addEventListener('click', () => {
    // Countdown mode (selectedDuration > 0) is fully handled by the document-level
    // capture listener below. This handler is exclusively for stopwatch mode (duration = 0).
    if (selectedDuration !== 0) return;
    if (!timerMode) return;
    const subj = currentSubjectValue();
    if (!subj) {
      if (sessionCustomInput) {
        sessionCustomInput.style.display = 'block';
        sessionCustomInput.focus();
      }
      showToast('Please enter or select a study subject', true);
      return;
    }
    const canonical = (typeof addSubject === 'function' ? addSubject(subj) : subj) || subj;
    state.activeSession = { subject: canonical, start: Date.now() };
    saveData();
    renderTrackerAll();
  });
}

if (stopBtn) {
  stopBtn.addEventListener('click', () => {
    // Only handle the stopwatch (selectedDuration === 0) case here.
    // Countdown stop is handled by the document-level capture listener below.
    if (selectedDuration !== 0) return;
    if (!state.activeSession) return;
    const end = Date.now();
    const elapsedMs = Math.max(0, end - Number(state.activeSession.start));
    if (elapsedMs < STOPWATCH_MIN_DURATION_MS) {
      state.activeSession = null;
      saveData();
      renderTrackerAll();
      showToast('Stopwatch session under 1 minute was not counted.');
      return;
    }
    const durationMin = Math.round(elapsedMs / 60000);
    state.sessions.push({ id: Date.now(), subject: state.activeSession.subject, start: state.activeSession.start, end, duration: durationMin });
    state.activeSession = null;
    saveData();
    renderTrackerAll();
    showToast('Stopwatch session saved!');
  });
}

function setDailyTarget(hours) {
  if (getRoutineGoalMinutes(todayKey())) return;
  const v = parseFloat(hours);
  state.dailyTargetMinutes = isNaN(v) || v < 0 ? 240 : Math.round(v * 60);
  renderProgress();
  saveData();
}
if (targetHoursInput) {
  targetHoursInput.addEventListener('change', () => setDailyTarget(targetHoursInput.value));
  targetHoursInput.addEventListener('input', () => setDailyTarget(targetHoursInput.value));
}
function tickTimer() {
  syncTimerRingUI();
  const now = new Date();
  const refreshKey = `${dateKey(now.getTime())}:${now.getHours()}:${now.getMinutes()}`;
  if (refreshKey !== lastSubjectBarsRefreshKey) renderSubjectBars();
 if (window.isCustomCountdownActive || (window.selectedTimerDuration && window.selectedTimerDuration > 0)) {
    if (typeof window.syncDashboardTrackerTimer === 'function') window.syncDashboardTrackerTimer();
    return;
  }
  const orb = document.getElementById('clockOrb');
  if (!timerDisplay) return;
  if (!state.activeSession) {
    timerDisplay.textContent = selectedDuration === 0 ? '∞' : '00:00:00';
    if (timerSub && !timerSub.textContent.trim()) {
      timerSub.innerHTML = 'Select a subject and duration to begin focus session';
    }
    if (orb) orb.classList.remove('active');
    syncMiniTimerWidget();
    if (typeof window.syncDashboardTrackerTimer === 'function') window.syncDashboardTrackerTimer();
    return;
  }
  if (orb) orb.classList.add('active');
  const secs = Math.floor((Date.now() - state.activeSession.start) / 1000);
  timerDisplay.textContent = fmtClock(secs);
  if (timerSub) {
    timerSub.innerHTML = '<span class="timer-dot"></span> Studying <strong>' + escapeHtml(state.activeSession.subject) + '</strong> in progress';
  }
  syncMiniTimerWidget();
  renderTodaySessions();
  if (typeof window.syncDashboardTrackerTimer === 'function') window.syncDashboardTrackerTimer();
}

function renderTodaySessions() {
  const box = document.getElementById('todaySessions');
  if (!box) return;
  const studyEntries = state.sessions
    .filter(s => dateKey(s.start) === todayKey())
    .map(s => ({ ...s, entryType: 'study' }));
  const breakEntries = getTodayBreakEntries()
    .map(entry => ({ ...entry, entryType: 'break', subject: entry.reason || 'Break' }));
  const liveEntries = [];
  if (state.activeSession) {
    liveEntries.push({
      id: 'active-study',
      start: state.activeSession.start,
      duration: Math.max(0, Math.floor((Date.now() - state.activeSession.start) / 60000)),
      subject: state.activeSession.subject,
      entryType: 'active-study'
    });
  }
  if (window.isCustomCountdownActive && timerMode === 'break') {
    liveEntries.push({
      id: 'active-break',
      start: Date.now() - Math.max(0, (selectedDuration * 60) - customCountdownSecs) * 1000,
      duration: Math.max(0, Math.floor(((selectedDuration * 60) - customCountdownSecs) / 60)),
      subject: document.getElementById('breakReason')?.value || 'Refreshment',
      entryType: 'active-break'
    });
  }
  const list = [...studyEntries, ...breakEntries, ...liveEntries].sort((a, b) => b.start - a.start);
  if (!list.length) { box.innerHTML = ''; return; }
  box.innerHTML = list.map(s => {
    const st = new Date(s.start), en = s.end ? new Date(s.end) : new Date();
    const timeStr = st.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' }) + ' – ' + en.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });
    const goal = getRoutineGoalMinutes(todayKey()) || state.dailyTargetMinutes || 240;
    const pct = Math.min(100, Math.max(8, Math.round((s.duration / Math.max(1, goal)) * 100)));
    const isBreak = s.entryType === 'break' || s.entryType === 'active-break';
    const isActive = s.entryType === 'active-study' || s.entryType === 'active-break';
    const label = isBreak ? `${escapeHtml(s.subject)} Break` : escapeHtml(s.subject);
    return `<div class="session-item">
      <div class="session-item-header">
        <div class="s-subject">${label}${isActive ? ' <span class="timer-dot"></span>' : ''}</div>
        <div style="display:flex; align-items:center; gap:6px;">
          <span class="s-badge">${isActive ? 'Live' : fmtHM(s.duration)}</span>
          ${!isActive && !isBreak ? `<button class="s-del-btn" title="Delete session" data-delsession="${s.id}">${ICON.x}</button>` : ''}
        </div>
      </div>
      <div class="s-progress">
        <div class="s-progress-track">
          <div class="s-progress-fill" style="width:${pct}%"></div>
        </div>
      </div>
      <div class="s-meta">${timeStr}</div>
    </div>`;
  }).join('');
}

const todaySessionsBox = document.getElementById('todaySessions');
if (todaySessionsBox) {
  todaySessionsBox.addEventListener('click', (e) => {
    const del = e.target.closest('[data-delsession]');
    if (del) {
      const id = del.dataset.delsession;
      state.sessions = state.sessions.filter(s => String(s.id) !== id);
      saveData();
      renderTrackerAll();
      showToast('Session deleted');
    }
  });
}

function renderProgress() {
  const todayTotal = state.sessions.filter(s => dateKey(s.start) === todayKey()).reduce((a, s) => a + s.duration, 0);
  const routineGoal = getRoutineGoalMinutes(todayKey());
  const target = routineGoal || state.dailyTargetMinutes || 240;
  const pct = Math.min(100, Math.round((todayTotal / target) * 100));

  const progressFill = document.getElementById('progressFill');
  const progressLabelLeft = document.getElementById('progressLabelLeft');
  const progressLabelRight = document.getElementById('progressLabelRight');
  const goalLabel = document.getElementById('trackerGoalLabel');
  const streakLine = document.getElementById('streakLine');
  const verdict = document.getElementById('verdictBox');

  if (progressFill) progressFill.style.width = pct + '%';
  if (progressLabelLeft) progressLabelLeft.textContent = fmtHM(todayTotal) + ' studied';
  if (progressLabelRight) progressLabelRight.textContent = pct + '%';
  if (goalLabel) goalLabel.textContent = routineGoal ? "Today's Routine Goal" : 'Daily Goal';
  if (targetHoursInput) {
    targetHoursInput.value = (target / 60).toString();
    targetHoursInput.readOnly = !!routineGoal;
    targetHoursInput.title = routineGoal ? 'Automatically set from today’s timed routine blocks' : 'Set a daily goal when no timed routine is scheduled';
  }
  if (verdict) {
    if (todayTotal === 0) {
      verdict.textContent = 'No study logged yet today — start your first session, you can do it!';
    } else if (pct >= 100) {
      verdict.textContent = routineGoal ? 'Today’s routine goal completed! Outstanding effort.' : 'Daily target completed! Outstanding effort today.';
    } else if (pct >= 75) {
      verdict.textContent = 'Almost there — just a little more focus to reach your goal.';
    } else if (pct >= 40) {
      verdict.textContent = 'Good start, keep up the momentum with another session.';
    } else {
      verdict.textContent = 'Study time is low today — jump into another focused session now.';
    }
  }

  let streak = 0;
  for (let i = 1; i <= 60; i++) {
    const d = new Date(); d.setDate(d.getDate() - i);
    const key = dateKey(d.getTime());
    const total = state.sessions.filter(s => dateKey(s.start) === key).reduce((a, s) => a + s.duration, 0);
    const dayGoal = getRoutineGoalMinutes(key) || state.dailyTargetMinutes || 240;
    if (total >= dayGoal) streak++; else break;
  }
  if (pct >= 100) streak++;
  if (streakLine) {
    streakLine.textContent = streak > 0
      ? 'Target Streak: ' + streak + (streak === 1 ? ' day' : ' days')
      : 'Start your study streak today!';
  }
}

function getRoutineGoalMinutes(date = todayKey()) {
  if (!Array.isArray(state.routine)) return 0;
  return state.routine.reduce((total, item) => {
    if (!item || item.date !== date) return total;
    const start = /^([01]\d|2[0-3]):([0-5]\d)$/.exec(String(item.startTime || ''));
    const end = /^([01]\d|2[0-3]):([0-5]\d)$/.exec(String(item.endTime || ''));
    if (!start || !end) return total;
    const startMinute = Number(start[1]) * 60 + Number(start[2]);
    const endMinute = Number(end[1]) * 60 + Number(end[2]);
    return total + (endMinute > startMinute ? endMinute - startMinute : 0);
  }, 0);
}


let lastSubjectBarsRefreshKey = '';

function renderSubjectBars() {
  const box = document.getElementById('subjectBars');
  if (!box) return;
  const now = new Date();
  lastSubjectBarsRefreshKey = `${dateKey(now.getTime())}:${now.getHours()}:${now.getMinutes()}`;
  const plan = typeof window.getTodayStudyPlanProgress === 'function'
    ? window.getTodayStudyPlanProgress()
    : [];
  if (plan.length) {
    const subjects = new Map();
    plan.forEach(block => {
      const subject = typeof canonicalSubjectName === 'function'
        ? canonicalSubjectName(block.subject || 'Study block')
        : (block.subject || 'Study block');
      const key = subject.trim().toLowerCase();
      const entry = subjects.get(key) || {
        subject,
        plannedMinutes: 0,
        trackedMinutes: 0,
        blocks: []
      };
      entry.plannedMinutes += block.duration;
      entry.trackedMinutes += block.trackedMinutes;
      entry.blocks.push(block);
      subjects.set(key, entry);
    });

    const plannedSubjects = new Set(subjects.keys());
    const unplannedSubjects = new Map();
    (Array.isArray(state.sessions) ? state.sessions : [])
      .filter(session => session && dateKey(session.start) === todayKey())
      .forEach(session => {
        const subject = typeof canonicalSubjectName === 'function'
          ? canonicalSubjectName(session.subject || 'General')
          : (session.subject || 'General');
        const key = subject.trim().toLowerCase();
        if (plannedSubjects.has(key)) return;
        unplannedSubjects.set(key, {
          subject,
          trackedMinutes: (unplannedSubjects.get(key)?.trackedMinutes || 0) + Math.max(0, Number(session.duration) || 0)
        });
      });
    const activeStudy = typeof window.getActiveTrackerStudySession === 'function'
      ? window.getActiveTrackerStudySession()
      : null;
    if (activeStudy && Number.isFinite(Number(activeStudy.start))) {
      const subject = typeof canonicalSubjectName === 'function'
        ? canonicalSubjectName(activeStudy.subject || 'General')
        : (activeStudy.subject || 'General');
      const key = subject.trim().toLowerCase();
      if (!plannedSubjects.has(key)) {
        const elapsedMinutes = Math.max(0, (now.getTime() - Number(activeStudy.start)) / 60000);
        unplannedSubjects.set(key, {
          subject,
          trackedMinutes: (unplannedSubjects.get(key)?.trackedMinutes || 0) + elapsedMinutes
        });
      }
    }

    const entries = [...subjects.values()].map(entry => {
      const completeCount = entry.blocks.filter(block => block.status === 'complete').length;
      const hasIncompleteBlock = entry.blocks.some(block => block.status === 'not-complete');
      const hasActiveBlock = entry.blocks.some(block => block.status === 'in-progress');
      const hasUpcomingBlock = entry.blocks.some(block => block.status === 'upcoming');
      let status = 'time-not-set';
      if (hasIncompleteBlock) status = 'not-complete';
      else if (hasActiveBlock) status = 'in-progress';
      else if (hasUpcomingBlock) status = 'upcoming';
      else if (entry.blocks.every(block => block.status === 'complete')) status = 'complete';
      return { ...entry, completeCount, status };
    });
    const chartEntries = [
      ...entries,
      ...[...unplannedSubjects.values()].map(entry => ({ ...entry, status: 'unplanned' }))
    ].sort((a, b) => b.trackedMinutes - a.trackedMinutes || a.subject.localeCompare(b.subject));

    const max = Math.max(...chartEntries.map(entry => entry.plannedMinutes || entry.trackedMinutes), 1);
    const statusLabels = {
      complete: 'Complete',
      'not-complete': 'Not complete',
      'in-progress': 'In progress',
      upcoming: 'Upcoming',
      'time-not-set': 'Time not set',
      unplanned: 'No plan'
    };
    box.innerHTML = chartEntries.map(entry => {
      const progress = entry.plannedMinutes
        ? Math.min(100, Math.round((entry.trackedMinutes / entry.plannedMinutes) * 100))
        : 0;
      const details = entry.blocks?.length
        ? `${entry.completeCount}/${entry.blocks.length} blocks complete · ${fmtHM(Math.round(entry.trackedMinutes))} / ${fmtHM(entry.plannedMinutes)}`
        : `${fmtHM(Math.round(entry.trackedMinutes))} tracked · no planned block`;
      const plannedWidth = Math.round(((entry.plannedMinutes || entry.trackedMinutes) / max) * 100);
      const trackedWidth = Math.round((entry.trackedMinutes / max) * 100);
      return `
        <div class="subj-bar-row subj-plan-row">
          <div class="subj-bar-label">
            <span>${escapeHtml(entry.subject)}</span>
            <span class="subj-plan-status subj-plan-status--${entry.status}">${statusLabels[entry.status]}</span>
          </div>
          <div class="subj-bar-track" role="progressbar" aria-label="${escapeAttr(entry.subject)} study plan progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress}">
            <span class="subj-plan-track" style="width:${plannedWidth}%"></span>
            <span class="subj-plan-fill" style="width:${trackedWidth}%"></span>
          </div>
          <div class="subj-plan-details">${details}</div>
        </div>
      `;
    }).join('');
    return;
  }

  const today = state.sessions.filter(s => dateKey(s.start) === todayKey());
  const byTotal = {};
  today.forEach(s => { byTotal[s.subject] = (byTotal[s.subject] || 0) + s.duration; });
  const activeStudy = typeof window.getActiveTrackerStudySession === 'function'
    ? window.getActiveTrackerStudySession()
    : null;
  if (activeStudy?.subject) {
    const elapsedMinutes = Math.max(0, (Date.now() - Number(activeStudy.start)) / 60000);
    byTotal[activeStudy.subject] = (byTotal[activeStudy.subject] || 0) + elapsedMinutes;
  }
  const entries = Object.entries(byTotal).sort((a, b) => b[1] - a[1]);
  if (!entries.length) { box.innerHTML = '<div class="empty-state">No study sessions logged today yet.</div>'; return; }
  const max = Math.max(...entries.map(e => e[1]));
  box.innerHTML = entries.map(([subj, min]) => `
    <div class="subj-bar-row">
      <div class="subj-bar-label"><span>${escapeHtml(subj)}</span><span>${fmtHM(min)}</span></div>
      <div class="subj-bar-track"><div class="subj-bar-fill" style="width:${Math.round((min / max) * 100)}%"></div></div>
    </div>
  `).join('');
}

window.renderTrackerSubjectBars = renderSubjectBars;

// ===== Customizable review period =====
let reviewPeriod = 'week';
let reviewCustomStart = null, reviewCustomEnd = null;

function getReviewRange() {
  const today = new Date(); today.setHours(23, 59, 59, 999);
  let start;
  if (reviewPeriod === 'week') {
    start = new Date(today); start.setDate(start.getDate() - 6); start.setHours(0, 0, 0, 0);
    return { start, end: today, granularity: 'day' };
  }
  if (reviewPeriod === 'month') {
    start = new Date(today); start.setDate(start.getDate() - 29); start.setHours(0, 0, 0, 0);
    return { start, end: today, granularity: 'week' };
  }
  if (reviewPeriod === 'year') {
    start = new Date(today); start.setMonth(start.getMonth() - 11); start.setDate(1); start.setHours(0, 0, 0, 0);
    return { start, end: today, granularity: 'month' };
  }
  const s = reviewCustomStart ? new Date(reviewCustomStart + 'T00:00:00') : new Date(today.getFullYear(), today.getMonth(), 1);
  const e = reviewCustomEnd ? new Date(reviewCustomEnd + 'T23:59:59') : today;
  const days = Math.round((e - s) / 86400000) + 1;
  const granularity = days <= 31 ? 'day' : (days <= 120 ? 'week' : 'month');
  return { start: s, end: e, granularity };
}

function buildReviewBuckets() {
  const { start, end, granularity } = getReviewRange();
  const buckets = [];
  const dayLabels = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const monthLabels = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

  if (granularity === 'day') {
    let cur = new Date(start);
    while (cur <= end) {
      const key = dateKey(cur.getTime());
      const total = state.sessions.filter(s => dateKey(s.start) === key).reduce((a, s) => a + s.duration, 0);
      buckets.push({ label: dayLabels[cur.getDay()], total, isToday: dateKey(Date.now()) === key });
      cur.setDate(cur.getDate() + 1);
    }
  } else if (granularity === 'week') {
    let cur = new Date(start); let wk = 1;
    while (cur <= end) {
      const wkStart = new Date(cur);
      const wkEnd = new Date(cur); wkEnd.setDate(wkEnd.getDate() + 6); wkEnd.setHours(23, 59, 59, 999);
      const cappedEnd = wkEnd < end ? wkEnd : end;
      const total = state.sessions.filter(s => { const d = new Date(s.start); return d >= wkStart && d <= cappedEnd; }).reduce((a, s) => a + s.duration, 0);
      buckets.push({ label: 'Wk ' + wk, total, isToday: false });
      cur.setDate(cur.getDate() + 7); wk++;
    }
  } else {
    let cur = new Date(start.getFullYear(), start.getMonth(), 1);
    while (cur <= end) {
      const mStart = new Date(cur.getFullYear(), cur.getMonth(), 1);
      const mEnd = new Date(cur.getFullYear(), cur.getMonth() + 1, 0, 23, 59, 59);
      const total = state.sessions.filter(s => { const d = new Date(s.start); return d >= mStart && d <= mEnd; }).reduce((a, s) => a + s.duration, 0);
      const now = new Date();
      buckets.push({ label: monthLabels[cur.getMonth()], total, isToday: cur.getFullYear() === now.getFullYear() && cur.getMonth() === now.getMonth() });
      cur.setMonth(cur.getMonth() + 1);
    }
  }
  return buckets;
}

function renderWeekChart() {
  const box = document.getElementById('weekChart');
  const target = getRoutineGoalMinutes(todayKey()) || state.dailyTargetMinutes || 1;
  const buckets = buildReviewBuckets();
  let maxVal = Math.max(1, target, ...buckets.map(b => b.total));
  box.innerHTML = buckets.map(b => {
    const h = Math.max(4, Math.round((b.total / maxVal) * 100));
    return `<div class="review-bar-col">
      <div class="review-bar ${b.total >= target && b.total > 0 ? 'met' : ''}" style="height:${h}%" title="${fmtHM(b.total)}"></div>
      <div class="review-bar-label">${b.label}${b.isToday ? ' •' : ''}</div>
    </div>`;
  }).join('');

  const { start, end } = getReviewRange();
  const fmt = (d) => d.getDate() + '/' + (d.getMonth() + 1);
  document.getElementById('reviewRangeLabel').textContent = fmt(start) + ' – ' + fmt(end);
}

document.getElementById('reviewPeriodSwitch').addEventListener('click', (e) => {
  if (!e.target.classList.contains('chip')) return;
  document.querySelectorAll('#reviewPeriodSwitch .chip').forEach(c => c.classList.remove('active'));
  e.target.classList.add('active');
  reviewPeriod = e.target.dataset.period;
  document.getElementById('reviewCustomRange').style.display = reviewPeriod === 'custom' ? 'flex' : 'none';
  renderWeekChart();
});
document.getElementById('reviewCustomApplyBtn').addEventListener('click', () => {
  reviewCustomStart = document.getElementById('reviewCustomStart').value || null;
  reviewCustomEnd = document.getElementById('reviewCustomEnd').value || null;
  renderWeekChart();
});

// ===== GitHub-style Study Activity Heatmap =====
function renderStudyHeatmap() {
  const grid = document.getElementById('studyHeatmapGrid');
  if (!grid) return;

  const today = new Date();
  today.setHours(23, 59, 59, 999);

  const dailyMinutes = {};
  const dailySessionsCount = {};

  if (Array.isArray(state.sessions)) {
    state.sessions.forEach(s => {
      if (!s.start) return;
      const dk = dateKey(s.start);
      const mins = s.duration || 0;
      dailyMinutes[dk] = (dailyMinutes[dk] || 0) + mins;
      dailySessionsCount[dk] = (dailySessionsCount[dk] || 0) + 1;
    });
  }

  if (state.activeSession && state.activeSession.start) {
    const todayDk = dateKey(Date.now());
    const elapsedMs = Date.now() - Number(state.activeSession.start);
    if (elapsedMs >= STOPWATCH_MIN_DURATION_MS) {
      const liveMins = Math.floor(elapsedMs / 60000);
      dailyMinutes[todayDk] = (dailyMinutes[todayDk] || 0) + liveMins;
      dailySessionsCount[todayDk] = (dailySessionsCount[todayDk] || 0) + 1;
    }
  }

  const allMins = Object.values(dailyMinutes).reduce((a, b) => a + b, 0);
  const totalHoursStr = (allMins / 60).toFixed(1) + 'h';
  const activeDaysCount = Object.keys(dailyMinutes).filter(k => dailyMinutes[k] > 0).length;

  let streak = 0;
  let checkDate = new Date();
  const todayKeyStr = dateKey(checkDate.getTime());
  if (dailyMinutes[todayKeyStr] > 0) {
    streak++;
    checkDate.setDate(checkDate.getDate() - 1);
  } else {
    checkDate.setDate(checkDate.getDate() - 1);
  }
  while (dailyMinutes[dateKey(checkDate.getTime())] > 0) {
    streak++;
    checkDate.setDate(checkDate.getDate() - 1);
  }

  const streakEl = document.getElementById('heatmapStreakDays');
  const totalEl = document.getElementById('heatmapTotalHours');
  const activeEl = document.getElementById('heatmapActiveDays');
  if (streakEl) streakEl.textContent = streak;
  if (totalEl) totalEl.textContent = totalHoursStr;
  if (activeEl) activeEl.textContent = activeDaysCount;

  const currentDayOfWeek = today.getDay();
  const numWeeks = 18;
  const totalDays = numWeeks * 7;
  const startDate = new Date(today);
  startDate.setDate(today.getDate() - totalDays + (6 - currentDayOfWeek) + 1);
  startDate.setHours(0, 0, 0, 0);

  const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  let html = '';
  let cur = new Date(startDate);

  for (let w = 0; w < numWeeks; w++) {
    let colHtml = '<div class="heatmap-col">';
    const colMonth = cur.getDate() <= 7 ? monthNames[cur.getMonth()] : '';
    colHtml += `<div class="heatmap-col-header">${colMonth}</div>`;

    for (let d = 0; d < 7; d++) {
      const dk = dateKey(cur.getTime());
      const isFuture = cur.getTime() > today.getTime();
      const mins = dailyMinutes[dk] || 0;
      const count = dailySessionsCount[dk] || 0;

      let lvl = 0;
      if (mins > 0 && mins < 60) lvl = 1;
      else if (mins >= 60 && mins < 120) lvl = 2;
      else if (mins >= 120 && mins < 240) lvl = 3;
      else if (mins >= 240) lvl = 4;

      const dateFormatted = cur.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' });
      const timeStr = mins >= 60 ? `${Math.floor(mins / 60)}h ${mins % 60}m` : `${mins}m`;
      const title = isFuture ? '' : `${dateFormatted}: ${mins > 0 ? `${timeStr} studied (${count} session${count > 1 ? 's' : ''})` : 'No study recorded'}`;

      if (isFuture) {
        colHtml += `<div class="heatmap-cell" style="opacity:0.06; pointer-events:none;"></div>`;
      } else {
        colHtml += `<div class="heatmap-cell lvl-${lvl}" data-date="${dk}" title="${title}"></div>`;
      }

      cur.setDate(cur.getDate() + 1);
    }
    colHtml += '</div>';
    html += colHtml;
  }

  grid.innerHTML = html;
}

function renderTrackerAll() {
  renderSubjectSelect();
  renderSubjectManager();
  tickTimer();
  refreshTimerSub();
  const isRunning = !!state.activeSession || !!window.isCustomCountdownActive;
  startBtn.style.display = isRunning ? 'none' : 'inline-flex';
  stopBtn.style.display = isRunning ? 'inline-flex' : 'none';
  renderTodaySessions();
  renderProgress();
  renderSubjectBars();
  renderWeekChart();
  renderTrackerRoutinePreview();
  update24hActivityUI();
  renderStudyHeatmap();
  syncMiniTimerWidget();
  if (typeof window.syncDashboardTrackerTimer === 'function') window.syncDashboardTrackerTimer();
  if (document.getElementById('panel-home')?.classList.contains('active') && typeof window.renderDashboard === 'function') {
    window.renderDashboard();
  }
}


// ==========================================
// UNIFIED TIMER & 24H BREAK TRACKER
// ==========================================
let selectedDuration = 0;
let timerMode = 'study';
let customCountdownInterval = null;
let customCountdownSecs = 0;
let customCountdownSubject = '';
const STOPWATCH_MIN_DURATION_MS = 60000;
window.selectedTimerDuration = 0;
window.isCustomCountdownActive = false;
window.getActiveTrackerStudySession = function () {
  const now = Date.now();
  if (timerMode === 'break') return null;
  if (state.activeSession) {
    if (now - Number(state.activeSession.start) < STOPWATCH_MIN_DURATION_MS) return null;
    return { subject: state.activeSession.subject, start: Number(state.activeSession.start), end: now };
  }
  if (!window.isCustomCountdownActive || selectedDuration <= 0) return null;
  const elapsedMs = Math.max(0, (selectedDuration * 60 - customCountdownSecs) * 1000);
  return { subject: customCountdownSubject || currentSubjectValue(), start: now - elapsedMs, end: now };
};


function getTodayBreakMinutes() {
  try {
    const raw = localStorage.getItem(BREAK_STORAGE_KEY);
    if (!raw) return 0;
    const parsed = JSON.parse(raw);
    return (parsed && parsed.date === todayKey()) ? (parsed.minutes || 0) : 0;
  } catch (e) { return 0; }
}

function addTodayBreakMinutes(mins) {
  try {
    const current = getTodayBreakMinutes();
    const updated = current + mins;
    localStorage.setItem(BREAK_STORAGE_KEY, JSON.stringify({ date: todayKey(), minutes: updated }));
    update24hActivityUI();
  } catch (e) { }
}

function addBreakEntry(minutes, reason, startTime = Date.now()) {
  if (!minutes) return;
  try {
    const raw = localStorage.getItem(BREAK_ENTRIES_KEY);
    const entries = raw ? JSON.parse(raw) : [];
    entries.push({
      id: Date.now(),
      start: startTime,
      end: Date.now(),
      duration: minutes,
      reason: reason || 'Refreshment'
    });
    localStorage.setItem(BREAK_ENTRIES_KEY, JSON.stringify(entries.slice(-100)));
  } catch (e) { }
}

function getTodayBreakEntries() {
  try {
    const raw = localStorage.getItem(BREAK_ENTRIES_KEY);
    const entries = raw ? JSON.parse(raw) : [];
    return Array.isArray(entries) ? entries.filter(entry => dateKey(entry.start) === todayKey()) : [];
  } catch (e) { return []; }
}

function update24hActivityUI() {
  const studyVal = document.getElementById('actStudyVal');
  const breakVal = document.getElementById('actBreakVal');
  const ratioVal = document.getElementById('actRatioVal');
  if (!studyVal || !breakVal || !ratioVal) return;

  let studyMinutes = 0;
  const today = todayKey();
  if (Array.isArray(state.sessions)) {
    state.sessions.forEach(s => {
      if (dateKey(s.start || s.date) === today) {
        studyMinutes += (s.duration || s.durationMinutes || 0);
      }
    });
  }

  const breakMinutes = getTodayBreakMinutes();
  const totalActivityMinutes = studyMinutes + breakMinutes;
  const totalDayMinutes = 24 * 60;
  const pct = Math.min(100, Math.round((totalActivityMinutes / totalDayMinutes) * 100));

  const sH = Math.floor(studyMinutes / 60);
  const sM = studyMinutes % 60;
  studyVal.textContent = `${sH}h ${sM}m`;
  breakVal.textContent = `${breakMinutes}m`;

  const totH = (totalActivityMinutes / 60).toFixed(1);
  ratioVal.textContent = `${pct}% (${totH}h / 24h)`;
}

const durationSelector = document.getElementById('timerDurationSelector');
const timerModeSelector = document.getElementById('timerModeSelector');
const studySubjectRow = document.getElementById('studySubjectRow');
const breakReasonRow = document.getElementById('breakReasonRow');

function syncTimerModeFields() {
  const hasMode = timerMode === 'study' || timerMode === 'break';
  window.trackerTimerMode = timerMode;
  if (studySubjectRow) studySubjectRow.hidden = timerMode !== 'study';
  const quickSubjectContainer = document.getElementById('quickSubjectContainer');
  if (quickSubjectContainer) quickSubjectContainer.hidden = timerMode !== 'study';
  if (breakReasonRow) breakReasonRow.hidden = timerMode !== 'break';
  if (durationSelector) durationSelector.hidden = !hasMode;
  const studyOpts = document.getElementById('studyDurationOptions');
  const breakOpts = document.getElementById('breakDurationOptions');
  if (studyOpts) studyOpts.hidden = timerMode !== 'study';
  if (breakOpts) breakOpts.hidden = timerMode !== 'break';
  if (startBtn) {
    startBtn.textContent = timerMode === 'break' ? 'Start Break' : 'Start Studying';
    startBtn.disabled = !hasMode;
  }
  if (stopBtn) stopBtn.textContent = timerMode === 'break' ? 'Finish Break' : 'Finish Session';
  if (!hasMode) {
    const sub = document.getElementById('timerSub');
    if (sub) sub.textContent = 'Choose Study or Break to begin';
  } else {
    refreshTimerSub();
  }
  if (typeof window.syncDashboardTrackerTimer === 'function') window.syncDashboardTrackerTimer();
}

syncTimerModeFields();
if (timerModeSelector) {
  timerModeSelector.querySelectorAll('.timer-mode-chip').forEach(chip => {
    chip.classList.toggle('active', chip.dataset.mode === timerMode);
  });
  timerModeSelector.addEventListener('click', (e) => {
    const modeChip = e.target.closest('.timer-mode-chip');
    if (!modeChip || state.activeSession || window.isCustomCountdownActive) return;
    timerMode = modeChip.dataset.mode === 'break' ? 'break' : 'study';
    try { localStorage.setItem('careerdesk_subnav_tracker', timerMode); } catch (err) { }
    const previousModeChip = timerModeSelector.querySelector('.timer-mode-chip.active');
    timerModeSelector.querySelectorAll('.timer-mode-chip').forEach(chip => chip.classList.toggle('active', chip === modeChip));
    if (typeof slideTimerSwitchBubble === 'function') slideTimerSwitchBubble(previousModeChip, modeChip);
    syncTimerModeFields();
    const studyOptEl = document.getElementById('studyDurationOptions');
    const breakOptEl = document.getElementById('breakDurationOptions');
    if (studyOptEl) studyOptEl.hidden = timerMode !== 'study';
    if (breakOptEl) breakOptEl.hidden = timerMode !== 'break';
    const firstDuration = document.querySelector(`#${timerMode === 'break' ? 'breakDurationOptions' : 'studyDurationOptions'} .timer-dur-chip`);
    if (firstDuration) firstDuration.click();
    syncTimerRingUI();
    if (typeof window.syncDashboardTrackerTimer === 'function') window.syncDashboardTrackerTimer();
  });

  // Restore saved tracker sub-nav
  try {
    const savedTrackerMode = localStorage.getItem('careerdesk_subnav_tracker');
    if (savedTrackerMode && (savedTrackerMode === 'study' || savedTrackerMode === 'break') && !state.activeSession) {
      const targetModeChip = timerModeSelector.querySelector(`[data-mode="${savedTrackerMode}"]`);
      if (targetModeChip) targetModeChip.click();
    }
  } catch (err) { }
}

if (durationSelector) {
  durationSelector.addEventListener('click', (e) => {
    const chip = e.target.closest('.timer-dur-chip');
    if (!chip) return;

    if (!timerMode) return;

    if (state.activeSession || window.isCustomCountdownActive) {
      showToast('Cannot change duration while a session is active. Finish current session first.', true);
      return;
    }

    const previousDurationChip = durationSelector.querySelector('.timer-dur-chip.active');
    durationSelector.querySelectorAll('.timer-dur-chip').forEach(c => c.classList.remove('active'));
    chip.classList.add('active');
    if (typeof slideTimerSwitchBubble === 'function') slideTimerSwitchBubble(previousDurationChip, chip);

    selectedDuration = parseInt(chip.dataset.duration, 10) || 0;
    window.selectedTimerDuration = selectedDuration;

    const display = document.getElementById('timerDisplay');
    const sub = document.getElementById('timerSub');
    const subject = currentSubjectValue() || 'General';
    const reason = document.getElementById('breakReason')?.value || 'Refreshment';

    if (timerMode === 'break') {
      customCountdownSecs = selectedDuration * 60;
      if (display) display.textContent = `${String(selectedDuration).padStart(2, '0')}:00`;
      if (sub) sub.innerHTML = `<strong>${selectedDuration}-minute ${escapeHtml(reason.toLowerCase())}</strong> break — recharge before your next focus block`;
    } else if (selectedDuration === 0) {
      if (display) display.textContent = '∞';
      if (sub) sub.innerHTML = `<strong>${escapeHtml(subject)}</strong> — Stopwatch mode active`;
    } else {
      customCountdownSecs = selectedDuration * 60;
      const h = Math.floor(selectedDuration / 60);
      const m = selectedDuration % 60;
      const mStr = h > 0 ? `${h}:${String(m).padStart(2, '0')}:00` : `${String(selectedDuration).padStart(2, '0')}:00`;
      if (display) display.textContent = mStr;
      const durText = h > 0 ? (m > 0 ? `${h}h ${m}m` : `${h} hour`) : `${selectedDuration} min`;
      if (sub) sub.innerHTML = `<strong>${escapeHtml(subject)}</strong> — ${durText} focus session`;
    }
    syncTimerRingUI();
    const orb = document.getElementById('clockOrb');
    if (orb) orb.classList.toggle('is-long', selectedDuration >= 60);
    if (typeof window.syncDashboardTrackerTimer === 'function') window.syncDashboardTrackerTimer();
  });
}

const cancelModal = document.getElementById('cancelSessionModal');
const resumeBtn = document.getElementById('resumeSessionBtn');
const confirmCancelBtn = document.getElementById('confirmCancelSessionBtn');

function openCancelModal(remSeconds) {
  if (!cancelModal) return;
  const m = Math.floor(remSeconds / 60);
  const s = remSeconds % 60;
  const textEl = document.getElementById('cancelModalBodyText');
  const subject = currentSubjectValue() || 'General';

  if (textEl && timerMode === 'break') {
    textEl.innerHTML = `Your <strong>${selectedDuration}-minute break</strong> has <strong>${m}m ${s}s</strong> remaining.<br><br>Ending it now will still count the elapsed break time.`;
  } else if (textEl) {
    textEl.innerHTML = `Your <strong>${escapeHtml(subject)}</strong> focus session of <strong>${selectedDuration} minutes</strong> has <strong>${m}m ${s}s</strong> remaining!<br><br>If you exit now, this session will not count toward your daily study target.`;
  }
  cancelModal.classList.add('open');
}

function closeCancelModal() {
  if (cancelModal) cancelModal.classList.remove('open');
}

if (resumeBtn) resumeBtn.addEventListener('click', closeCancelModal);
const closeCancelModalBtn = document.getElementById('closeCancelModalBtn');
if (closeCancelModalBtn) closeCancelModalBtn.addEventListener('click', closeCancelModal);
if (confirmCancelBtn) {
  confirmCancelBtn.addEventListener('click', () => {
    closeCancelModal();
    stopCustomCountdown(false);
  });
}

function startCustomCountdown() {
  if (timerMode !== 'break') {
    const subj = currentSubjectValue();
    if (!subj) {
      if (sessionCustomInput) {
        sessionCustomInput.style.display = 'block';
        sessionCustomInput.focus();
      }
      showToast('Please enter or select a study subject', true);
      return;
    }
    customCountdownSubject = subj;
    if (typeof addSubject === 'function') addSubject(subj);
  } else {
    customCountdownSubject = '';
  }
  window.isCustomCountdownActive = true;
  syncTimerRingUI();
  const display = document.getElementById('timerDisplay');
  const startBtn = document.getElementById('startBtn');
  const stopBtn = document.getElementById('stopBtn');
  const orb = document.getElementById('clockOrb');
  const sub = document.getElementById('timerSub');

  if (startBtn) startBtn.style.display = 'none';
  if (stopBtn) stopBtn.style.display = 'inline-flex';
  if (orb) orb.classList.add('active');

  if (sub) {
    if (timerMode === 'break') {
      const reason = document.getElementById('breakReason')?.value || 'Refreshment';
      sub.innerHTML = `<span class="timer-dot"></span> Taking a <strong>${escapeHtml(reason.toLowerCase())}</strong> break (${selectedDuration}m)`;
    } else {
      const subj = currentSubjectValue() || 'General';
      const durText = selectedDuration >= 60 ? (selectedDuration % 60 === 0 ? `${selectedDuration / 60}h` : `${Math.floor(selectedDuration / 60)}h ${selectedDuration % 60}m`) : `${selectedDuration}m`;
      sub.innerHTML = `<span class="timer-dot"></span> Focusing on <strong>${escapeHtml(subj)}</strong> (${durText})`;
    }
  }

  customCountdownInterval = setInterval(() => {
    if (customCountdownSecs > 0) {
      customCountdownSecs--;
      const h = Math.floor(customCountdownSecs / 3600);
      const m = String(Math.floor((customCountdownSecs % 3600) / 60)).padStart(2, '0');
      const s = String(customCountdownSecs % 60).padStart(2, '0');
      if (display) display.textContent = h > 0 ? `${h}:${m}:${s}` : `${m}:${s}`;
      renderTodaySessions();
      renderProgress();
      syncMiniTimerWidget();
      const orb = document.getElementById('clockOrb');
      if (orb) {
        if (window.isCustomCountdownActive && selectedDuration > 0) {
          const totalSecs = Math.max(1, selectedDuration * 60);
          const pct = Math.max(0, Math.min(1, customCountdownSecs / totalSecs));
          const angle = 135 + 270 * (1 - pct);
          orb.style.setProperty('--glow-angle', `${angle}deg`);
        } else {
          orb.style.setProperty('--glow-angle', '0deg');
        }
      }
      if (typeof window.syncDashboardTrackerTimer === 'function') window.syncDashboardTrackerTimer();
    } else {
      clearInterval(customCountdownInterval);
      stopCustomCountdown(true);
    }
  }, 1000);

  syncMiniTimerWidget();
  if (typeof window.syncDashboardTrackerTimer === 'function') window.syncDashboardTrackerTimer();
  renderSubjectBars();
}

function stopCustomCountdown(isCompleted = false) {
  clearInterval(customCountdownInterval);
  window.isCustomCountdownActive = false;
  syncTimerRingUI();

  const display = document.getElementById('timerDisplay');
  const startBtn = document.getElementById('startBtn');
  const stopBtn = document.getElementById('stopBtn');
  const orb = document.getElementById('clockOrb');

  if (startBtn) startBtn.style.display = 'inline-flex';
  if (stopBtn) stopBtn.style.display = 'none';
  if (orb) orb.classList.remove('active');
  syncMiniTimerWidget();

  const subject = customCountdownSubject || currentSubjectValue() || 'General';
  const reason = document.getElementById('breakReason')?.value || 'Refreshment';

  if (timerMode === 'break') {
    const elapsedBreakSeconds = Math.max(0, (selectedDuration * 60) - customCountdownSecs);
    const elapsedBreakMinutes = elapsedBreakSeconds > 0 ? Math.max(1, Math.round(elapsedBreakSeconds / 60)) : 0;
    if (isCompleted) {
      addTodayBreakMinutes(selectedDuration);
      addBreakEntry(selectedDuration, reason, Date.now() - (selectedDuration * 60000));
      showToast(`${selectedDuration}-minute ${reason.toLowerCase()} break completed and added to break time!`);
    } else {
      if (elapsedBreakMinutes > 0) {
        addTodayBreakMinutes(elapsedBreakMinutes);
        addBreakEntry(elapsedBreakMinutes, reason, Date.now() - elapsedBreakSeconds * 1000);
        showToast(`${elapsedBreakMinutes}m of ${reason.toLowerCase()} break counted.`);
      } else {
        showToast('Break ended before any time was recorded');
      }
    }
    customCountdownSecs = selectedDuration * 60;
    if (display) display.textContent = `${String(selectedDuration).padStart(2, '0')}:00`;
  } else {
    if (isCompleted) {
      state.sessions.push({
        id: Date.now(),
        start: Date.now() - (selectedDuration * 60000),
        end: Date.now(),
        subject: subject,
        duration: selectedDuration
      });
      saveData();
      renderTrackerAll();
      showToast(`${selectedDuration}m ${subject} study session completed and added to daily goal!`);
    } else {
      showToast('Session cancelled — not counted towards daily goal', true);
    }
    customCountdownSecs = selectedDuration * 60;
    const mStr = String(selectedDuration).padStart(2, '0');
    if (display) display.textContent = `${mStr}:00`;
  }

  update24hActivityUI();
  renderTodaySessions();
  refreshTimerSub();
  customCountdownSubject = '';
  if (typeof window.syncDashboardTrackerTimer === 'function') window.syncDashboardTrackerTimer();
  renderSubjectBars();
}

document.addEventListener('click', (e) => {
  if (selectedDuration === 0) return;

  const startBtnClicked = e.target && (e.target.id === 'startBtn' || (e.target.closest && e.target.closest('#startBtn')));
  const stopBtnClicked = e.target && (e.target.id === 'stopBtn' || (e.target.closest && e.target.closest('#stopBtn')));

  if (startBtnClicked) {
    e.stopImmediatePropagation();
    startCustomCountdown();
  } else if (stopBtnClicked) {
    e.stopImmediatePropagation();
    // Both study and break sessions show a cancel confirmation modal when time remains.
    // The modal already has mode-specific text via openCancelModal().
    if (customCountdownSecs > 0) {
      openCancelModal(customCountdownSecs);
    } else {
      stopCustomCountdown(false);
    }
  }
}, true);


// ===== Mini Floating Header Timer Widget =====
function syncMiniTimerWidget() {
  const widget = document.getElementById('headerMiniTimer');
  if (!widget) return;
  const timeEl = document.getElementById('miniTimerTime');
  const subjEl = document.getElementById('miniTimerSubject');

  if (window.isCustomCountdownActive && typeof customCountdownSecs === 'number') {
    widget.style.display = 'inline-flex';
    const h = Math.floor(customCountdownSecs / 3600);
    const m = String(Math.floor((customCountdownSecs % 3600) / 60)).padStart(2, '0');
    const s = String(customCountdownSecs % 60).padStart(2, '0');
    if (timeEl) timeEl.textContent = h > 0 ? `${h}:${m}:${s}` : `${m}:${s}`;
    if (subjEl) {
      subjEl.textContent = timerMode === 'break' ? 'Break' : (typeof currentSubjectValue === 'function' ? (currentSubjectValue() || 'Focus') : 'Focus');
    }
  } else if (state && state.activeSession && state.activeSession.start) {
    widget.style.display = 'inline-flex';
    const secs = Math.floor((Date.now() - state.activeSession.start) / 1000);
    const m = Math.floor(secs / 60);
    const s = secs % 60;
    if (timeEl) {
      timeEl.textContent = m >= 60
        ? `${Math.floor(m / 60)}h ${m % 60}m`
        : `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
    }
    if (subjEl) subjEl.textContent = state.activeSession.subject || 'Focus';
  } else {
    widget.style.display = 'none';
  }
}

const headerMiniTimerEl = document.getElementById('headerMiniTimer');
if (headerMiniTimerEl) {
  headerMiniTimerEl.addEventListener('click', (e) => {
    if (e.target.closest('#miniTimerStopBtn')) {
      e.stopPropagation();
      if (window.isCustomCountdownActive && typeof stopCustomCountdown === 'function') {
        stopCustomCountdown(false);
      } else if (state && state.activeSession) {
        const stopBtn = document.getElementById('stopBtn');
        if (stopBtn) stopBtn.click();
      }
      syncMiniTimerWidget();
      return;
    }
    activateTab('tracker', true);
  });
}

/* Source: assets/js/features/countdown.js */
/* ==========================================================================
   CareerDesk — Exam Countdown Engine: Target Dates & Time Remaining
   ========================================================================== */

// ==========================================
// EXAM COUNTDOWN ENGINE
// ==========================================
let exams = [];

function loadExams() {
  const parsed = Store.get(EXAMS_KEY, []);
  exams = Array.isArray(parsed)
    ? parsed.filter(e => e && !(typeof e.id === 'number' && e.id >= 1 && e.id <= 5))
    : [];
}

function saveExams() {
  Store.set(EXAMS_KEY, exams);
  if (typeof window.scheduleFirestoreSync === 'function') {
    window.scheduleFirestoreSync();
  }
}

function parseExamTargetMs(target) {
  if (!target) return 0;
  if (typeof target === 'number') return target;
  const str = String(target).trim();
  if (str.length === 10 && /^\d{4}-\d{2}-\d{2}$/.test(str)) {
    const [y, m, d] = str.split('-').map(Number);
    return new Date(y, m - 1, d, 23, 59, 59, 999).getTime();
  }
  const parsed = new Date(str).getTime();
  return isNaN(parsed) ? 0 : parsed;
}
window.parseExamTargetMs = parseExamTargetMs;

function renderExams() {
  const grid = document.getElementById('countdownGrid');
  if (!grid) return;
  grid.innerHTML = '';

  if (!exams.length) {
    grid.innerHTML = '<div class="empty-state">No active exam countdowns. Click "+ New Exam Target" above to track an upcoming test!</div>';
    return;
  }

  const now = Date.now();
  exams.forEach(ex => {
    const targetTime = parseExamTargetMs(ex.targetDate);
    const diff = targetTime - now;

    let days = 0, hours = 0, mins = 0, secs = 0;
    let isExpired = false;

    if (diff <= 0) {
      isExpired = true;
    } else {
      days = Math.floor(diff / (1000 * 60 * 60 * 24));
      hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
      mins = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
      secs = Math.floor((diff % (1000 * 60)) / 1000);
    }

    const card = document.createElement('div');
    card.className = 'countdown-card glass';
    card.innerHTML = `
      <div class="countdown-head">
        <h3>${escapeHtml(ex.name)}</h3>
        <div class="countdown-head-actions">
          <span class="countdown-tag">${escapeHtml(ex.category || 'Exam')}</span>
          <button class="countdown-edit-btn micro-btn edit" data-id="${ex.id}" title="Edit exam target">${ICON.edit}</button>
          <button class="countdown-del-btn" data-id="${ex.id}" title="Delete">${ICON.x}</button>
        </div>
      </div>
      ${isExpired ? `
        <div style="padding: 16px 0; text-align:center; color: var(--accent3); font-weight:700;">Exam Date Passed / Target Reached!</div>
      ` : `
        <div class="countdown-timer-row">
          <div class="time-box"><span class="time-num">${days}</span><span class="time-lbl">days</span></div>
          <div class="time-box"><span class="time-num">${hours}</span><span class="time-lbl">h</span></div>
          <div class="time-box"><span class="time-num">${mins}</span><span class="time-lbl">m</span></div>
          <div class="time-box"><span class="time-num">${secs}</span><span class="time-lbl">s</span></div>
        </div>
      `}
    `;
    grid.appendChild(card);
  });
}

document.addEventListener('click', (e) => {
  // Delete exam
  const delBtn = e.target.closest('.countdown-del-btn');
  if (delBtn) {
    const id = delBtn.dataset.id;
    const ex = exams.find(x => String(x.id) === String(id));
    const exName = ex && ex.name ? `"${ex.name}"` : 'this exam target';
    if (!window.confirm(`Are you sure you want to delete exam target ${exName}?`)) return;
    exams = exams.filter(ex => String(ex.id) !== String(id));
    saveExams();
    renderExams();
    showToast('Exam target deleted');
  }

  // Edit exam
  const editBtn = e.target.closest('.countdown-edit-btn');
  if (editBtn) {
    const id = editBtn.dataset.id;
    const ex = exams.find(x => String(x.id) === String(id));
    if (!ex) return;
    const modal = document.getElementById('editExamModal');
    const nameInput = document.getElementById('editExamNameInput');
    const catInput = document.getElementById('editExamCatInput');
    const dateInput = document.getElementById('editExamDateInput');
    const idInput = document.getElementById('editExamId');
    if (!modal || !nameInput || !catInput || !dateInput || !idInput) return;
    idInput.value = ex.id;
    nameInput.value = ex.name || '';
    catInput.value = ex.category || '';
    // Format date for datetime-local input
    try {
      const d = new Date(ex.targetDate);
      const pad = n => String(n).padStart(2, '0');
      dateInput.value = `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
    } catch(e2) { dateInput.value = ''; }
    modal.style.display = 'flex';
    void modal.offsetWidth;
    modal.classList.add('open');
    if (window.lucide) lucide.createIcons();
  }
});

// Edit exam modal save/cancel
function initEditExamListeners() {
  const saveEditExamBtn = document.getElementById('saveEditExamBtn');
  const cancelEditExamBtn = document.getElementById('cancelEditExamBtn');
  const closeEditExamModal = document.getElementById('closeEditExamModal');

  function closeEditExam() {
    const modal = document.getElementById('editExamModal');
    if (modal) { modal.classList.remove('open'); setTimeout(() => { if (!modal.classList.contains('open')) modal.style.display = 'none'; }, 180); }
  }

  if (saveEditExamBtn) {
    saveEditExamBtn.addEventListener('click', () => {
      const id = document.getElementById('editExamId').value;
      const name = document.getElementById('editExamNameInput').value.trim();
      const cat = document.getElementById('editExamCatInput').value.trim();
      const dateVal = document.getElementById('editExamDateInput').value;
      if (!name || !dateVal) { showToast('Please enter both exam name and date.', true); return; }
      const ex = exams.find(x => String(x.id) === String(id));
      if (!ex) return;
      ex.name = name;
      ex.category = cat || 'Exam';
      ex.targetDate = new Date(dateVal).toISOString();
      saveExams();
      renderExams();
      closeEditExam();
      showToast('Exam target updated!');
    });
  }

  if (cancelEditExamBtn) cancelEditExamBtn.addEventListener('click', closeEditExam);
  if (closeEditExamModal) closeEditExamModal.addEventListener('click', closeEditExam);

  // Click outside to close
  document.addEventListener('click', e => {
    const modal = document.getElementById('editExamModal');
    if (modal && e.target === modal) closeEditExam();
  });
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initEditExamListeners);
} else {
  initEditExamListeners();
}


const toggleExamBtn = document.getElementById('toggleExamFormBtn');
const examWrap = document.getElementById('examFormWrap');
if (toggleExamBtn && examWrap) {
  toggleExamBtn.addEventListener('click', () => {
    const isOpen = examWrap.style.display !== 'none';
    examWrap.style.display = isOpen ? 'none' : 'block';
    toggleExamBtn.innerHTML = isOpen ? `${ICON.plus} New Exam Target` : `${ICON.x} Close Form`;
    toggleExamBtn.classList.toggle('active-open', !isOpen);
  });
}

const addExamBtn = document.getElementById('addExamTargetBtn');
if (addExamBtn) {
  addExamBtn.addEventListener('click', () => {
    const nameEl = document.getElementById('examNameInput');
    const catEl = document.getElementById('examCatInput');
    const dateEl = document.getElementById('examDateInput');
    const name = nameEl.value.trim();
    const cat = catEl.value.trim();
    const dateVal = dateEl.value;

    if (!name || !dateVal) {
      showToast('Please enter both exam name and target date.', true);
      return;
    }

    exams.push({
      id: Date.now(),
      name: name,
      category: cat || 'Exam',
      targetDate: new Date(dateVal).toISOString()
    });

    nameEl.value = ''; dateEl.value = '';
    saveExams();
    renderExams();

    if (examWrap && toggleExamBtn) {
      examWrap.style.display = 'none';
      toggleExamBtn.innerHTML = `${ICON.plus} <span>New Exam Target</span>`;
      toggleExamBtn.classList.remove('active-open');
    }
    showToast('New exam countdown target added!');
  });
}

/* Source: assets/js/features/syllabus.js */
/* ==========================================================================
   CareerDesk — Syllabus Module: Categories, Topics & Progress Tracking
   ========================================================================== */

// ===== Syllabus =====
const categoryList = document.getElementById('categoryList');
const openCategoryIds = new Set();
const topicDeleteModeCategories = new Set();
const topicEditModeCategories = new Set();
const editingSubjectCategories = new Set();
let editingTopicKey = null;

function syllabusTotals() {
  let total = 0, done = 0;
  state.syllabus.forEach(cat => { cat.topics.forEach(t => { total++; if (t.done) done++; }); });
  return { total, done };
}

function renderSyllabusOverall() {
  const { total, done } = syllabusTotals();
  const pct = total ? Math.round((done / total) * 100) : 0;
  document.getElementById('syllabusOverallLabel').textContent = `${done} / ${total} topics completed`;
  document.getElementById('syllabusOverallPct').textContent = pct + '%';
  document.getElementById('syllabusOverallFill').style.width = pct + '%';
}

function parseSyllabusTopicNames(value) {
  return [...new Set(value.split('|').map(topic => topic.trim()).filter(Boolean))];
}

function addSyllabusTopics(category, topicNames) {
  const existingNames = new Set(category.topics.map(topic => topic.name.trim().toLowerCase()));
  const allIds = new Set(state.syllabus.flatMap(item => item.topics.map(topic => String(topic.id))));
  let nextId = Date.now();
  let addedCount = 0;

  topicNames.forEach(name => {
    const normalizedName = name.toLowerCase();
    if (existingNames.has(normalizedName)) return;
    while (allIds.has(String(nextId))) nextId++;
    category.topics.push({ id: nextId, name, done: false });
    allIds.add(String(nextId));
    existingNames.add(normalizedName);
    nextId++;
    addedCount++;
  });

  return addedCount;
}

function renderCategories() {
  if (!state.syllabus.length) {
    categoryList.innerHTML = '<div class="empty-state">No categories yet. Add one above to begin your syllabus.</div>';
    renderSyllabusOverall();
    return;
  }
  categoryList.innerHTML = state.syllabus.map(cat => {
    const total = cat.topics.length;
    const done = cat.topics.filter(t => t.done).length;
    const pct = total ? Math.round((done / total) * 100) : 0;
    const isTopicDelActive = topicDeleteModeCategories.has(String(cat.id));
    const isTopicEditActive = topicEditModeCategories.has(String(cat.id));
    const isSubjectEditing = editingSubjectCategories.has(String(cat.id));
    const meta = typeof getSubjectMeta === 'function' ? getSubjectMeta(cat.name) : { color: '#6366f1', icon: 'book-open' };
    const topicsHtml = cat.topics.length ? (
      '<div class="topic-tile-grid">' + cat.topics.map(t => `
        <div class="topic-tile ${t.done ? 'done' : ''} ${isTopicEditActive ? 'topic-edit-target' : ''} ${editingTopicKey === `${cat.id}:${t.id}` ? 'topic-editing' : ''}" data-cat="${cat.id}" data-topic="${t.id}">
          ${editingTopicKey === `${cat.id}:${t.id}`
            ? `<input class="topic-edit-input" data-topic-edit-input="${t.id}" data-topic-edit-cat="${cat.id}" value="${escapeAttr(t.name)}" aria-label="Edit topic name">
               <span class="topic-edit-controls">
                 <button class="topic-edit-save" data-save-topic="${t.id}" data-save-topic-cat="${cat.id}" type="button" aria-label="Save topic">${ICON.check}</button>
                 <button class="topic-edit-cancel" data-cancel-topic="${t.id}" type="button" aria-label="Cancel topic edit">${ICON.x}</button>
               </span>`
            : `<span class="tile-label" data-topic-label="${t.id}" data-topic-cat="${cat.id}" title="${isTopicEditActive ? 'Select to edit' : 'Double-click to edit'}">${escapeHtml(t.name)}</span>
               <button class="tile-del" data-cat="${cat.id}" data-topic="${t.id}" title="Delete Topic" aria-label="Delete Topic">${ICON.x}</button>`}
        </div>
      `).join('') + '</div>'
    ) : '<div class="empty-state" style="padding:20px;">No topics in this category yet.</div>';

    const topicModeBanner = isTopicDelActive || isTopicEditActive ? `
      <div class="topic-del-active-banner ${isTopicEditActive ? 'topic-edit-active-banner' : ''}">
        <div class="del-banner-left">
          <span class="del-pulse-dot"></span>
          <span>${isTopicEditActive
            ? 'Topic edit mode active — select a topic to edit its name'
            : 'Topic delete mode active — click <strong>✕</strong> on any topic to remove'}</span>
        </div>
        <button class="pill subtle mini-exit-del-btn" data-exit-topic-mode="${cat.id}" type="button">Done</button>
      </div>
    ` : '';

    return `
      <div class="category-card glass open ${isTopicDelActive ? 'topic-delete-mode' : ''}" data-cat="${cat.id}">
        <div class="category-head">
          <div class="category-head-left" style="display:flex; align-items:center; gap:10px;">
            <span class="category-icon-badge" style="color:${meta.color}; background:${meta.color}18; border:1px solid ${meta.color}30; width:30px; height:30px; border-radius:8px; display:inline-flex; align-items:center; justify-content:center; flex-shrink:0;">
              <i data-lucide="${meta.icon || 'book-open'}" style="width:16px; height:16px;"></i>
            </span>
            <h3 class="category-title" data-category-title="${cat.id}" title="Double-click to edit">
              ${escapeHtml(typeof getSubjectDisplayName === 'function' ? getSubjectDisplayName(cat.name) : cat.name)}
            </h3>
          </div>
          <div class="category-head-right">
            <span class="category-progress-text">${done}/${total} • ${pct}%</span>
            <div class="category-mini-track"><div class="category-mini-fill" style="width:${pct}%"></div></div>
            <div class="btn-group category-action-group" aria-label="Subject actions">
              <button class="cat-group-btn cat-add-btn" data-toggle-add-topic="${cat.id}" type="button" title="Add Topic" aria-label="Add Topic">
                ${ICON.plus} <span>Add Topic</span>
              </button>
              <div class="cat-edit-dropdown-wrap">
                <button class="cat-group-btn cat-edit-btn" data-cat-edit-trigger="${cat.id}" type="button" title="Edit Subject or Topics" aria-label="Edit Subject or Topics" aria-expanded="false">
                  ${ICON.edit} <span>Edit</span>
                </button>
                <div class="cat-del-menu cat-edit-menu" data-cat-edit-menu="${cat.id}" style="display:none;">
                  <button class="cat-del-menu-item" data-edit-subject="${cat.id}" type="button">${ICON.edit}<span>Edit Subject</span></button>
                  <button class="cat-del-menu-item" data-edit-topics="${cat.id}" type="button">${ICON.edit}<span>Edit Topics</span></button>
                </div>
              </div>
              <div class="cat-del-dropdown-wrap">
                <button class="cat-group-btn cat-del-trigger ${isTopicDelActive ? 'active' : ''}" data-catdel-trigger="${cat.id}" type="button" title="Delete Subject or Topics" aria-label="Delete Subject or Topics" aria-expanded="false">
                  ${ICON.trash} <span>Delete</span>
                </button>
                <div class="cat-del-menu" data-catdel-dropdown="${cat.id}" style="display:none;">
                  <button class="cat-del-menu-item item-subject" data-catdel-subject="${cat.id}" type="button">
                    ${ICON.trash}
                    <span>Delete Subject</span>
                  </button>
                  <button class="cat-del-menu-item item-topics ${isTopicDelActive ? 'active-mode' : ''}" data-catdel-topics="${cat.id}" type="button">
                    ${ICON.x}
                    <span>${isTopicDelActive ? 'Done Deleting' : 'Delete Topic'}</span>
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
        <div class="category-body">
          ${topicModeBanner}
          ${isSubjectEditing ? `
            <div class="edit-subject-row" data-edit-subject-form="${cat.id}">
              <input type="text" data-subject-edit-input="${cat.id}" value="${escapeAttr(cat.name)}" aria-label="Edit subject name">
              <button class="pill solid" data-save-subject="${cat.id}" type="button">${ICON.check}<span>Save</span></button>
              <button class="pill subtle" data-cancel-subject="${cat.id}" type="button">Cancel</button>
            </div>
          ` : ''}
          ${topicsHtml}
          <div class="add-topic-row" data-topic-form="${cat.id}" hidden>
            <input type="text" placeholder="Topic name (use | between topics)" aria-label="Topic names, separated by vertical bars" data-topicinput="${cat.id}">
            <button class="pill" data-addtopic="${cat.id}">Add topics</button>
          </div>
        </div>
      </div>
    `;
  }).join('');
  renderSyllabusOverall();

  if (window.lucide && typeof window.lucide.createIcons === 'function') {
    window.lucide.createIcons();
  }
}

function saveSyllabusAndRefresh() {
  saveData();
  renderCategories();
  syncAllSubjectSelects();
}

function positionSyllabusMenu(menu, trigger) {
  const menuHeight = menu.getBoundingClientRect().height;
  const triggerRect = trigger.getBoundingClientRect();
  const fitsBelow = window.innerHeight - triggerRect.bottom >= menuHeight + 8;
  const fitsAbove = triggerRect.top >= menuHeight + 8;
  menu.classList.toggle('opens-up', !fitsBelow && fitsAbove);
}

const addCategoryBtn = document.getElementById('addCategoryBtn');
if (addCategoryBtn) {
  addCategoryBtn.addEventListener('click', () => {
    const input = document.getElementById('newCategoryInput');
    if (!input) return;
    const name = input.value.trim();
    if (!name) return;
    if (typeof addSubject === 'function') addSubject(name);
    const topicInput = document.getElementById('newTopicInput');
    const topicNames = topicInput ? parseSyllabusTopicNames(topicInput.value) : [];
    const normalizedName = name.toLowerCase();
    const existingCat = state.syllabus.find(c => String(c.name).trim().toLowerCase() === normalizedName);
    if (existingCat) {
      if (topicNames.length) {
        const addedCount = addSyllabusTopics(existingCat, topicNames);
        showToast(addedCount
          ? `${addedCount} topic${addedCount === 1 ? '' : 's'} added to existing subject.`
          : 'These topics already exist in this subject.', !addedCount);
      } else {
        showToast('This category already exists.', true);
      }
      input.value = '';
      if (topicInput) topicInput.value = '';
      saveSyllabusAndRefresh();
      return;
    }
    const id = Date.now();
    const category = { id, name, topics: [] };
    addSyllabusTopics(category, topicNames);
    state.syllabus.push(category);
    input.value = '';
    if (topicInput) topicInput.value = '';
    saveSyllabusAndRefresh();
  });
}

if (categoryList) {
  categoryList.addEventListener('click', (e) => {
  if (e.detail > 1) return;

  const editTrigger = e.target.closest('[data-cat-edit-trigger]');
  if (editTrigger) {
    const catId = editTrigger.dataset.catEditTrigger;
    const menu = categoryList.querySelector(`[data-cat-edit-menu="${catId}"]`);
    const shouldOpen = menu && menu.style.display !== 'flex';
    document.querySelectorAll('.cat-edit-menu, .cat-del-menu').forEach(item => { item.style.display = 'none'; });
    document.querySelectorAll('[data-cat-edit-trigger], .cat-del-trigger').forEach(button => {
      button.classList.remove('menu-open');
      button.setAttribute('aria-expanded', 'false');
    });
    if (shouldOpen) {
      menu.style.display = 'flex';
      positionSyllabusMenu(menu, editTrigger);
      editTrigger.classList.add('menu-open');
      editTrigger.setAttribute('aria-expanded', 'true');
    }
    return;
  }

  const editSubjectButton = e.target.closest('[data-edit-subject]');
  if (editSubjectButton) {
    const catId = String(editSubjectButton.dataset.editSubject);
    document.querySelectorAll('.cat-edit-menu, .cat-del-menu').forEach(item => { item.style.display = 'none'; });
    topicEditModeCategories.delete(catId);
    topicDeleteModeCategories.delete(catId);
    editingTopicKey = null;
    editingSubjectCategories.add(catId);
    renderCategories();
    categoryList.querySelector(`[data-subject-edit-input="${catId}"]`)?.focus();
    return;
  }

  const editTopicsButton = e.target.closest('[data-edit-topics]');
  if (editTopicsButton) {
    const catId = String(editTopicsButton.dataset.editTopics);
    document.querySelectorAll('.cat-edit-menu, .cat-del-menu').forEach(item => { item.style.display = 'none'; });
    editingSubjectCategories.delete(catId);
    topicEditModeCategories.add(catId);
    topicDeleteModeCategories.delete(catId);
    renderCategories();
    return;
  }

  const saveSubjectButton = e.target.closest('[data-save-subject]');
  if (saveSubjectButton) {
    const catId = String(saveSubjectButton.dataset.saveSubject);
    const cat = state.syllabus.find(item => String(item.id) === catId);
    const input = categoryList.querySelector(`[data-subject-edit-input="${catId}"]`);
    const newName = input ? input.value.trim() : '';
    if (!cat || !newName) {
      showToast('Subject name cannot be empty.', true);
      input?.focus();
      return;
    }
    if (state.syllabus.some(item => item !== cat && item.name.trim().toLowerCase() === newName.toLowerCase())) {
      showToast('A subject with this name already exists.', true);
      input.focus();
      return;
    }
    editingSubjectCategories.delete(catId);
    if (cat.name === newName) {
      renderCategories();
    } else if (typeof renameSubject === 'function') renameSubject(cat.name, newName);
    else {
      cat.name = newName;
      saveSyllabusAndRefresh();
    }
    return;
  }

  const cancelSubjectButton = e.target.closest('[data-cancel-subject]');
  if (cancelSubjectButton) {
    editingSubjectCategories.delete(String(cancelSubjectButton.dataset.cancelSubject));
    renderCategories();
    return;
  }

  const saveTopicButton = e.target.closest('[data-save-topic]');
  if (saveTopicButton) {
    const catId = String(saveTopicButton.dataset.saveTopicCat);
    const topicId = String(saveTopicButton.dataset.saveTopic);
    const cat = state.syllabus.find(item => String(item.id) === catId);
    const topic = cat && cat.topics.find(item => String(item.id) === topicId);
    const input = categoryList.querySelector(`[data-topic-edit-input="${topicId}"][data-topic-edit-cat="${catId}"]`);
    const newName = input ? input.value.trim() : '';
    if (!topic || !newName) {
      showToast('Topic name cannot be empty.', true);
      input?.focus();
      return;
    }
    if (cat.topics.some(item => item !== topic && item.name.trim().toLowerCase() === newName.toLowerCase())) {
      showToast('A topic with this name already exists.', true);
      input.focus();
      return;
    }
    topic.name = newName;
    editingTopicKey = null;
    saveSyllabusAndRefresh();
    return;
  }

  const cancelTopicButton = e.target.closest('[data-cancel-topic]');
  if (cancelTopicButton) {
    editingTopicKey = null;
    renderCategories();
    return;
  }

  const exitTopicModeButton = e.target.closest('[data-exit-topic-mode]');
  if (exitTopicModeButton) {
    const catId = String(exitTopicModeButton.dataset.exitTopicMode);
    topicEditModeCategories.delete(catId);
    topicDeleteModeCategories.delete(catId);
    editingTopicKey = null;
    renderCategories();
    return;
  }

  // Delete trigger clicked: toggle dropdown menu.
  const delTrigger = e.target.closest('[data-catdel-trigger]');
  if (delTrigger) {
    const catId = delTrigger.dataset.catdelTrigger;
    const menu = categoryList.querySelector(`[data-catdel-dropdown="${catId}"]`);
    const isCurrentlyOpen = menu && menu.style.display === 'flex';
    document.querySelectorAll('.cat-edit-menu, .cat-del-menu').forEach(item => { item.style.display = 'none'; });
    document.querySelectorAll('[data-cat-edit-trigger], .cat-del-trigger').forEach(button => {
      button.classList.remove('menu-open');
      button.setAttribute('aria-expanded', 'false');
    });
    if (!isCurrentlyOpen && menu) {
      menu.style.display = 'flex';
      positionSyllabusMenu(menu, delTrigger);
      delTrigger.classList.add('menu-open');
      delTrigger.setAttribute('aria-expanded', 'true');
    }
    return;
  }

  // Delete Subject option
  const subBtn = e.target.closest('[data-catdel-subject]');
  if (subBtn) {
    const catId = subBtn.dataset.catdelSubject;
    const cat = state.syllabus.find(c => String(c.id) === catId);
    const catName = cat && cat.name ? `"${cat.name}"` : 'this subject/category';
    document.querySelectorAll('.cat-edit-menu, .cat-del-menu').forEach(item => { item.style.display = 'none'; });
    document.querySelectorAll('[data-cat-edit-trigger], .cat-del-trigger').forEach(button => {
      button.classList.remove('menu-open');
      button.setAttribute('aria-expanded', 'false');
    });
    if (!window.confirm(`Are you sure you want to delete subject ${catName} and all its topics?`)) return;
    openCategoryIds.delete(catId);
    topicDeleteModeCategories.delete(catId);
    topicEditModeCategories.delete(catId);
    editingSubjectCategories.delete(catId);
    state.syllabus = state.syllabus.filter(c => String(c.id) !== catId);
    saveSyllabusAndRefresh();
    showToast('Subject deleted');
    return;
  }

  // Delete Topic / Toggle topic delete mode option
  const topBtn = e.target.closest('[data-catdel-topics]');
  if (topBtn) {
    const catId = String(topBtn.dataset.catdelTopics);
    document.querySelectorAll('.cat-edit-menu, .cat-del-menu').forEach(item => { item.style.display = 'none'; });
    document.querySelectorAll('.cat-del-trigger').forEach(button => {
      button.classList.remove('menu-open');
      button.setAttribute('aria-expanded', 'false');
    });
    editingSubjectCategories.delete(catId);
    editingTopicKey = null;
    if (topicDeleteModeCategories.has(catId)) {
      topicDeleteModeCategories.delete(catId);
      showToast('Topic delete mode disabled');
    } else {
      topicEditModeCategories.delete(catId);
      topicDeleteModeCategories.add(catId);
      showToast('Topic delete mode enabled. Click ✕ on topics to delete.');
    }
    renderCategories();
    return;
  }

  const tile = e.target.closest('.topic-tile');
  if (tile && !e.target.closest('.tile-del, .topic-edit-input, .topic-edit-controls')) {
    const cat = state.syllabus.find(c => String(c.id) === tile.dataset.cat);
    if (cat) {
      const topic = cat.topics.find(t => String(t.id) === tile.dataset.topic);
      const catId = String(cat.id);
      if (topic && topicEditModeCategories.has(catId)) {
        editingTopicKey = `${catId}:${topic.id}`;
        renderCategories();
        categoryList.querySelector(`[data-topic-edit-input="${topic.id}"][data-topic-edit-cat="${catId}"]`)?.focus();
      } else if (topic && !e.target.closest('.topic-edit-input, .topic-edit-controls')) {
        topic.done = !topic.done;
        saveSyllabusAndRefresh();
      }
    }
    return;
  }

  if (e.target.closest('.tile-del')) {
    const btn = e.target.closest('.tile-del');
    const cat = state.syllabus.find(c => String(c.id) === btn.dataset.cat);
    if (cat) {
      const topic = cat.topics.find(t => String(t.id) === btn.dataset.topic);
      const topicName = topic && topic.name ? `"${topic.name}"` : 'this topic';
      if (!window.confirm(`Are you sure you want to delete topic ${topicName}?`)) return;
      cat.topics = cat.topics.filter(t => String(t.id) !== btn.dataset.topic);
      if (!cat.topics.length) {
        topicDeleteModeCategories.delete(String(cat.id));
      }
      saveSyllabusAndRefresh();
      showToast('Topic deleted');
    }
    return;
  }

  if (e.target.closest('[data-addtopic]')) {
    const btn = e.target.closest('[data-addtopic]');
    const catId = btn.dataset.addtopic;
    const input = categoryList.querySelector(`[data-topicinput="${catId}"]`);
    const topicNames = input ? parseSyllabusTopicNames(input.value) : [];
    if (!topicNames.length) return;
    const cat = state.syllabus.find(c => String(c.id) === catId);
    if (cat) {
      const addedCount = addSyllabusTopics(cat, topicNames);
      input.value = '';
      saveSyllabusAndRefresh();
      showToast(addedCount
        ? `${addedCount} topic${addedCount === 1 ? '' : 's'} added.`
        : 'These topics already exist in this subject.', !addedCount);
    }
    return;
  }

  if (e.target.closest('[data-toggle-add-topic]')) {
    const btn = e.target.closest('[data-toggle-add-topic]');
    const catId = btn.dataset.toggleAddTopic;
    const panel = categoryList.querySelector(`[data-topic-form="${catId}"]`);
    if (panel) {
      panel.hidden = !panel.hidden;
      const input = panel.querySelector('input');
      if (!panel.hidden && input) input.focus();
    }
    return;
  }

});
}

// Global click to dismiss category delete dropdowns when clicking outside
document.addEventListener('click', (e) => {
  if (!e.target.closest('.cat-del-dropdown-wrap, .cat-edit-dropdown-wrap')) {
    document.querySelectorAll('.cat-del-menu, .cat-edit-menu').forEach(menu => { menu.style.display = 'none'; });
    document.querySelectorAll('.cat-del-trigger, [data-cat-edit-trigger]').forEach(button => {
      button.classList.remove('menu-open');
      button.setAttribute('aria-expanded', 'false');
    });
  }
});

if (categoryList) {
  categoryList.addEventListener('keydown', e => {
    if (e.key === 'Escape' && e.target.matches('[data-subject-edit-input]')) {
      editingSubjectCategories.delete(String(e.target.dataset.subjectEditInput));
      renderCategories();
      return;
    }
    if (e.key === 'Escape' && e.target.matches('[data-topic-edit-input]')) {
      editingTopicKey = null;
      renderCategories();
      return;
    }
    if (e.key === 'Enter' && e.target.matches('[data-subject-edit-input]')) {
      e.preventDefault();
      categoryList.querySelector(`[data-save-subject="${e.target.dataset.subjectEditInput}"]`)?.click();
    }
    if (e.key === 'Enter' && e.target.matches('[data-topic-edit-input]')) {
      e.preventDefault();
      categoryList.querySelector(`[data-save-topic="${e.target.dataset.topicEditInput}"][data-save-topic-cat="${e.target.dataset.topicEditCat}"]`)?.click();
    }
  });
}

if (categoryList) {
  categoryList.addEventListener('dblclick', (e) => {
    const label = e.target.closest('.tile-label');
    if (label) {
      const cat = state.syllabus.find(c => String(c.id) === label.dataset.topicCat);
      if (!cat) return;
      const topic = cat.topics.find(t => String(t.id) === label.dataset.topicLabel);
      if (!topic) return;
      const catId = String(cat.id);
      topicEditModeCategories.add(catId);
      editingTopicKey = `${catId}:${topic.id}`;
      renderCategories();
      categoryList.querySelector(`[data-topic-edit-input="${topic.id}"][data-topic-edit-cat="${catId}"]`)?.focus();
      return;
    }
    const title = e.target.closest('.category-title');
    if (!title) return;
    const catId = String(title.dataset.categoryTitle);
    editingSubjectCategories.add(catId);
    renderCategories();
    categoryList.querySelector(`[data-subject-edit-input="${catId}"]`)?.focus();
  });
}

/* Source: assets/js/features/mcq.js */
/* ==========================================================================
   CareerDesk — BCS 1,000 MCQ Engine & Mistake Bank System
   Features:
   - 100% True Random Question Generation from 1,000 authentic BCS items
   - Randomized Option Choices (A, B, C, D) per question
   - Practice Mode: Instant feedback (+1.0 / -0.5), explanations, auto-mistake logging
   - 20-Question Timed Exam Mode: 15-min countdown, question navigator, comprehensive review
   - Mistake Bank: Targeted remediation, drill practice, and full management
   ========================================================================== */

const EXAM_QUESTION_COUNT = 20;
const EXAM_DURATION_SECONDS = 900; // 15 Minutes
// Note: MISTAKES_KEY is declared in core.js ('jobprep_mistakes_list')
const MCQ_STATS_KEY = 'careerdesk_mcq_session_stats';

// BCS 10 Subjects with metadata
const BCS_SUBJECT_META = {
  "বাংলা সাহিত্য": { icon: "book-open", color: "#6366f1", label: "বাংলা সাহিত্য" },
  "বাংলা ব্যাকরণ": { icon: "feather", color: "#8b5cf6", label: "বাংলা ব্যাকরণ" },
  "English": { icon: "languages", color: "#3b82f6", label: "English" },
  "বাংলাদেশ বিষয়াবলী": { icon: "map-pin", color: "#10b981", label: "বাংলাদেশ বিষয়াবলী" },
  "আন্তর্জাতিক বিষয়াবলী": { icon: "globe", color: "#06b6d4", label: "আন্তর্জাতিক বিষয়াবলী" },
  "সাধারণ বিজ্ঞান": { icon: "flask-conical", color: "#ec4899", label: "সাধারণ বিজ্ঞান" },
  "কম্পিউটার ও আইসিটি": { icon: "monitor", color: "#0ea5e9", label: "কম্পিউটার ও আইসিটি" },
  "গণিত": { icon: "calculator", color: "#f59e0b", label: "গণিত" },
  "ভূগোল ও পরিবেশ": { icon: "trees", color: "#10b981", label: "ভূগোল ও পরিবেশ" },
  "নৈতিকতা ও সুশাসন": { icon: "scale", color: "#64748b", label: "নৈতিকতা ও সুশাসন" }
};

const PREFIX_LETTERS = ["A", "B", "C", "D"];

// State Variables
let currentMCQMode = 'practice'; // 'practice' | 'exam'
let currentSelectedSubject = 'all';

// Practice Mode State
let practicePool = [];         // Shuffled queue of candidate questions
let practiceIndex = 0;         // Pointer in practicePool
let practiceAnswers = {};      // { [practiceIndex]: { selectedIndex, isCorrect } }
let practiceStats = { correct: 0, wrong: 0 };

// Exam Mode State
let examPool = [];             // 20 randomly drawn questions
let examIndex = 0;             // Pointer 0..19
let examAnswers = {};          // { [examIndex]: { selectedIndex } }
let examFlagged = {};          // { [examIndex]: boolean }
let examTimerInterval = null;
let examTimeRemaining = EXAM_DURATION_SECONDS;

// Mistakes Bank State
let mistakes = [];
let questionBankPromise = null;
let questionBankInitialized = false;

// ==========================================================================
// 1. Storage & Helper Utilities
// ==========================================================================

function loadMistakes() {
  try {
    const raw = localStorage.getItem(MISTAKES_KEY);
    mistakes = raw ? JSON.parse(raw) : [];
    if (!Array.isArray(mistakes)) mistakes = [];
  } catch (e) {
    mistakes = [];
  }
  window.mistakes = mistakes;
  updateMistakeBadge();
}

function saveMistakes() {
  try {
    localStorage.setItem(MISTAKES_KEY, JSON.stringify(mistakes));
    if (typeof window.scheduleFirestoreSync === 'function') {
      window.scheduleFirestoreSync();
    }
  } catch (e) { }
  window.mistakes = mistakes;
  updateMistakeBadge();
}

function updateMistakeBadge() {
  const badge = document.getElementById("headerMistakeCountBadge");
  if (badge) {
    badge.textContent = String(mistakes.length);
    badge.style.display = mistakes.length > 0 ? "inline-block" : "none";
  }
}

// Fisher-Yates True Shuffle
function shuffleArray(arr) {
  const result = [...arr];
  for (let i = result.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [result[i], result[j]] = [result[j], result[i]];
  }
  return result;
}

// Prepare question with randomized options (A, B, C, D) while maintaining correct answer
function prepareQuestionWithOptionsShuffled(rawQ) {
  if (!rawQ || !Array.isArray(rawQ.options)) return rawQ;

  const optionsWithMeta = rawQ.options.map((optText, idx) => ({
    text: optText,
    isCorrect: idx === rawQ.correct
  }));

  const shuffledOptions = shuffleArray(optionsWithMeta);
  const correctIdx = shuffledOptions.findIndex(o => o.isCorrect);

  return {
    ...rawQ,
    originalId: rawQ.id,
    options: shuffledOptions.map(o => o.text),
    correct: correctIdx >= 0 ? correctIdx : 0
  };
}

const CUSTOM_MCQ_KEY = 'custom_bcs_questions_v3';

function getStoredQuestions() {
  try {
    const raw = localStorage.getItem(CUSTOM_MCQ_KEY) || localStorage.getItem('jobprep_custom_quiz_questions');
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    return [];
  }
}
window.getStoredQuestions = getStoredQuestions;

function saveStoredQuestions(questions) {
  try {
    localStorage.setItem(CUSTOM_MCQ_KEY, JSON.stringify(questions));
    if (typeof window.scheduleFirestoreSync === 'function') {
      window.scheduleFirestoreSync();
    }
  } catch (e) { }
}

function ensureBCSQuestionBankLoaded() {
  if (Array.isArray(window.bcs1000QuestionBank)) {
    return Promise.resolve(window.bcs1000QuestionBank);
  }
  if (questionBankPromise) return questionBankPromise;

  questionBankPromise = fetch('assets/data/bcs-mcq-question-bank-1000.json')
    .then(response => {
      if (!response.ok) {
        throw new Error(`Question bank request failed (${response.status})`);
      }
      return response.json();
    })
    .then(questions => {
      if (!Array.isArray(questions)) {
        throw new TypeError('Question bank data must be an array.');
      }
      window.bcs1000QuestionBank = questions;
      window.defaultQuestions = questions;
      return questions;
    })
    .catch(error => {
      questionBankPromise = null;
      throw error;
    });

  return questionBankPromise;
}

function renderQuizLoadingSkeleton() {
  const quizCard = document.getElementById("quiz-card");
  const qText = document.getElementById("q-text");
  const optionsContainer = document.getElementById("options-container");
  const filterBar = document.getElementById("filter-bar");

  if (quizCard) quizCard.setAttribute("aria-busy", "true");

  if (qText) {
    qText.innerHTML = `<span class="sr-only" role="status" aria-live="polite">Loading questions…</span>
      <span class="skeleton-stack" aria-hidden="true">
        <span class="skeleton skeleton-line" style="width: 94%"></span>
        <span class="skeleton skeleton-line" style="width: 66%"></span>
      </span>`;
  }

  if (optionsContainer) {
    optionsContainer.innerHTML = ["96%", "88%", "92%", "74%"]
      .map(width => `<span class="skeleton skeleton-option" style="width: ${width}" aria-hidden="true"></span>`)
      .join("");
  }

  if (filterBar) {
    filterBar.setAttribute("aria-busy", "true");
    filterBar.innerHTML = ["78px", "92px", "70px", "86px", "74px"]
      .map(width => `<span class="skeleton skeleton-pill" style="width: ${width}" aria-hidden="true"></span>`)
      .join("");
  }
}

function clearQuizLoadingSkeleton() {
  const quizCard = document.getElementById("quiz-card");
  const filterBar = document.getElementById("filter-bar");
  if (quizCard) quizCard.setAttribute("aria-busy", "false");
  if (filterBar) filterBar.setAttribute("aria-busy", "false");
}

function loadQuestionBankForQuiz() {
  if (!questionBankInitialized) renderQuizLoadingSkeleton();
  return ensureBCSQuestionBankLoaded().then(() => {
    if (!questionBankInitialized) {
      buildPracticePool(currentSelectedSubject);
      renderMCQFilterBar();
      renderMCQQuestion();
      updateMCQStatsBar();
      questionBankInitialized = true;
    }
    clearQuizLoadingSkeleton();
  }).catch(error => {
    clearQuizLoadingSkeleton();
    const qText = document.getElementById("q-text");
    const optionsContainer = document.getElementById("options-container");
    if (qText) qText.textContent = "Questions could not be loaded. Check your connection and try again.";
    if (optionsContainer) optionsContainer.innerHTML = "";
    throw error;
  });
}

// Get Master Questions Bank (Curated BCS Bank + Custom Stored Questions)
function getMasterQuestions() {
  let base = [];
  if (Array.isArray(window.bcs1000QuestionBank) && window.bcs1000QuestionBank.length > 0) {
    base = window.bcs1000QuestionBank;
  } else if (Array.isArray(window.defaultQuestions)) {
    base = window.defaultQuestions;
  }
  const custom = getStoredQuestions();
  if (custom.length > 0) {
    return [...custom, ...base];
  }
  return base;
}

// Get Candidate Questions for the active subject filter
function getCandidateQuestions(subject = currentSelectedSubject) {
  const allMaster = getMasterQuestions();
  if (!subject || subject === 'all') {
    return allMaster;
  }

  const target = subject.trim().toLowerCase();
  return allMaster.filter(q => {
    const s = String(q.subject || '').trim();
    if (s.toLowerCase() === target) return true;
    if (typeof canonicalSubjectName === 'function') {
      return canonicalSubjectName(s).toLowerCase() === target;
    }
    return false;
  });
}

// ==========================================================================
// 2. Practice Mode Architecture (True Random Pool Engine)
// ==========================================================================

function buildPracticePool(subject = currentSelectedSubject, keepStats = false) {
  const candidates = getCandidateQuestions(subject);
  if (candidates.length === 0) {
    practicePool = [];
    practiceIndex = 0;
    return;
  }

  // Shuffle candidate questions randomly so questions are never serial
  const shuffledCandidates = shuffleArray(candidates);
  practicePool = shuffledCandidates.map(q => prepareQuestionWithOptionsShuffled(q));
  practiceIndex = 0;
  practiceAnswers = {};

  if (!keepStats) {
    practiceStats = { correct: 0, wrong: 0 };
  }
}

function jumpToRandomPracticeQuestion() {
  const candidates = getCandidateQuestions(currentSelectedSubject);
  if (candidates.length === 0) return;

  // Pick a random question that isn't the current one if possible
  let randomIndex = Math.floor(Math.random() * candidates.length);
  const currentQ = practicePool[practiceIndex];
  if (candidates.length > 1 && currentQ && candidates[randomIndex].id === currentQ.originalId) {
    randomIndex = (randomIndex + 1) % candidates.length;
  }

  const freshQ = prepareQuestionWithOptionsShuffled(candidates[randomIndex]);
  // Append after current index and advance immediately
  practicePool.splice(practiceIndex + 1, 0, freshQ);
  practiceIndex++;
  renderMCQQuestion();
  updateMCQStatsBar();
}

function advancePracticeQuestion() {
  if (practiceIndex < practicePool.length - 1) {
    practiceIndex++;
    renderMCQQuestion();
    updateMCQStatsBar();
  } else {
    // Reached end of current pool: re-shuffle and seamlessly continue
    const candidates = getCandidateQuestions(currentSelectedSubject);
    const reshuffled = shuffleArray(candidates).map(q => prepareQuestionWithOptionsShuffled(q));
    practicePool = practicePool.concat(reshuffled);
    practiceIndex++;
    renderMCQQuestion();
    updateMCQStatsBar();
    showToast("Re-shuffled 1,000 questions pool for continuous practice!", false);
  }
}

function previousPracticeQuestion() {
  if (practiceIndex > 0) {
    practiceIndex--;
    renderMCQQuestion();
    updateMCQStatsBar();
  }
}

// ==========================================================================
// 3. 20-Question Model Test Exam Mode
// ==========================================================================

function start20QuestionExam() {
  currentMCQMode = 'exam';
  examAnswers = {};
  examFlagged = {};
  examIndex = 0;
  examTimeRemaining = EXAM_DURATION_SECONDS;

  // Draw 20 purely random questions from current candidates (or all 1,000)
  const candidates = getCandidateQuestions(currentSelectedSubject);
  const count = Math.min(candidates.length, EXAM_QUESTION_COUNT);

  if (count < 5) {
    showToast(`At least 5 questions are required to start an exam (found ${count}).`, true);
    currentMCQMode = 'practice';
    return;
  }

  const shuffled = shuffleArray(candidates).slice(0, count);
  examPool = shuffled.map(q => prepareQuestionWithOptionsShuffled(q));

  // Toggle UI Elements
  const modeBanner = document.getElementById("mode-banner");
  const paletteContainer = document.getElementById("mcq-palette-container");
  const filterBar = document.getElementById("filter-bar");
  const btnPractice = document.getElementById("btnModePractice");
  const btnExam = document.getElementById("start-exam-20-btn");
  const quizCard = document.getElementById("quiz-card");
  const summaryCard = document.getElementById("summary-card");
  const modeBadge = document.getElementById("mcqCurrentModeBadge");

  if (modeBanner) modeBanner.style.display = "flex";
  if (paletteContainer) paletteContainer.style.display = "block";
  if (filterBar) filterBar.style.display = "none";
  if (btnPractice) btnPractice.classList.remove("active", "solid");
  if (btnExam) btnExam.classList.add("active", "solid");
  if (quizCard) quizCard.style.display = "block";
  if (summaryCard) summaryCard.style.display = "none";
  if (modeBadge) modeBadge.textContent = "20-Q Exam Mode";

  // Start Timer Countdown
  clearInterval(examTimerInterval);
  updateExamTimerDisplay();
  examTimerInterval = setInterval(() => {
    examTimeRemaining--;
    updateExamTimerDisplay();
    if (examTimeRemaining <= 0) {
      clearInterval(examTimerInterval);
      showToast("Time is up! Evaluating your model test...", false);
      submitExamEvaluation();
    }
  }, 1000);

  renderMCQQuestion();
  updateMCQStatsBar();
  renderExamPalette();
}

function updateExamTimerDisplay() {
  const timerEl = document.getElementById("exam-timer");
  if (!timerEl) return;
  const mins = Math.floor(Math.max(0, examTimeRemaining) / 60);
  const secs = Math.max(0, examTimeRemaining) % 60;
  timerEl.textContent = `${String(mins).padStart(2, "0")}:${String(secs).padStart(2, "0")}`;
}

function openExamSubmitConfirmation() {
  const modal = document.getElementById("examSubmitModal");
  if (!modal) {
    submitExamEvaluation();
    return;
  }

  const total = examPool.length;
  const answered = Object.keys(examAnswers).length;
  const unanswered = Math.max(0, total - answered);
  const flagged = Object.values(examFlagged).filter(Boolean).length;

  const elAns = document.getElementById("modalTallyAnswered");
  const elUnans = document.getElementById("modalTallyUnanswered");
  const elFlag = document.getElementById("modalTallyFlagged");

  if (elAns) elAns.textContent = String(answered);
  if (elUnans) elUnans.textContent = String(unanswered);
  if (elFlag) elFlag.textContent = String(flagged);

  modal.classList.add("open");
  if (window.lucide && typeof window.lucide.createIcons === 'function') {
    window.lucide.createIcons();
  }
}

function closeExamSubmitModal() {
  const modal = document.getElementById("examSubmitModal");
  if (modal) modal.classList.remove("open");
}

function submitExamEvaluation() {
  closeExamSubmitModal();
  clearInterval(examTimerInterval);

  let correctCount = 0;
  let wrongCount = 0;
  let skippedCount = 0;
  const total = examPool.length;

  examPool.forEach((q, idx) => {
    const userAns = examAnswers[idx];
    if (userAns && typeof userAns.selectedIndex === 'number') {
      const isRight = (userAns.selectedIndex === q.correct);
      userAns.isCorrect = isRight;
      if (isRight) {
        correctCount++;
      } else {
        wrongCount++;
        // Auto-save wrong question to Mistake Bank
        recordMistake({
          id: q.originalId || q.id || `mcq_${Date.now()}_${idx}`,
          q: q.question,
          subject: q.subject || "BCS Preliminary",
          yourAns: q.options[userAns.selectedIndex] || "",
          correctAns: q.options[q.correct] || "",
          explain: q.explanation || "No explanation provided."
        });
      }
    } else {
      skippedCount++;
    }
  });

  // Standard BCS Preliminary scoring: +1.0 for correct, -0.5 for wrong
  const rawScore = (correctCount * 1.0) - (wrongCount * 0.5);
  const netScore = Math.max(0, rawScore);

  renderExamSummary(correctCount, wrongCount, skippedCount, netScore, total);
}

function renderExamSummary(correctCount, wrongCount, skippedCount, netScore, total) {
  const quizCard = document.getElementById("quiz-card");
  const summaryCard = document.getElementById("summary-card");
  const modeBanner = document.getElementById("mode-banner");
  const paletteContainer = document.getElementById("mcq-palette-container");

  if (quizCard) quizCard.style.display = "none";
  if (paletteContainer) paletteContainer.style.display = "none";
  if (modeBanner) modeBanner.style.display = "none";
  if (!summaryCard) return;

  summaryCard.style.display = "block";

  const attempted = correctCount + wrongCount;
  const accuracy = attempted > 0 ? Math.round((correctCount / attempted) * 100) : 0;
  const percentage = total > 0 ? Math.round((netScore / total) * 100) : 0;
  const flaggedCount = Object.values(examFlagged).filter(Boolean).length;

  let gradeBadge = "";
  let gradeColor = "";
  if (netScore >= 16) {
    gradeBadge = "🌟 Outstanding! (Top Tier Aspirant)";
    gradeColor = "#10b981";
  } else if (netScore >= 12) {
    gradeBadge = "✓ Passed Preliminary Cutoff";
    gradeColor = "#3b82f6";
  } else if (netScore >= 9) {
    gradeBadge = "⚠️ Marginal Score (More practice recommended)";
    gradeColor = "#f59e0b";
  } else {
    gradeBadge = "✕ Below Qualifying Cutoff";
    gradeColor = "#f43f5e";
  }

  let reviewItemsHtml = "";
  examPool.forEach((q, idx) => {
    const userAns = examAnswers[idx];
    const isAnswered = Boolean(userAns && typeof userAns.selectedIndex === 'number');
    const isCorrect = isAnswered && userAns.selectedIndex === q.correct;
    const isSkipped = !isAnswered;
    const isFlagged = Boolean(examFlagged[idx]);

    let cardClass = isSkipped ? "review-card-skipped" : (isCorrect ? "review-card-correct" : "review-card-wrong");
    let statusPill = isSkipped
      ? `<span class="review-status-pill pill-skipped" style="background:rgba(148,163,184,0.15); color:var(--text-soft); font-size:11px; padding:3px 8px; border-radius:6px;">— Skipped (0.0)</span>`
      : (isCorrect
        ? `<span class="review-status-pill pill-correct" style="background:rgba(16,185,129,0.15); color:#10b981; font-size:11px; padding:3px 8px; border-radius:6px; font-weight:700;">✓ Correct (+1.0)</span>`
        : `<span class="review-status-pill pill-wrong" style="background:rgba(244,63,94,0.15); color:#f43f5e; font-size:11px; padding:3px 8px; border-radius:6px; font-weight:700;">✕ Incorrect (-0.5)</span>`);

    let optionsRowsHtml = "";
    q.options.forEach((optText, optIdx) => {
      let optClass = "review-opt-row";
      let optTag = "";
      if (optIdx === q.correct) {
        optClass += " opt-correct";
        optTag = `<span style="font-size:11.5px; color:#10b981; font-weight:700; margin-left:auto;">✓ Correct Answer</span>`;
      } else if (isAnswered && optIdx === userAns.selectedIndex && !isCorrect) {
        optClass += " opt-wrong";
        optTag = `<span style="font-size:11.5px; color:#f43f5e; font-weight:700; margin-left:auto;">✕ Your Choice</span>`;
      }
      optionsRowsHtml += `
        <div class="${optClass}" style="display:flex; align-items:center; gap:10px; padding:8px 12px; border-radius:8px; margin-bottom:6px; background:var(--surface); border:1px solid var(--border);">
          <span style="font-weight:700; width:22px; height:22px; border-radius:6px; background:var(--surface-strong); display:flex; align-items:center; justify-content:center; font-size:12px;">${PREFIX_LETTERS[optIdx]}</span>
          <span style="font-size:13.5px; color:var(--text);">${escapeHtml(optText)}</span>
          ${optTag}
        </div>
      `;
    });

    reviewItemsHtml += `
      <div class="review-card glass ${cardClass}" data-review-status="${isSkipped ? 'skipped' : (isCorrect ? 'correct' : 'wrong')}" data-flagged="${isFlagged ? 'true' : 'false'}" style="padding:16px 18px; border-radius:12px; margin-bottom:14px; border:1px solid var(--border);">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px; flex-wrap:wrap; gap:8px;">
          <div style="display:flex; align-items:center; gap:8px;">
            <span class="q-badge" style="font-size:11px; padding:2px 8px; border-radius:6px;">${escapeHtml(q.subject || "BCS Preliminary")}</span>
            <span style="font-weight:700; font-size:13px; color:var(--text-soft);">Question ${idx + 1} of ${total}</span>
            ${isFlagged ? `<span style="font-size:11px; color:#f59e0b; background:rgba(245,158,11,0.15); padding:2px 6px; border-radius:4px; font-weight:600;">Flagged</span>` : ''}
          </div>
          <div>${statusPill}</div>
        </div>
        <div style="font-size:15px; font-weight:700; color:var(--text); line-height:1.4; margin-bottom:12px;">
          ${idx + 1}. ${escapeHtml(q.question)}
        </div>
        <div class="review-options-list" style="margin-bottom:12px;">
          ${optionsRowsHtml}
        </div>
        <div style="font-size:13px; color:var(--text-soft); line-height:1.5; background:rgba(99,102,241,0.06); padding:10px 14px; border-radius:8px; border-left:3px solid var(--accent1);">
          <strong style="color:var(--accent1);"><i data-lucide="lightbulb" style="width:13px; height:13px; vertical-align:middle;"></i> Explanation &amp; Shortcut:</strong>
          <div style="margin-top:4px;">${escapeHtml(q.explanation || "No explanation provided.")}</div>
        </div>
      </div>
    `;
  });

  summaryCard.innerHTML = `
    <div class="exam-summary-wrapper" style="padding:10px 0;">
      <div style="text-align:center; margin-bottom:20px;">
        <div style="display:inline-block; padding:5px 14px; border-radius:20px; font-size:12px; font-weight:700; background:${gradeColor}18; color:${gradeColor}; border:1px solid ${gradeColor}50; margin-bottom:8px;">
          ${gradeBadge}
        </div>
        <h2 style="font-family:var(--font-display); font-size:1.4rem; margin:0 0 6px; color:var(--text);">
          BCS 20-Question Model Test Results
        </h2>
        <p style="font-size:13px; color:var(--text-soft); margin:0;">
          BCS Preliminary Negative Marking Applied (+1.0 / -0.5)
        </p>
      </div>

      <div class="glass" style="padding:20px; border-radius:14px; text-align:center; margin-bottom:18px; border:1px solid var(--border);">
        <div style="font-family:var(--font-display); font-size:2.4rem; font-weight:800; color:${gradeColor}; line-height:1;">
          ${netScore.toFixed(2)} <span style="font-size:1.1rem; color:var(--text-soft); font-weight:600;">/ ${total}.00</span>
        </div>
        <div style="font-size:13px; color:var(--text-soft); margin-top:8px;">
          Net Score &bull; Accuracy: <b style="color:var(--text);">${accuracy}%</b> &bull; Score Rate: <b style="color:var(--text);">${percentage}%</b>
        </div>
      </div>

      <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(130px, 1fr)); gap:10px; margin-bottom:22px;">
        <div class="glass" style="padding:12px; border-radius:12px; text-align:center; border:1px solid var(--border);">
          <div style="font-weight:800; font-size:1.4rem; color:#10b981;">${correctCount}</div>
          <div style="font-size:11px; text-transform:uppercase; color:var(--text-soft); font-weight:700;">✓ Correct (+${(correctCount * 1.0).toFixed(1)})</div>
        </div>
        <div class="glass" style="padding:12px; border-radius:12px; text-align:center; border:1px solid var(--border);">
          <div style="font-weight:800; font-size:1.4rem; color:#f43f5e;">${wrongCount}</div>
          <div style="font-size:11px; text-transform:uppercase; color:var(--text-soft); font-weight:700;">✕ Wrong (-${(wrongCount * 0.5).toFixed(1)})</div>
        </div>
        <div class="glass" style="padding:12px; border-radius:12px; text-align:center; border:1px solid var(--border);">
          <div style="font-weight:800; font-size:1.4rem; color:var(--text-soft);">${skippedCount}</div>
          <div style="font-size:11px; text-transform:uppercase; color:var(--text-soft); font-weight:700;">— Skipped (0.0)</div>
        </div>
      </div>

      <div class="btn-group" style="justify-content:center; margin-bottom:26px;">
        <button class="pill solid btn-exam20" id="summaryRetakeExamBtn" type="button" style="padding:10px 22px; font-weight:700;">
          <i data-lucide="zap"></i> <span>Start New 20-Q Exam</span>
        </button>
        <button class="pill" id="summaryBackPracticeBtn" type="button" style="padding:10px 20px;">
          <i data-lucide="book-open"></i> <span>Back to Practice Mode</span>
        </button>
        ${wrongCount > 0 ? `
          <button class="pill danger" id="summaryViewMistakesBtn" type="button" style="padding:10px 20px;">
            <i data-lucide="alert-circle"></i> <span>Review Mistakes (${wrongCount})</span>
          </button>
        ` : ''}
      </div>

      <div class="exam-review-section">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:14px; border-bottom:1px solid var(--border); padding-bottom:10px; flex-wrap:wrap; gap:10px;">
          <div>
            <h3 style="margin:0; font-size:16px; font-weight:700; color:var(--text);">Question Review &amp; Explanations</h3>
            <span style="font-size:12px; color:var(--text-soft);">Complete solutions for all 20 questions</span>
          </div>
          <div class="review-filter-chips" style="display:flex; gap:6px; flex-wrap:wrap;">
            <button class="pill subtle active" data-review-filter="all" style="font-size:11.5px; padding:4px 10px;">All (${total})</button>
            <button class="pill subtle" data-review-filter="correct" style="font-size:11.5px; padding:4px 10px; color:#10b981;">✓ Correct (${correctCount})</button>
            <button class="pill subtle" data-review-filter="wrong" style="font-size:11.5px; padding:4px 10px; color:#f43f5e;">✕ Wrong (${wrongCount})</button>
            <button class="pill subtle" data-review-filter="skipped" style="font-size:11.5px; padding:4px 10px;">— Skipped (${skippedCount})</button>
            ${flaggedCount > 0 ? `<button class="pill subtle" data-review-filter="flagged" style="font-size:11.5px; padding:4px 10px; color:#f59e0b;">Flagged (${flaggedCount})</button>` : ''}
          </div>
        </div>

        <div class="exam-review-list">
          ${reviewItemsHtml}
        </div>
      </div>
    </div>
  `;

  // Review Filter handling
  const filterPills = summaryCard.querySelectorAll("[data-review-filter]");
  filterPills.forEach(pill => {
    pill.addEventListener("click", () => {
      filterPills.forEach(p => p.classList.remove("active", "solid"));
      pill.classList.add("active", "solid");
      const filterVal = pill.getAttribute("data-review-filter");
      summaryCard.querySelectorAll(".review-card").forEach(card => {
        if (filterVal === "all") {
          card.style.display = "block";
        } else if (filterVal === "correct") {
          card.style.display = card.getAttribute("data-review-status") === "correct" ? "block" : "none";
        } else if (filterVal === "wrong") {
          card.style.display = card.getAttribute("data-review-status") === "wrong" ? "block" : "none";
        } else if (filterVal === "skipped") {
          card.style.display = card.getAttribute("data-review-status") === "skipped" ? "block" : "none";
        } else if (filterVal === "flagged") {
          card.style.display = card.getAttribute("data-flagged") === "true" ? "block" : "none";
        }
      });
    });
  });

  const retakeBtn = document.getElementById("summaryRetakeExamBtn");
  if (retakeBtn) retakeBtn.addEventListener("click", start20QuestionExam);

  const backBtn = document.getElementById("summaryBackPracticeBtn");
  if (backBtn) backBtn.addEventListener("click", switchToPracticeMode);

  const viewMistakesBtn = document.getElementById("summaryViewMistakesBtn");
  if (viewMistakesBtn) {
    viewMistakesBtn.addEventListener("click", () => {
      const mistakeTab = document.querySelector("#quizFlashSwitch [data-view='mistakes']");
      if (mistakeTab) mistakeTab.click();
    });
  }

  if (window.lucide && typeof window.lucide.createIcons === 'function') {
    window.lucide.createIcons();
  }
}

function switchToPracticeMode() {
  clearInterval(examTimerInterval);
  currentMCQMode = 'practice';

  const modeBanner = document.getElementById("mode-banner");
  const paletteContainer = document.getElementById("mcq-palette-container");
  const filterBar = document.getElementById("filter-bar");
  const btnPractice = document.getElementById("btnModePractice");
  const btnExam = document.getElementById("start-exam-20-btn");
  const quizCard = document.getElementById("quiz-card");
  const summaryCard = document.getElementById("summary-card");
  const modeBadge = document.getElementById("mcqCurrentModeBadge");

  if (modeBanner) modeBanner.style.display = "none";
  if (paletteContainer) paletteContainer.style.display = "none";
  if (filterBar) filterBar.style.display = "flex";
  if (btnPractice) btnPractice.classList.add("active", "solid");
  if (btnExam) btnExam.classList.remove("active", "solid");
  if (quizCard) quizCard.style.display = "block";
  if (summaryCard) summaryCard.style.display = "none";
  if (modeBadge) modeBadge.textContent = "Practice Mode";

  if (!practicePool.length) {
    buildPracticePool(currentSelectedSubject);
  }

  renderMCQQuestion();
  updateMCQStatsBar();
}

function renderExamPalette() {
  const container = document.getElementById("mcq-palette-container");
  const grid = document.getElementById("mcq-palette-grid");
  if (!container || !grid || currentMCQMode !== 'exam') return;

  grid.innerHTML = "";
  examPool.forEach((q, idx) => {
    const isCurrent = (idx === examIndex);
    const isAnswered = Boolean(examAnswers[idx] && typeof examAnswers[idx].selectedIndex === 'number');
    const isFlagged = Boolean(examFlagged[idx]);

    const chip = document.createElement("button");
    chip.type = "button";
    chip.className = "palette-chip" +
      (isCurrent ? " current" : "") +
      (isAnswered ? " answered" : "") +
      (isFlagged ? " flagged" : "");
    chip.textContent = String(idx + 1);
    chip.title = `Question ${idx + 1}${isFlagged ? " (Flagged)" : (isAnswered ? " (Answered)" : "")}`;
    chip.addEventListener("click", () => {
      examIndex = idx;
      renderMCQQuestion();
      updateMCQStatsBar();
      renderExamPalette();
    });
    grid.appendChild(chip);
  });
}

function toggleExamFlagCurrent() {
  if (currentMCQMode !== 'exam') return;
  examFlagged[examIndex] = !examFlagged[examIndex];
  renderMCQQuestion();
  renderExamPalette();
}

// ==========================================================================
// 4. Core Question & Option Rendering Engine
// ==========================================================================

function getCurrentActiveQuestion() {
  if (currentMCQMode === 'exam') {
    return examPool[examIndex] || null;
  }
  return practicePool[practiceIndex] || null;
}

function renderMCQQuestion() {
  const quizCard = document.getElementById("quiz-card");
  const summaryCard = document.getElementById("summary-card");
  const qSubject = document.getElementById("q-subject");
  const qSourceTag = document.getElementById("q-source-tag");
  const qCounterBadge = document.getElementById("q-counter-badge");
  const qFlagBtn = document.getElementById("qFlagBtn");
  const qFlagText = document.getElementById("qFlagText");
  const qText = document.getElementById("q-text");
  const optionsContainer = document.getElementById("options-container");
  const explanationBox = document.getElementById("explanation-box");
  const explanationText = document.getElementById("explanation-text");
  const prevBtn = document.getElementById("prev-btn");
  const nextBtn = document.getElementById("next-btn");

  if (!quizCard) return;
  quizCard.style.display = "block";
  quizCard.setAttribute("aria-busy", "false");
  if (summaryCard) summaryCard.style.display = "none";

  const q = getCurrentActiveQuestion();
  if (!q) {
    if (qText) qText.textContent = "No questions found for this subject.";
    if (optionsContainer) optionsContainer.innerHTML = "";
    if (explanationBox) explanationBox.classList.remove("show");
    if (prevBtn) prevBtn.style.display = "none";
    if (nextBtn) nextBtn.style.display = "none";
    return;
  }

  // Render Question Meta
  const subj = q.subject || "BCS Preliminary";
  const meta = BCS_SUBJECT_META[subj] || (typeof getSubjectMeta === 'function' ? getSubjectMeta(subj) : { icon: 'book-open' });

  if (qSubject) {
    qSubject.innerHTML = `<i data-lucide="${meta.icon || 'book-open'}" style="width:13px; height:13px; vertical-align:middle; margin-right:4px;"></i> <span>${escapeHtml(subj)}</span>`;
  }
  if (qSourceTag) {
    qSourceTag.textContent = "BCS Question Pool";
  }

  // Counter Badge & Flag Controls
  if (currentMCQMode === 'exam') {
    if (qCounterBadge) {
      qCounterBadge.innerHTML = `<i data-lucide="hash" style="width:12px; height:12px; vertical-align:middle;"></i> Question ${examIndex + 1} of ${examPool.length}`;
    }
    if (qFlagBtn && qFlagText) {
      qFlagBtn.style.display = "inline-flex";
      const isFlagged = Boolean(examFlagged[examIndex]);
      qFlagBtn.classList.toggle("flagged", isFlagged);
      qFlagText.textContent = isFlagged ? "Flagged" : "Mark for Review";
      qFlagBtn.title = isFlagged ? "Click to remove review flag" : "Mark this question to review before submitting";
    }
  } else {
    if (qCounterBadge) {
      qCounterBadge.innerHTML = `<i data-lucide="shuffle" style="width:12px; height:12px; vertical-align:middle;"></i> Random Q #${practiceIndex + 1}`;
    }
    if (qFlagBtn && qFlagText) {
      qFlagBtn.style.display = "inline-flex";
      const isBookmarked = mistakes.some(m => m.q === q.question || String(m.id) === String(q.originalId || q.id));
      qFlagBtn.classList.toggle("flagged", isBookmarked);
      qFlagText.textContent = isBookmarked ? "Saved in Mistakes" : "Save to Mistakes";
      qFlagBtn.title = isBookmarked ? "Question is recorded in your Mistake Bank" : "Bookmark this question into your Mistake Bank";
    }
  }

  // Question Text
  if (qText) {
    const qNumberPrefix = currentMCQMode === 'exam' ? `${examIndex + 1}. ` : `${practiceIndex + 1}. `;
    qText.textContent = qNumberPrefix + q.question;
  }

  // Render Options
  if (optionsContainer) {
    optionsContainer.innerHTML = "";

    if (currentMCQMode === 'exam') {
      // EXAM MODE: Neutral selection, no instant answers
      const recorded = examAnswers[examIndex];
      const selectedIdx = recorded ? recorded.selectedIndex : undefined;

      q.options.forEach((optText, optIdx) => {
        const btn = document.createElement("button");
        btn.type = "button";
        const isSelected = (selectedIdx === optIdx);
        btn.className = "quiz-opt-btn" + (isSelected ? " selected-exam" : "");
        btn.innerHTML = `
          <div style="display:flex; align-items:center; gap:12px; width:100%;">
            <span style="font-weight:700; width:26px; height:26px; border-radius:8px; background:var(--surface-strong); display:flex; align-items:center; justify-content:center; font-size:12.5px; flex-shrink:0;">${PREFIX_LETTERS[optIdx]}</span>
            <span style="font-size:14px; line-height:1.4; flex-grow:1;">${escapeHtml(optText)}</span>
            ${isSelected ? '<span style="font-size:11.5px; color:var(--accent1); font-weight:700; margin-left:auto;">Selected</span>' : ''}
          </div>
        `;
        btn.onclick = () => selectOption(optIdx);
        optionsContainer.appendChild(btn);
      });

      if (explanationBox) explanationBox.classList.remove("show");

    } else {
      // PRACTICE MODE: Instant feedback and explanations
      const recorded = practiceAnswers[practiceIndex];

      q.options.forEach((optText, optIdx) => {
        const btn = document.createElement("button");
        btn.type = "button";
        btn.className = "quiz-opt-btn";

        let statusTag = "";
        if (recorded !== undefined) {
          btn.disabled = true;
          if (optIdx === q.correct) {
            btn.classList.add("correct");
            statusTag = `<span style="color:#10b981; font-weight:700; font-size:12px; margin-left:auto;">✓ Correct</span>`;
          } else if (optIdx === recorded.selectedIndex && !recorded.isCorrect) {
            btn.classList.add("wrong");
            statusTag = `<span style="color:#f43f5e; font-weight:700; font-size:12px; margin-left:auto;">✕ Your Choice</span>`;
          }
        } else {
          btn.onclick = () => selectOption(optIdx);
        }

        btn.innerHTML = `
          <div style="display:flex; align-items:center; gap:12px; width:100%;">
            <span style="font-weight:700; width:26px; height:26px; border-radius:8px; background:var(--surface-strong); display:flex; align-items:center; justify-content:center; font-size:12.5px; flex-shrink:0;">${PREFIX_LETTERS[optIdx]}</span>
            <span style="font-size:14px; line-height:1.4; flex-grow:1;">${escapeHtml(optText)}</span>
            ${statusTag}
          </div>
        `;
        optionsContainer.appendChild(btn);
      });

      // Explanation Box
      if (recorded !== undefined && explanationBox && explanationText) {
        if (recorded.isCorrect) {
          explanationText.innerHTML = `
            <div style="color:#10b981; font-weight:700; font-size:13px; margin-bottom:6px;">✓ Correct (+1.0 point earned)</div>
            <div>${escapeHtml(q.explanation || "No explanation provided.")}</div>
          `;
        } else {
          const chosenText = escapeHtml(q.options[recorded.selectedIndex] || "");
          const rightText = escapeHtml(q.options[q.correct] || "");
          explanationText.innerHTML = `
            <div style="color:#f43f5e; font-weight:700; font-size:13px; margin-bottom:6px;">✕ Incorrect (-0.5 negative marking) &bull; Auto-saved to Mistake Bank</div>
            <div style="font-size:13px; margin-bottom:6px;">
              <strong>Your Choice:</strong> <span style="color:#f43f5e;">${chosenText}</span> &nbsp;|&nbsp;
              <strong>Correct Answer:</strong> <span style="color:#10b981;">${rightText}</span>
            </div>
            <div><strong>Explanation:</strong> ${escapeHtml(q.explanation || "No explanation provided.")}</div>
          `;
        }
        explanationBox.classList.add("show");
      } else if (explanationBox) {
        explanationBox.classList.remove("show");
      }
    }
  }

  // Navigation Buttons
  if (prevBtn) {
    if (currentMCQMode === 'exam') {
      prevBtn.style.display = examIndex > 0 ? "inline-flex" : "none";
    } else {
      prevBtn.style.display = practiceIndex > 0 ? "inline-flex" : "none";
    }
  }

  if (nextBtn) {
    nextBtn.style.display = "inline-flex";
    if (currentMCQMode === 'exam') {
      if (examIndex === examPool.length - 1) {
        nextBtn.innerHTML = `<span>Finish &amp; Submit</span> <i data-lucide="check-circle"></i>`;
      } else {
        nextBtn.innerHTML = `<span>Next Question</span> <i data-lucide="arrow-right"></i>`;
      }
    } else {
      nextBtn.innerHTML = `<i data-lucide="shuffle"></i> <span>Next Random Question</span> <i data-lucide="arrow-right"></i>`;
    }
  }

  if (window.lucide && typeof window.lucide.createIcons === 'function') {
    window.lucide.createIcons();
  }
}

function selectOption(selectedIdx) {
  const q = getCurrentActiveQuestion();
  if (!q) return;

  if (currentMCQMode === 'exam') {
    // Record Exam Answer
    examAnswers[examIndex] = { selectedIndex: selectedIdx };
    renderMCQQuestion();
    renderExamPalette();
    updateMCQStatsBar();
    return;
  }

  // PRACTICE MODE: Check if already answered
  if (practiceAnswers[practiceIndex] !== undefined) return;

  const isCorrect = (selectedIdx === q.correct);
  practiceAnswers[practiceIndex] = { selectedIndex: selectedIdx, isCorrect };

  if (isCorrect) {
    practiceStats.correct++;
  } else {
    practiceStats.wrong++;
    // Auto-record to Mistake Bank
    recordMistake({
      id: q.originalId || q.id || `mcq_${Date.now()}`,
      q: q.question,
      subject: q.subject || "BCS Preliminary",
      yourAns: q.options[selectedIdx] || "",
      correctAns: q.options[q.correct] || "",
      explain: q.explanation || "No explanation provided."
    });
  }

  renderMCQQuestion();
  updateMCQStatsBar();
}

function recordMistake(item) {
  if (!item || !item.q) return;
  const exists = mistakes.some(m => m.q === item.q || (item.id && String(m.id) === String(item.id)));
  if (!exists) {
    mistakes.unshift({
      id: item.id || `m_${Date.now()}`,
      q: item.q,
      subject: item.subject || "General",
      yourAns: item.yourAns || "",
      correctAns: item.correctAns || "",
      explain: item.explain || "No explanation provided.",
      date: new Date().toLocaleDateString()
    });
    saveMistakes();
    renderMistakes();
  }
}

function toggleFlagOrBookmark() {
  if (currentMCQMode === 'exam') {
    toggleExamFlagCurrent();
    return;
  }

  // In Practice Mode: Bookmark current question to Mistake Bank
  const q = getCurrentActiveQuestion();
  if (!q) return;

  const existingIdx = mistakes.findIndex(m => m.q === q.question || String(m.id) === String(q.originalId || q.id));
  if (existingIdx !== -1) {
    mistakes.splice(existingIdx, 1);
    saveMistakes();
    renderMistakes();
    showToast("Question removed from Mistake Bank");
  } else {
    recordMistake({
      id: q.originalId || q.id,
      q: q.question,
      subject: q.subject,
      yourAns: "Bookmarked for practice",
      correctAns: q.options[q.correct] || "",
      explain: q.explanation || "No explanation provided."
    });
    showToast("Question saved to Mistake Bank for revision!");
  }
  renderMCQQuestion();
}

// ==========================================================================
// 5. Dashboard Stats Bar Updates
// ==========================================================================

function updateMCQStatsBar() {
  const currentIndexEl = document.getElementById("current-index");
  const progressBar = document.getElementById("mcqProgressBar");
  const correctCountEl = document.getElementById("correct-count");
  const wrongCountEl = document.getElementById("wrong-count");
  const scoreValEl = document.getElementById("score-val");

  if (currentMCQMode === 'exam') {
    const total = examPool.length || EXAM_QUESTION_COUNT;
    const answeredCount = Object.keys(examAnswers).length;
    const remainingCount = Math.max(0, total - answeredCount);

    if (currentIndexEl) currentIndexEl.textContent = `${examIndex + 1} / ${total}`;
    if (progressBar) {
      const pct = Math.min(100, Math.round(((examIndex + 1) / total) * 100));
      progressBar.style.width = `${pct}%`;
    }
    if (correctCountEl) {
      correctCountEl.textContent = String(answeredCount);
      const lbl = correctCountEl.nextElementSibling;
      if (lbl) lbl.textContent = "Answered";
    }
    if (wrongCountEl) {
      wrongCountEl.textContent = String(remainingCount);
      const lbl = wrongCountEl.nextElementSibling;
      if (lbl) lbl.textContent = "Remaining";
    }
    if (scoreValEl) {
      scoreValEl.textContent = "Locked";
      const lbl = scoreValEl.nextElementSibling;
      if (lbl) lbl.textContent = "Results on Submit";
    }
  } else {
    const totalCandidates = getCandidateQuestions(currentSelectedSubject).length || 1000;
    const studiedCount = practiceIndex + 1;

    if (currentIndexEl) currentIndexEl.textContent = `${studiedCount} / ${totalCandidates}`;
    if (progressBar) {
      const pct = Math.min(100, Math.max(1, Math.round((studiedCount / totalCandidates) * 100)));
      progressBar.style.width = `${pct}%`;
    }
    if (correctCountEl) {
      correctCountEl.textContent = String(practiceStats.correct);
      const lbl = correctCountEl.nextElementSibling;
      if (lbl) lbl.textContent = "Correct (+1.0)";
    }
    if (wrongCountEl) {
      wrongCountEl.textContent = String(practiceStats.wrong);
      const lbl = wrongCountEl.nextElementSibling;
      if (lbl) lbl.textContent = "Incorrect (-0.5)";
    }
    const netMarks = (practiceStats.correct * 1.0) - (practiceStats.wrong * 0.5);
    if (scoreValEl) {
      scoreValEl.textContent = netMarks.toFixed(2);
      const lbl = scoreValEl.nextElementSibling;
      if (lbl) lbl.textContent = "Net Score";
    }
  }
}

// ==========================================================================
// 6. Category Filter Bar (10 BCS Subjects + All)
// ==========================================================================

function renderMCQFilterBar() {
  const filterBar = document.getElementById("filter-bar");
  if (!filterBar) return;

  const allMaster = getMasterQuestions();
  const subjectCounts = {};
  allMaster.forEach(q => {
    const s = String(q.subject || '').trim();
    if (s) subjectCounts[s] = (subjectCounts[s] || 0) + 1;
  });

  const allCount = allMaster.length || 1000;
  let html = `
    <button type="button" class="filter-pill ${currentSelectedSubject === 'all' ? 'active' : ''}" data-subject="all">
      <i data-lucide="layers" style="width:13px; height:13px;"></i>
      <span>All Subjects (${allCount})</span>
    </button>
  `;

  Object.keys(BCS_SUBJECT_META).forEach(subj => {
    const meta = BCS_SUBJECT_META[subj];
    const count = subjectCounts[subj] || 0;
    const isActive = (currentSelectedSubject === subj);
    html += `
      <button type="button" class="filter-pill ${isActive ? 'active' : ''}" data-subject="${escapeAttr(subj)}">
        <i data-lucide="${meta.icon}" style="width:13px; height:13px;"></i>
        <span>${escapeHtml(subj)} (${count})</span>
      </button>
    `;
  });

  filterBar.innerHTML = html;

  filterBar.querySelectorAll(".filter-pill").forEach(pill => {
    pill.addEventListener("click", () => {
      const targetSubj = pill.getAttribute("data-subject") || 'all';
      currentSelectedSubject = targetSubj;
      filterBar.querySelectorAll(".filter-pill").forEach(p => p.classList.remove("active"));
      pill.classList.add("active");

      // Rebuild random pool for selected subject
      buildPracticePool(currentSelectedSubject);
      renderMCQQuestion();
      updateMCQStatsBar();
    });
  });

  if (window.lucide && typeof window.lucide.createIcons === 'function') {
    window.lucide.createIcons();
  }
}

// ==========================================================================
// 7. Mistake Bank Management
// ==========================================================================

function renderMistakes() {
  const list = document.getElementById("mistakeBankList");
  if (!list) return;

  updateMistakeBadge();

  if (!mistakes.length) {
    list.innerHTML = `
      <div style="text-align:center; padding:36px 16px; color:var(--text-soft);">
        <i data-lucide="check-circle" style="width:40px; height:40px; color:#10b981; margin-bottom:10px; display:inline-block;"></i>
        <div style="font-weight:700; font-size:15px; color:var(--text); margin-bottom:4px;">No mistakes recorded!</div>
        <p style="font-size:13px; margin:0;">Great job! As you practice quizzes, missed questions will appear here for targeted remediation.</p>
      </div>
    `;
    if (window.lucide && typeof window.lucide.createIcons === 'function') {
      window.lucide.createIcons();
    }
    return;
  }

  let html = "";
  mistakes.forEach((m, idx) => {
    const meta = BCS_SUBJECT_META[m.subject] || { icon: 'alert-circle' };
    html += `
      <div class="mistake-card glass" style="padding:16px 18px; margin-bottom:12px; border-radius:12px; border:1px solid var(--border);">
        <div style="display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:8px; gap:10px;">
          <h4 style="margin:0; font-size:15px; font-weight:700; color:var(--text); line-height:1.4;">${escapeHtml(m.q)}</h4>
          <div style="display:flex; align-items:center; gap:8px; flex-shrink:0;">
            ${m.subject ? `<span class="q-badge" style="font-size:11px; padding:2px 8px; display:inline-flex; align-items:center; gap:4px;"><i data-lucide="${meta.icon}" style="width:12px; height:12px;"></i> <span>${escapeHtml(m.subject)}</span></span>` : ""}
            <button class="pill danger mistake-del-btn" data-del-mistake="${idx}" title="Remove question from Mistake Bank" aria-label="Remove question" style="padding:4px 10px; font-size:11px;">
              <i data-lucide="trash-2" style="width:12px; height:12px;"></i> <span>Remove</span>
            </button>
          </div>
        </div>
        <div class="mistake-ans-row" style="display:flex; gap:14px; margin-bottom:8px; flex-wrap:wrap; font-size:13px;">
          <span style="color:#f43f5e; font-weight:600;">Your Choice: ${escapeHtml(m.yourAns || "None")}</span>
          <span style="color:#10b981; font-weight:600;">Correct Answer: ${escapeHtml(m.correctAns || "N/A")}</span>
        </div>
        <div style="font-size:13px; color:var(--text-soft); line-height:1.5; background:rgba(99,102,241,0.06); padding:8px 12px; border-radius:8px; border-left:3px solid var(--accent1);">
          <strong>Explanation:</strong> ${escapeHtml(m.explain || "No explanation recorded.")}
        </div>
      </div>
    `;
  });

  list.innerHTML = html;

  list.querySelectorAll("[data-del-mistake]").forEach(btn => {
    btn.addEventListener("click", (e) => {
      const targetBtn = e.target.closest("[data-del-mistake]");
      if (!targetBtn) return;
      const i = parseInt(targetBtn.getAttribute("data-del-mistake"), 10);
      if (isNaN(i)) return;
      mistakes.splice(i, 1);
      saveMistakes();
      renderMistakes();
      showToast("Question removed from Mistake Bank");
    });
  });

  if (window.lucide && typeof window.lucide.createIcons === 'function') {
    window.lucide.createIcons();
  }
}

function practiceAllMistakes() {
  if (!mistakes.length) {
    showToast("No mistakes recorded to practice!", true);
    return;
  }

  // Switch to quiz subview
  const quizTab = document.querySelector("#quizFlashSwitch [data-view='quiz']");
  if (quizTab) quizTab.click();

  // Find candidate questions matching the mistake texts
  const allMaster = getMasterQuestions();
  const mistakeQuestions = [];

  mistakes.forEach(m => {
    const found = allMaster.find(q => q.question === m.q || String(q.id) === String(m.id));
    if (found) {
      mistakeQuestions.push(found);
    } else {
      mistakeQuestions.push({
        id: m.id,
        subject: m.subject || "Mistake Bank",
        question: m.q,
        options: [m.correctAns, m.yourAns, "None of the above", "Both are applicable"],
        correct: 0,
        explanation: m.explain
      });
    }
  });

  currentMCQMode = 'practice';
  practicePool = shuffleArray(mistakeQuestions).map(q => prepareQuestionWithOptionsShuffled(q));
  practiceIndex = 0;
  practiceAnswers = {};
  practiceStats = { correct: 0, wrong: 0 };

  switchToPracticeMode();
  showToast(`Loaded ${practicePool.length} mistakes for targeted practice!`);
}

function clearAllMistakes() {
  if (!mistakes.length) {
    showToast("Mistake bank is already empty.");
    return;
  }
  if (window.confirm("Are you sure you want to clear all recorded mistakes?")) {
    mistakes = [];
    saveMistakes();
    renderMistakes();
    showToast("Mistake bank cleared successfully.");
  }
}

// ==========================================================================
// 8. Bootstrap & Event Listeners
// ==========================================================================

function initMCQEngine() {
  loadMistakes();

  // Subview Switcher (MCQ Quiz vs Mistake Bank)
  const quizFlashSwitch = document.getElementById("quizFlashSwitch");
  if (quizFlashSwitch) {
    quizFlashSwitch.addEventListener("click", (e) => {
      const chip = e.target.closest(".chip");
      if (!chip) return;
      quizFlashSwitch.querySelectorAll(".chip").forEach(c => c.classList.remove("active", "solid"));
      chip.classList.add("active", "solid");
      const view = chip.dataset.view;

      const subQuiz = document.getElementById("subview-quiz");
      const subMistakes = document.getElementById("subview-mistakes");

      if (subQuiz) subQuiz.style.display = (view === "quiz") ? "block" : "none";
      if (subMistakes) subMistakes.style.display = (view === "mistakes") ? "block" : "none";

      if (view === "mistakes") {
        renderMistakes();
      }
    });
  }

  // Mode Buttons
  const btnPractice = document.getElementById("btnModePractice");
  if (btnPractice) {
    btnPractice.addEventListener("click", () => {
      if (currentMCQMode === 'exam') {
        if (window.confirm("Switch to Practice Mode? Current 20-Q Exam will be terminated.")) {
          switchToPracticeMode();
        }
      } else {
        switchToPracticeMode();
      }
    });
  }

  const startExam20Btn = document.getElementById("start-exam-20-btn");
  if (startExam20Btn) {
    startExam20Btn.addEventListener("click", start20QuestionExam);
  }

  // Quick Tools
  const randomQuestionBtn = document.getElementById("randomQuestionBtn");
  if (randomQuestionBtn) {
    randomQuestionBtn.addEventListener("click", () => {
      if (currentMCQMode === 'exam') {
        showToast("Random Question button is only active during Practice Mode.", true);
        return;
      }
      jumpToRandomPracticeQuestion();
    });
  }

  const resetBtn = document.getElementById("reset-btn");
  if (resetBtn) {
    resetBtn.addEventListener("click", () => {
      if (currentMCQMode === 'exam') {
        if (window.confirm("Restart exam with fresh questions?")) {
          start20QuestionExam();
        }
      } else {
        buildPracticePool(currentSelectedSubject);
        renderMCQQuestion();
        updateMCQStatsBar();
        showToast("Question pool re-shuffled and stats reset!");
      }
    });
  }

  // Question Card Actions
  const qFlagBtn = document.getElementById("qFlagBtn");
  if (qFlagBtn) {
    qFlagBtn.addEventListener("click", toggleFlagOrBookmark);
  }

  const prevBtn = document.getElementById("prev-btn");
  if (prevBtn) {
    prevBtn.addEventListener("click", () => {
      if (currentMCQMode === 'exam') {
        if (examIndex > 0) {
          examIndex--;
          renderMCQQuestion();
          updateMCQStatsBar();
          renderExamPalette();
        }
      } else {
        previousPracticeQuestion();
      }
    });
  }

  const nextBtn = document.getElementById("next-btn");
  if (nextBtn) {
    nextBtn.addEventListener("click", () => {
      if (currentMCQMode === 'exam') {
        if (examIndex < examPool.length - 1) {
          examIndex++;
          renderMCQQuestion();
          updateMCQStatsBar();
          renderExamPalette();
        } else {
          openExamSubmitConfirmation();
        }
      } else {
        advancePracticeQuestion();
      }
    });
  }

  // Exam Finish & Modal Submit
  const finishEarlyBtn = document.getElementById("finishEarlyBtn");
  if (finishEarlyBtn) {
    finishEarlyBtn.addEventListener("click", openExamSubmitConfirmation);
  }

  const btnConfirmSubmit = document.getElementById("btnConfirmSubmitExam");
  if (btnConfirmSubmit) {
    btnConfirmSubmit.addEventListener("click", submitExamEvaluation);
  }

  const btnCancelSubmit = document.getElementById("btnCancelSubmitExam");
  if (btnCancelSubmit) {
    btnCancelSubmit.addEventListener("click", closeExamSubmitModal);
  }

  const examModal = document.getElementById("examSubmitModal");
  if (examModal) {
    examModal.addEventListener("click", (e) => {
      if (e.target === examModal) closeExamSubmitModal();
    });
  }

  // Mistake Bank Action Buttons
  const practiceMistakesQuizBtn = document.getElementById("practiceMistakesQuizBtn");
  if (practiceMistakesQuizBtn) {
    practiceMistakesQuizBtn.addEventListener("click", practiceAllMistakes);
  }

  const clearMistakesBtn = document.getElementById("clearMistakesBtn");
  if (clearMistakesBtn) {
    clearMistakesBtn.addEventListener("click", clearAllMistakes);
  }

  // Summary Card Action Buttons
  const retake20Btn = document.getElementById("retake-20-btn");
  if (retake20Btn) {
    retake20Btn.addEventListener("click", start20QuestionExam);
  }

  const restartBtn = document.getElementById("restart-btn");
  if (restartBtn) {
    restartBtn.addEventListener("click", switchToPracticeMode);
  }

  // Manage Questions Modal Controls
  const btnOpenManageQuestions = document.getElementById("btnOpenManageQuestions");
  if (btnOpenManageQuestions) {
    btnOpenManageQuestions.addEventListener("click", openManageQuestionsModal);
  }

  const mcqModalTabSwitch = document.getElementById("mcqModalTabSwitch");
  if (mcqModalTabSwitch) {
    mcqModalTabSwitch.addEventListener("click", (e) => {
      const chip = e.target.closest(".chip");
      if (chip && chip.dataset.tab) {
        setManageQuestionsTab(chip.dataset.tab);
      }
    });
  }

  const addQuestionForm = document.getElementById("add-question-form");
  if (addQuestionForm) {
    addQuestionForm.addEventListener("submit", handleAddCustomQuestion);
  }

  const btnExportJson = document.getElementById("btn-export-mcq-json");
  if (btnExportJson) {
    btnExportJson.addEventListener("click", handleExportMCQJson);
  }

  const btnImportJson = document.getElementById("btn-import-json");
  if (btnImportJson) {
    btnImportJson.addEventListener("click", handleImportMCQJson);
  }

  // Initial Pool Build and First Render
  buildPracticePool(currentSelectedSubject);
  renderMCQFilterBar();
  renderMCQQuestion();
  updateMCQStatsBar();
}

// ==========================================================================
// 8. Custom Questions & JSON Import / Export Manager
// ==========================================================================

function openManageQuestionsModal() {
  const modal = document.getElementById('add-modal');
  if (!modal) return;

  const newSubjSel = document.getElementById('new-subject');
  if (newSubjSel) {
    const subs = (typeof masterSubjectList === 'function') ? masterSubjectList(false) : Object.keys(BCS_SUBJECT_META);
    newSubjSel.innerHTML = subs.map(s => `<option value="${escapeAttr(s)}">${escapeHtml(s)}</option>`).join('');
  }

  setManageQuestionsTab('create');
  modal.classList.add('open');
  if (window.lucide && typeof window.lucide.createIcons === 'function') {
    window.lucide.createIcons();
  }
}
window.openManageQuestionsModal = openManageQuestionsModal;

function closeManageQuestionsModal() {
  const modal = document.getElementById('add-modal');
  if (modal) modal.classList.remove('open');
}
window.closeManageQuestionsModal = closeManageQuestionsModal;

function setManageQuestionsTab(tabName) {
  const tabSwitch = document.getElementById('mcqModalTabSwitch');
  const createPanel = document.getElementById('modal-tab-create');
  const importPanel = document.getElementById('modal-tab-import');

  if (tabSwitch) {
    tabSwitch.querySelectorAll('.chip').forEach(c => {
      const isTarget = c.dataset.tab === tabName;
      c.classList.toggle('active', isTarget);
      c.classList.toggle('solid', isTarget);
    });
  }

  if (createPanel) createPanel.style.display = (tabName === 'create') ? 'block' : 'none';
  if (importPanel) importPanel.style.display = (tabName === 'import') ? 'block' : 'none';
}

function handleAddCustomQuestion(e) {
  e.preventDefault();
  const subjEl = document.getElementById('new-subject');
  const qEl = document.getElementById('new-question');
  const opt0El = document.getElementById('opt-0');
  const opt1El = document.getElementById('opt-1');
  const opt2El = document.getElementById('opt-2');
  const opt3El = document.getElementById('opt-3');
  const correctEl = document.getElementById('new-correct');
  const expEl = document.getElementById('new-explanation');

  const subject = subjEl ? subjEl.value.trim() : 'General';
  const question = qEl ? qEl.value.trim() : '';
  const opt0 = opt0El ? opt0El.value.trim() : '';
  const opt1 = opt1El ? opt1El.value.trim() : '';
  const opt2 = opt2El ? opt2El.value.trim() : '';
  const opt3 = opt3El ? opt3El.value.trim() : '';
  const correct = correctEl ? parseInt(correctEl.value, 10) : 0;
  const explanation = expEl ? expEl.value.trim() : '';

  if (!question || !opt0 || !opt1 || !opt2 || !opt3) {
    if (typeof showToast === 'function') showToast('Please enter the question and all 4 options.', true);
    return;
  }

  const newQ = {
    id: Date.now(),
    subject,
    question,
    options: [opt0, opt1, opt2, opt3],
    correct: isNaN(correct) ? 0 : correct,
    explanation: explanation || 'Custom question.'
  };

  const currentCustom = getStoredQuestions();
  currentCustom.unshift(newQ);
  saveStoredQuestions(currentCustom);

  if (qEl) qEl.value = '';
  if (opt0El) opt0El.value = '';
  if (opt1El) opt1El.value = '';
  if (opt2El) opt2El.value = '';
  if (opt3El) opt3El.value = '';
  if (expEl) expEl.value = '';

  closeManageQuestionsModal();

  buildPracticePool(currentSelectedSubject, true);
  renderMCQFilterBar();
  renderMCQQuestion();
  updateMCQStatsBar();

  if (typeof showToast === 'function') {
    showToast('Custom question saved successfully!');
  }
}

function handleExportMCQJson() {
  const master = getMasterQuestions();
  const jsonStr = JSON.stringify(master, null, 2);

  const textarea = document.getElementById('agent-import-text');
  if (textarea) textarea.value = jsonStr;

  const blob = new Blob([jsonStr], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'careerdesk-mcq-question-bank.json';
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);

  if (typeof showToast === 'function') {
    showToast(`Exported ${master.length} questions as JSON!`);
  }
}

function handleImportMCQJson() {
  const textarea = document.getElementById('agent-import-text');
  if (!textarea || !textarea.value.trim()) {
    if (typeof showToast === 'function') showToast('Please paste a valid JSON questions array.', true);
    return;
  }

  try {
    const parsed = JSON.parse(textarea.value.trim());
    if (!Array.isArray(parsed) || !parsed.length) {
      if (typeof showToast === 'function') showToast('JSON must be a non-empty array of question objects.', true);
      return;
    }

    const validQuestions = [];
    parsed.forEach((item, idx) => {
      if (item && item.question && Array.isArray(item.options) && item.options.length >= 2) {
        validQuestions.push({
          id: item.id || (Date.now() + idx),
          subject: item.subject || 'General',
          question: String(item.question).trim(),
          options: item.options.map(o => String(o).trim()),
          correct: typeof item.correct === 'number' ? item.correct : 0,
          explanation: item.explanation ? String(item.explanation).trim() : ''
        });
      }
    });

    if (!validQuestions.length) {
      if (typeof showToast === 'function') showToast('No valid questions found in JSON array.', true);
      return;
    }

    const existing = getStoredQuestions();
    const merged = [...validQuestions, ...existing];
    saveStoredQuestions(merged);

    textarea.value = '';
    closeManageQuestionsModal();

    buildPracticePool(currentSelectedSubject, true);
    renderMCQFilterBar();
    renderMCQQuestion();
    updateMCQStatsBar();

    if (typeof showToast === 'function') {
      showToast(`Successfully imported ${validQuestions.length} questions!`);
    }
  } catch (err) {
    if (typeof showToast === 'function') showToast('Invalid JSON syntax: ' + err.message, true);
  }
}

// Auto-run on DOM ready or direct load
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initMCQEngine);
} else {
  initMCQEngine();
}

// Global exports for cross-module integration
window.mistakes = mistakes;
window.loadMistakes = loadMistakes;
window.renderMistakes = renderMistakes;
window.initMCQEngine = initMCQEngine;
window.loadQuestionBankForQuiz = loadQuestionBankForQuiz;
window.renderQuizLoadingSkeleton = renderQuizLoadingSkeleton;
window.clearQuizLoadingSkeleton = clearQuizLoadingSkeleton;
window.renderMCQFilterBar = renderMCQFilterBar;
window.renderMCQQuestion = renderMCQQuestion;
window.updateMCQStatsBar = updateMCQStatsBar;

/* Source: assets/js/integrations/security.js */
/* ==========================================================================
   CareerDesk — Privacy, Security & Anti-Hacking Engine
   Zero-Knowledge AES-GCM-256 Encryption, Strict XSS Sanitization,
   SHA-256 Checksum Tamper-Proofing & Privacy Screen PIN Lock
   ========================================================================== */

const CAREERDESK_VAULT_CFG_KEY = 'careerdesk_vault_cfg_v1';
const CAREERDESK_PIN_HASH_KEY = 'careerdesk_privacy_pin_hash_v1';
const CAREERDESK_AUTOLOCK_MINS_KEY = 'careerdesk_autolock_minutes_v1';

let lastUserActivityTimestamp = Date.now();
let autoLockIntervalTimer = null;
let isWorkspaceLocked = false;
let currentEnteredPin = '';

// =========================================================
// 1. NATIVE WEB CRYPTO AES-GCM-256 ENCRYPTION ENGINE
// =========================================================

function isWebCryptoSupported() {
  const subtle = (typeof window !== 'undefined' && window.crypto && window.crypto.subtle) || (typeof crypto !== 'undefined' && crypto.subtle);
  return !!subtle;
}

/**
 * Converts ArrayBuffer / Uint8Array to base64 string
 */
function bufferToBase64(buffer) {
  const bytes = buffer instanceof Uint8Array ? buffer : new Uint8Array(buffer);
  if (typeof btoa === 'function') {
    let binary = '';
    for (let i = 0; i < bytes.byteLength; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  }
  return Buffer.from(bytes).toString('base64');
}

/**
 * Converts base64 string to Uint8Array
 */
function base64ToBuffer(base64) {
  if (typeof atob === 'function') {
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i);
    }
    return bytes;
  }
  return new Uint8Array(Buffer.from(base64, 'base64'));
}

/**
 * Computes SHA-256 hexadecimal hash string
 */
async function computeSha256(text) {
  if (!isWebCryptoSupported()) return '';
  const enc = new TextEncoder();
  const hashBuffer = await crypto.subtle.digest('SHA-256', enc.encode(text));
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
}

/**
 * Derives an AES-GCM 256-bit key from user passphrase using PBKDF2
 */
async function deriveKeyFromPassphrase(passphrase, saltBytes) {
  const enc = new TextEncoder();
  const keyMaterial = await crypto.subtle.importKey(
    'raw',
    enc.encode(passphrase),
    { name: 'PBKDF2' },
    false,
    ['deriveKey']
  );

  return await crypto.subtle.deriveKey(
    {
      name: 'PBKDF2',
      salt: saltBytes,
      iterations: 100000,
      hash: 'SHA-256'
    },
    keyMaterial,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt']
  );
}

/**
 * Encrypts any data bundle using Zero-Knowledge AES-GCM 256-bit encryption
 */
async function encryptVaultPayload(dataObj, passphrase) {
  if (!isWebCryptoSupported()) {
    throw new Error('Web Crypto API is not supported in this browser environment.');
  }

  const saltBytes = crypto.getRandomValues(new Uint8Array(16));
  const ivBytes = crypto.getRandomValues(new Uint8Array(12));
  const key = await deriveKeyFromPassphrase(passphrase, saltBytes);

  const jsonStr = JSON.stringify(dataObj);
  const checksum = await computeSha256(jsonStr);

  const enc = new TextEncoder();
  const cipherBuffer = await crypto.subtle.encrypt(
    { name: 'AES-GCM', iv: ivBytes },
    key,
    enc.encode(jsonStr)
  );

  return {
    __careerdesk_vault: true,
    version: 1,
    algorithm: 'AES-GCM-256',
    kdf: 'PBKDF2-SHA256',
    iterations: 100000,
    salt: bufferToBase64(saltBytes),
    iv: bufferToBase64(ivBytes),
    ciphertext: bufferToBase64(cipherBuffer),
    checksum: checksum,
    timestamp: new Date().toISOString()
  };
}

/**
 * Decrypts a vault envelope with passphrase and verifies checksum
 */
async function decryptVaultPayload(envelope, passphrase) {
  if (!isWebCryptoSupported()) {
    throw new Error('Web Crypto API is not supported in this browser environment.');
  }
  if (!envelope || !envelope.__careerdesk_vault || !envelope.ciphertext) {
    throw new Error('Invalid or unencrypted vault file format.');
  }

  const saltBytes = base64ToBuffer(envelope.salt);
  const ivBytes = base64ToBuffer(envelope.iv);
  const cipherBytes = base64ToBuffer(envelope.ciphertext);

  const key = await deriveKeyFromPassphrase(passphrase, saltBytes);

  let decryptedBuffer;
  try {
    decryptedBuffer = await crypto.subtle.decrypt(
      { name: 'AES-GCM', iv: ivBytes },
      key,
      cipherBytes
    );
  } catch (err) {
    throw new Error('Incorrect passphrase. Decryption failed.');
  }

  const dec = new TextDecoder();
  const plaintext = dec.decode(decryptedBuffer);

  // Verify Checksum Integrity
  if (envelope.checksum) {
    const computedCheck = await computeSha256(plaintext);
    if (computedCheck !== envelope.checksum) {
      throw new Error('Security Alert: Checksum mismatch! The data appears tampered or corrupted.');
    }
  }

  return JSON.parse(plaintext);
}

/**
 * Gets the current Vault configuration
 */
function getVaultConfig() {
  try {
    const raw = localStorage.getItem(CAREERDESK_VAULT_CFG_KEY);
    if (raw) return JSON.parse(raw);
  } catch (e) { }
  return { enabled: false, lastConfigured: null };
}

function saveVaultConfig(cfg) {
  try {
    localStorage.setItem(CAREERDESK_VAULT_CFG_KEY, JSON.stringify(cfg));
  } catch (e) { }
}

// =========================================================
// 2. INPUT SANITIZATION & ANTI-XSS DEFENSE
// =========================================================

/**
 * Deep recursive object sanitizer to prevent Prototype Pollution
 */
function scrubPrototypePollution(obj) {
  if (obj === null || typeof obj !== 'object') return obj;
  if (Array.isArray(obj)) {
    return obj.map(scrubPrototypePollution);
  }
  const clean = {};
  for (const key of Object.keys(obj)) {
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
      continue; // Block prototype pollution vectors
    }
    clean[key] = scrubPrototypePollution(obj[key]);
  }
  return clean;
}

/**
 * Sanitizes rich text to prevent XSS execution
 */
function sanitizeHtmlString(str) {
  if (typeof str !== 'string') return '';
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;')
    .replace(/`/g, '&#96;');
}

// =========================================================
// 3. PRIVACY PIN LOCK SCREEN & PANIC BUTTON
// =========================================================

function getPrivacyPinHash() {
  return localStorage.getItem(CAREERDESK_PIN_HASH_KEY);
}

async function setPrivacyPin(pin) {
  if (!pin || pin.length < 4) {
    throw new Error('PIN must be at least 4 digits');
  }
  const hash = await computeSha256(pin);
  localStorage.setItem(CAREERDESK_PIN_HASH_KEY, hash);
}

function removePrivacyPin() {
  localStorage.removeItem(CAREERDESK_PIN_HASH_KEY);
}

function getAutoLockMinutes() {
  const val = localStorage.getItem(CAREERDESK_AUTOLOCK_MINS_KEY);
  return val ? parseInt(val, 10) : 0; // 0 = disabled
}

function setAutoLockMinutes(mins) {
  localStorage.setItem(CAREERDESK_AUTOLOCK_MINS_KEY, String(mins));
  setupAutoLockTimer();
}

/**
 * Lock the dashboard screen immediately
 */
function lockWorkspaceNow() {
  const pinHash = getPrivacyPinHash();
  if (!pinHash) {
    openSetPinModal();
    return;
  }
  isWorkspaceLocked = true;
  currentEnteredPin = '';
  renderLockScreenOverlay();
}

/**
 * Renders the PIN lock overlay
 */
function renderLockScreenOverlay() {
  let overlay = document.getElementById('privacyLockScreen');
  if (!overlay) {
    overlay = document.createElement('div');
    overlay.id = 'privacyLockScreen';
    document.body.appendChild(overlay);
  }

  overlay.innerHTML = `
    <div class="privacy-lock-card">
      <div class="lock-shield-badge">
        <i data-lucide="shield-check" style="width:30px; height:30px;"></i>
      </div>
      <h2 class="lock-title">CareerDesk Locked</h2>
      <p class="lock-sub">Enter your 4-digit Privacy PIN to unlock</p>

      <div class="lock-pin-dots" id="lockPinDots">
        <span class="pin-dot"></span>
        <span class="pin-dot"></span>
        <span class="pin-dot"></span>
        <span class="pin-dot"></span>
      </div>

      <div class="lock-error-msg" id="lockErrorMsg"></div>

      <div class="lock-keypad">
        <button type="button" class="keypad-btn" data-key="1">1</button>
        <button type="button" class="keypad-btn" data-key="2">2</button>
        <button type="button" class="keypad-btn" data-key="3">3</button>
        <button type="button" class="keypad-btn" data-key="4">4</button>
        <button type="button" class="keypad-btn" data-key="5">5</button>
        <button type="button" class="keypad-btn" data-key="6">6</button>
        <button type="button" class="keypad-btn" data-key="7">7</button>
        <button type="button" class="keypad-btn" data-key="8">8</button>
        <button type="button" class="keypad-btn" data-key="9">9</button>
        <button type="button" class="keypad-btn action-btn" id="btnKeypadClear">C</button>
        <button type="button" class="keypad-btn" data-key="0">0</button>
        <button type="button" class="keypad-btn action-btn" id="btnKeypadBack"><i data-lucide="delete"></i></button>
      </div>
    </div>
  `;

  overlay.style.display = 'flex';

  overlay.querySelectorAll('.keypad-btn[data-key]').forEach(btn => {
    btn.addEventListener('click', () => {
      handlePinDigit(btn.getAttribute('data-key'));
    });
  });

  const clearBtn = overlay.querySelector('#btnKeypadClear');
  if (clearBtn) {
    clearBtn.addEventListener('click', () => {
      currentEnteredPin = '';
      updatePinDotsUI();
    });
  }

  const backBtn = overlay.querySelector('#btnKeypadBack');
  if (backBtn) {
    backBtn.addEventListener('click', () => {
      if (currentEnteredPin.length > 0) {
        currentEnteredPin = currentEnteredPin.slice(0, -1);
        updatePinDotsUI();
      }
    });
  }

  if (window.lucide && typeof window.lucide.createIcons === 'function') {
    window.lucide.createIcons();
  }
}

async function handlePinDigit(digit) {
  if (currentEnteredPin.length >= 6) return;
  currentEnteredPin += digit;
  updatePinDotsUI();

  const savedHash = getPrivacyPinHash();
  if (currentEnteredPin.length >= 4) {
    const inputHash = await computeSha256(currentEnteredPin);
    if (inputHash === savedHash) {
      unlockWorkspace();
    } else if (currentEnteredPin.length === 6 || (currentEnteredPin.length === 4 && savedHash.length > 0)) {
      setTimeout(async () => {
        const checkAgain = await computeSha256(currentEnteredPin);
        if (checkAgain === savedHash) {
          unlockWorkspace();
        } else {
          flashPinError('Incorrect PIN. Try again.');
        }
      }, 150);
    }
  }
}

function updatePinDotsUI() {
  const dots = document.querySelectorAll('#lockPinDots .pin-dot');
  dots.forEach((dot, index) => {
    if (index < currentEnteredPin.length) {
      dot.classList.add('filled');
    } else {
      dot.classList.remove('filled');
    }
  });
}

function flashPinError(msg) {
  const errEl = document.getElementById('lockErrorMsg');
  const dotsEl = document.getElementById('lockPinDots');
  if (errEl) errEl.textContent = msg;
  if (dotsEl) {
    dotsEl.classList.add('shake');
    setTimeout(() => dotsEl.classList.remove('shake'), 400);
  }
  currentEnteredPin = '';
  setTimeout(() => {
    updatePinDotsUI();
    if (errEl) errEl.textContent = '';
  }, 1200);
}

function unlockWorkspace() {
  isWorkspaceLocked = false;
  currentEnteredPin = '';
  lastUserActivityTimestamp = Date.now();
  const overlay = document.getElementById('privacyLockScreen');
  if (overlay) {
    overlay.style.display = 'none';
  }
  if (typeof showToast === 'function') {
    showToast('Dashboard unlocked');
  }
}

// Global Activity Listener for Auto-Lock & Keyboard shortcuts
function setupAutoLockTimer() {
  const events = ['mousemove', 'mousedown', 'keydown', 'touchstart', 'scroll'];
  events.forEach(evt => {
    window.addEventListener(evt, () => {
      lastUserActivityTimestamp = Date.now();
    }, { passive: true });
  });

  // Shortcut: Alt + L to lock screen immediately
  window.addEventListener('keydown', (e) => {
    if (e.altKey && (e.key === 'l' || e.key === 'L')) {
      e.preventDefault();
      lockWorkspaceNow();
    }

    // Direct numpad input when lock screen is open
    if (isWorkspaceLocked) {
      if (/^[0-9]$/.test(e.key)) {
        e.preventDefault();
        handlePinDigit(e.key);
      } else if (e.key === 'Backspace') {
        e.preventDefault();
        if (currentEnteredPin.length > 0) {
          currentEnteredPin = currentEnteredPin.slice(0, -1);
          updatePinDotsUI();
        }
      } else if (e.key === 'Escape') {
        e.preventDefault();
        currentEnteredPin = '';
        updatePinDotsUI();
      }
    }
  });

  if (autoLockIntervalTimer) clearInterval(autoLockIntervalTimer);
  autoLockIntervalTimer = setInterval(() => {
    const mins = getAutoLockMinutes();
    if (mins > 0 && !isWorkspaceLocked) {
      const elapsedMs = Date.now() - lastUserActivityTimestamp;
      if (elapsedMs > mins * 60 * 1000) {
        lockWorkspaceNow();
      }
    }
  }, 15000);
}

