                      <span class="home-pillar-icon" style="color: ${p.color}; display:inline-flex; align-items:center; justify-content:center; flex-shrink:0;">
                        <i data-lucide="${meta.icon || 'book-open'}" style="width:14px; height:14px;"></i>
                      </span>
